HT.CDF["G02"] = {"bang":[{"i":0,"tieu_de_bang":"Huế – Kinh thành và trường Quốc Học","tieu_de":"Hơn tám năm ở kinh đô: nơi cậu bé làng Sen nhìn thấu bộ mặt chế độ bảo hộ","sapo":"Cuối năm 1895, một gia đình nhà nho nghèo xứ Nghệ đi bộ nhiều ngày vào kinh, hai đứa trẻ ngồi trong đôi quang gánh. Kinh đô ấy có cung điện, có Kỳ Đài, có nhà vua, nhưng quyền lực thật lại nằm ở một tòa nhà bên kia sông. Qua hai lần sống ở Huế, cậu bé làng Sen mất mẹ, đổi tên, học chữ Tây và lần đầu đứng giữa đoàn người đòi giảm sưu thuế. Gian trưng bày này mở ra từng lát cắt của những năm tháng ấy.","bia":{"src":"textures/bai/G02_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Chuyến đi bộ vào kinh","text":"Cuối năm 1895, trên con đường từ Nghệ An vào Huế, có một gia đình nhỏ lặng lẽ đi về phía nam. Người cha là cử nhân Nguyễn Sinh Sắc, vừa đỗ khoa thi Hương năm Giáp Ngọ 1894 ở trường thi Nghệ An. Người mẹ là bà Hoàng Thị Loan. Đi cùng họ là hai cậu con trai, Nguyễn Sinh Khiêm và Nguyễn Sinh Cung, cậu em khi ấy mới năm tuổi. Người con gái đầu là Nguyễn Thị Thanh được gửi lại quê cho bà ngoại nuôi.\n\nTrước đó, ông Sắc đã vào kinh dự thi Hội nhưng không đỗ. Ông xin vào học Trường Quốc Tử Giám để chuẩn bị cho khoa sau, được nhận rồi mới về quê đón vợ con. Thời ấy giữa Nghệ An và Huế chưa có đường xe lửa, cũng chưa có ô tô. Theo tư liệu của Bảo tàng Hồ Chí Minh, mọi người đều đi bộ; trẻ nhỏ thường được ngồi trong quang gánh, vất vả nhiều ngày dọc đường mới tới kinh đô. Đến nơi, gia đình phải ở nhờ nhà người quen, sau đó ở tạm trong một gian của trại lính gần Viện Đô sát. Đó là cuộc sống của một sĩ tử nghèo nơi đất khách, và cũng là lúc cậu bé Cung bước vào một thế giới khác hẳn làng quê xứ Nghệ.","doc":1},{"loai":"doan","tieu_de":"Tòa thành của các vua Nguyễn","text":"Kinh đô mà cậu bé nhìn thấy là thành quả của gần ba mươi năm xây dựng. Theo Châu bản triều Nguyễn, năm 1805 vua Gia Long cho khởi công đắp Kinh thành ở bờ bắc sông Hương. Phải đến năm Minh Mạng thứ mười ba, tức năm 1832, công trình mới hoàn thành. Kinh thành gồm ba vòng thành lồng nhau là Kinh thành, Hoàng thành và Tử Cấm thành, tất cả đều quay mặt về hướng nam.\n\nVòng ngoài được xây theo lối kiến trúc Vauban của phương Tây, với hai mươi bốn pháo đài bố trí cách đều nhau. Bên ngoài là hệ thống hào và sông bao quanh, vừa để phòng thủ, vừa làm đường thủy. Dòng Ngự Hà chảy vắt ngang lòng thành. Mặt thành phía nam có Kỳ Đài, nơi treo cờ của triều đình. Bên trong vòng thành ngoài là khu Thành Nội, có dinh thự các bộ, các nha môn và những xóm nhà dân chen chúc. Sĩ tử các tỉnh vào kinh ôn thi thường tìm chỗ trọ ở đây. Với một đứa trẻ quen lũy tre, ao sen và cánh đồng Nam Đàn, những bức tường thành cao và dày ấy là một cảnh tượng hoàn toàn mới lạ.","doc":2},{"loai":"ban_co_biet","text":"Kinh thành Huế có mười cửa chính thông ra ngoài, thêm một cửa thông tới Trấn Bình đài và hai cửa thủy quan ở phía đông và phía tây trên dòng Ngự Hà.","nguon_ten":"Trung tâm Lưu trữ quốc gia I – Kinh thành Huế: dấu xưa còn lại (archives.org.vn)","doc":3},{"loai":"anh","src":"textures/bang_w/G02_0_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Huế – Kinh thành và trường Quốc Học”, nhìn từ xa."},{"loai":"doan","tieu_de":"Mười năm sau ngày thất thủ","text":"Nhưng vẻ uy nghi ấy chỉ còn là vỏ ngoài. Ngày 6/6/1884, triều Nguyễn buộc phải ký Hòa ước Patenôtre, thừa nhận chế độ bảo hộ của Pháp. Đêm 4 rạng ngày 5/7/1885, tức ngày 23 tháng Năm năm Ất Dậu, cuộc tấn công của phái chủ chiến vào quân Pháp thất bại. Quân Pháp tràn vào Kinh thành, hàng nghìn người dân vô tội thiệt mạng. Vua Hàm Nghi rời kinh, phong trào Cần Vương bùng lên ở nhiều nơi. Người Huế gọi biến cố ấy là ngày thất thủ Kinh đô.\n\nKhi gia đình ông Sắc vào kinh, sự kiện ấy mới lùi xa mười năm. Theo tư liệu giới thiệu về ngôi nhà lưu niệm ở đường Mai Thúc Loan, câu chuyện thất thủ Kinh đô đã in sâu trong ký ức tuổi thơ cậu bé Cung. Lúc này trên ngai vàng là vua Thành Thái, lên ngôi năm 1889 khi mới mười tuổi. Những việc hệ trọng, từ thuế khóa, quân đội cho đến việc lập hay phế một ông vua, đều phải qua tay người Pháp. Hai bờ sông Hương vì thế như hai thế giới: bờ bắc là triều đình của nhà vua, bờ nam là bộ máy cai trị của chính quyền bảo hộ.","doc":4},{"loai":"doan","tieu_de":"Bên kia sông: khu phố của người Pháp","text":"Theo hiệp ước năm 1874, triều đình phải để người Pháp dựng một tòa sứ ở bờ nam sông Hương. Tòa nhà xây xong năm 1878, về sau được nâng cấp và gọi là Tòa Khâm sứ Trung Kỳ. Sau năm 1885, người Pháp ép triều đình nhường thêm đất xung quanh. Từ một khoảnh nhượng địa ban đầu mỗi bề chừng hai trăm mét, dọc bờ nam lần lượt mọc lên trại lính, nhà dây thép, nhà thương, kho bạc, nhà băng, khách sạn và các trường học kiểu mới, trong đó có Trường Quốc Học.\n\nNăm 1899, cây cầu thép mà người Huế quen gọi là cầu Trường Tiền được xây dựng xong, nối hai bờ sông (xem chuyên đề Cầu Trường Tiền và sông Hương). Nhà nghiên cứu Phan Thuận An nhận xét rằng người Pháp đặt các công sở lùi xa mép nước, sau những thảm cỏ và hàng cây, để không lấn át cảnh sắc cổ kính bên kia sông. Nhưng sự hài hòa về kiến trúc không che được sự bất bình đẳng về quyền lực. Một người dân đi từ Thành Nội sang bờ nam là đi qua đúng lằn ranh ấy: từ kinh đô cũ đang mất dần thực quyền sang trung tâm của chính quyền bảo hộ.","doc":5},{"loai":"ban_co_biet","text":"Khu đất của Tòa Khâm sứ Trung Kỳ, nơi nông dân Thừa Thiên kéo đến đòi giảm thuế năm 1908, nay thuộc Trường Đại học Sư phạm Huế.","nguon_ten":"Phan Thuận An – Kiến trúc Khu phố Tây ở Huế thời Pháp thuộc, Tạp chí Sông Hương, 2017","doc":6},{"loai":"doan","tieu_de":"Chặng thứ nhất: sĩ tử nghèo trong Thành Nội","text":"Chặng đầu ở Huế kéo dài hơn năm năm, từ cuối năm 1895 đến đầu năm 1901. Sau những ngày ở tạm, gia đình được ở nhờ nhà một người quen trong Thành Nội, nay là ngôi nhà lưu niệm trên đường Mai Thúc Loan. Ông Sắc ngoài giờ học phải đi chép chữ thuê để kiếm sống. Bà Loan làm nghề dệt vải. Năm 1898, ông thi Hội lần thứ hai vẫn không đỗ, cuộc sống càng thêm chật vật. Gần cuối năm ấy, nhận lời mời của ông Nguyễn Sĩ Độ, ông về dạy học ở làng Dương Nỗ, cách trung tâm Huế khoảng sáu cây số. Hai con trai theo cha, và ở lớp học nhỏ ấy, cậu bé Cung bắt đầu học chữ Hán.\n\nTheo cuốn tiểu sử do Bảo tàng Hồ Chí Minh biên soạn, những năm ấy cậu bé thấy ở Huế nhiều lớp người khác nhau. Có những người Pháp thống trị nghênh ngang, hách dịch. Có những ông quan Nam triều bệ vệ trong áo gấm, hài nhung, mũ cánh chuồn nhưng khúm núm, rụt rè. Còn phần đông là người lao động nghèo: phu khuân vác, phu kéo xe tay, trẻ em lang thang trên đường phố. Chặng này khép lại bằng một mất mát lớn: ngày 10/2/1901, bà Hoàng Thị Loan qua đời giữa kinh thành (xem chuyên đề Mất mẹ giữa kinh thành).","doc":7},{"loai":"ban_co_biet","text":"Lớp học ở làng Dương Nỗ, nơi cậu bé Nguyễn Sinh Cung học những chữ Hán đầu tiên, đặt trong ngôi nhà của ông Nguyễn Sĩ Khuyến, em trai ông Nguyễn Sĩ Độ, người đã mời ông Nguyễn Sinh Sắc về dạy học.","nguon_ten":"Bảo tàng Hồ Chí Minh – Hồ Chí Minh: Tiểu sử, NXB Chính trị quốc gia, 2008","doc":8},{"loai":"anh","src":"textures/bang_w/G02_0_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Huế – Kinh thành và trường Quốc Học”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Năm năm ở quê và một cái tên mới","text":"Được tin vợ mất, ông Sắc vội trở lại Huế, đưa các con về quê. Được bà con trong họ ngoài làng động viên, ông lại vào kinh dự khoa thi Hội năm Tân Sửu, lần này với tên mới là Nguyễn Sinh Huy. Tháng 5/1901, ông đỗ Phó bảng. Khoảng tháng 9 năm ấy, cả nhà về sống ở quê nội làng Kim Liên. Trong lễ vào làng, hai con trai được đặt tên mới: Nguyễn Sinh Khiêm thành Nguyễn Tất Đạt, Nguyễn Sinh Cung thành Nguyễn Tất Thành.\n\nNăm năm tiếp theo, người thiếu niên học chữ Hán ở quê với các thầy đồ, lớn lên giữa những câu chuyện thời thế của các nhà nho yêu nước xứ Nghệ. Ông Phó bảng thì lần lữa nhiều năm, chưa chịu ra làm quan. Khi trở lại Huế, người thiếu niên đã mười sáu tuổi, mang theo một cái tên chứa đựng ước vọng của người cha: tất thành, nghĩa là ắt sẽ thành công.","doc":9},{"loai":"doan","tieu_de":"Chặng thứ hai: con quan Thừa biện đi học chữ Tây","text":"Cuối tháng 5/1906, ông Nguyễn Sinh Huy vào kinh nhận chức Thừa biện Bộ Lễ, đưa hai con trai đi cùng. Ông được cấp một căn phòng trong khu nhà dành cho thuộc viên các bộ, thường gọi là Dãy Trại, trên đường Đông Ba, nay là đường Mai Thúc Loan. Tháng 9/1906, hai anh em vào học Trường tiểu học Pháp – Việt Đông Ba, nằm ngay sát ngoài cửa Đông Ba, cách nhà chừng hai trăm mét. Đây là bước ngoặt lớn: từ chữ Hán của cửa Khổng sân Trình, người thiếu niên bắt đầu học chữ quốc ngữ và tiếng Pháp.\n\nNhà nghiên cứu Nguyễn Đắc Xuân đã tìm gặp những người bạn học cũ của anh ở trường Đông Ba. Nhà giáo Lê Thiện, người làng Phú Lương, kể rằng lúc mới vào trường, anh còn để tóc chỏm, đội nón tre sơn xứ Nghệ, mặc áo quần vải thô nhuộm nâu, đi guốc gỗ quai mây. Chỉ mấy tuần sau, anh đã cắt tóc ngắn, mặc quần trắng, áo đen, đội nón lá như người kinh đô. Trong giấy tờ ở Huế, anh mang tên Nguyễn Sinh Côn, nên bạn bè gọi là trò Côn. Người bạn học ấy còn giữ một ấn tượng rõ nét về cách học của anh.","doc":10},{"loai":"trich","text":"Côn học giỏi nhưng không học “gạo”. Học môn gì anh cũng hỏi cặn kẽ. Nếu thầy trả lời không thỏa mãn, anh hỏi đến khi ngã ngũ mới thôi. Hán văn anh giỏi nhất lớp. Pháp văn không có trò Nghệ nào bằng anh.","nguoi":"Nhà giáo Lê Thiện, bạn học ở Trường tiểu học Pháp – Việt Đông Ba","nguon_ten":"Nguyễn Đắc Xuân, Đi tìm dấu tích thời niên thiếu của Bác Hồ ở Huế; dẫn theo Tuổi Trẻ Online, 13/2/2018","doc":11},{"loai":"doan","tieu_de":"Kinh đô chao đảo, học trò thức tỉnh","text":"Những năm Tất Thành đi học cũng là những năm kinh đô chao đảo. Mùa thu năm 1907, chính quyền bảo hộ buộc vua Thành Thái thoái vị và đưa người con trai còn nhỏ tuổi của ông lên ngôi, lấy niên hiệu Duy Tân. Cùng thời gian ấy, phong trào Duy Tân của các nhà nho yêu nước lan rộng ở Trung Kỳ, với việc mở trường, diễn thuyết, cắt tóc ngắn, mặc áo ngắn. Theo cuốn tiểu sử của Bảo tàng Hồ Chí Minh, ở Huế người thiếu niên được nghe kể về những hành động của các ông vua yêu nước như Thành Thái, Duy Tân, và nghe các sĩ phu bàn luận về con đường cứu nước.\n\nMùa xuân năm 1908, làn sóng chống sưu thuế từ Quảng Nam lan ra đến kinh đô. Tháng 4/1908, khi nông dân Thừa Thiên kéo đến Tòa Khâm sứ, người học trò trường Đông Ba đã đi cùng họ và đứng ra làm thông ngôn (xem chuyên đề Người phiên dịch cho đoàn nông dân). Từ đó, anh bị thực dân Pháp để ý theo dõi. Ông Nguyễn Sinh Huy cũng bị chúng khiển trách vì đã để con trai có những hoạt động bài Pháp.","doc":12},{"loai":"anh","src":"textures/bang_w/G02_0_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Huế – Kinh thành và trường Quốc Học”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dưới mái tranh Trường Quốc Học","text":"Dù đã bị để ý, tháng 8/1908 anh vẫn được Hiệu trưởng Quốc Học là ông Chouquet tiếp nhận vào học, dưới tên Nguyễn Sinh Côn. Tháng 9/1908, anh vào lớp trung đẳng của trường. Quốc Học khi ấy chưa có những dãy nhà gạch sơn đỏ quen thuộc hôm nay. Các lớp học còn là những dãy nhà tranh vách đất; dãy nhà gạch chỉ được xây từ năm 1915. Ông Lê Thanh Cảnh, một bạn học, về sau đặt tên cho bài hồi ký của mình là Dưới mái tranh Trường Quốc Học những năm 1906 – 1911.\n\nỞ đây, anh được tiếp xúc nhiều với sách báo Pháp. Thầy giáo có người Pháp, có người Việt, trong đó có những người yêu nước như thầy Hoàng Thông, thầy Lê Văn Miến. Theo lời họa sĩ Tôn Thất Sa, một thầy giáo Quốc Học đời sau, kể với nhà nghiên cứu Nguyễn Đắc Xuân, thầy dạy vẽ Lê Văn Miến hay dành thời gian kể cho học trò nghe về nước Pháp. Trò Côn thích nghe chuyện hơn học vẽ, và có lần hỏi thầy làm sao để sang Pháp xem người Pháp sống ra sao. Khoảng tháng 6/1909, anh rời trường, theo cha vào Bình Định khi ông được bổ làm Tri huyện Bình Khê.","doc":13},{"loai":"doan","tieu_de":"Những câu hỏi mang theo từ kinh đô","text":"Cộng lại, Nguyễn Sinh Cung, rồi Nguyễn Tất Thành, đã sống ở Huế hơn tám năm, qua hai chặng cách nhau năm năm. Những năm ấy để lại trong con người anh nhiều lớp trầm tích. Đó là nỗi đau mất mẹ và mất em giữa đất khách. Đó là cảnh nghèo của một gia đình sĩ tử, là hình ảnh người lao động lam lũ ngay dưới chân thành. Đó còn là hai nền học: chữ Hán ở lớp học Dương Nỗ, chữ Pháp ở trường Đông Ba và Quốc Học. Và trên hết là cảnh một triều đình có vua, có kinh đô mà không giữ nổi chủ quyền, bên cạnh những người nông dân chỉ biết dựa vào nhau để đòi bớt gánh sưu thuế.\n\nCuốn tiểu sử của Bảo tàng Hồ Chí Minh nhận định rằng Nguyễn Tất Thành rất khâm phục các bậc tiền bối, nhưng không đi theo con đường của họ. Thất bại của các phong trào yêu nước đầu thế kỷ XX đã đặt ra nhiều câu hỏi, để rồi anh quyết định ra nước ngoài tìm đường cứu nước. Rời Huế năm 1909, anh dạy học ở Trường Dục Thanh, Phan Thiết, rồi vào Sài Gòn. Ngày 5/6/1911, anh rời Bến Nhà Rồng trên tàu Amiral Latouche-Tréville.","doc":14},{"loai":"anh","src":"textures/ht/ht_anh_quoc_hoc_hue.jpg","chu_thich":"Trường Quốc Học Huế bên bờ sông Hương, ảnh chụp năm 2008.","credit":"Ảnh: Lưu Ly · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, những năm tháng ấy vẫn để lại dấu vết rõ ràng trên đất Huế. Ngôi nhà trong Thành Nội nơi gia đình ở chặng thứ nhất nay là nhà lưu niệm trên đường Mai Thúc Loan. Đó là một ngôi nhà gỗ ba gian kiểu nhà rường truyền thống, mái lợp ngói, bên trong trưng bày khung cửi gợi nhớ những ngày bà Hoàng Thị Loan dệt vải nuôi chồng con. Ở làng Dương Nỗ là ngôi nhà tranh ba gian hai chái, nơi ông Sắc từng ngồi trên bộ phản gỗ dạy học trò. Theo Quyết định số 2280/QĐ-TTg ngày 31/12/2020 của Thủ tướng Chính phủ, hai ngôi nhà được xếp hạng di tích quốc gia đặc biệt.\n\nNơi an táng ban đầu của bà Hoàng Thị Loan trên núi Bân có nhà bia tưởng niệm (xem chuyên đề Mất mẹ giữa kinh thành). Bên bờ nam sông Hương, Trường Quốc Học vẫn đón học trò, với tượng người học trò Nguyễn Tất Thành giữa sân trường (xem chuyên đề Tượng học trò Nguyễn Tất Thành ở Trường Quốc Học). Khu đất Tòa Khâm sứ năm xưa nay thuộc Trường Đại học Sư phạm Huế. Còn Kinh thành, Kỳ Đài và Đại Nội nằm trong Quần thể di tích Cố đô Huế, được UNESCO công nhận là di sản văn hóa thế giới năm 1993.","doc":15}],"nguon":["Bảo tàng Hồ Chí Minh – Hồ Chí Minh: Tiểu sử, NXB Chính trị quốc gia, Hà Nội, 2008 (bản điện tử: https://tulieuvankien.dangcongsan.vn/c-mac-angghen-lenin-ho-chi-minh/book/ho-chi-minh/tieu-su-cuoc-doi-va-su-nghiep/ho-chi-minh-tieu-su-bao-tang-ho-chi-minh-nxb-chinh-tri-quoc-gia-ha-noi-nam-2008-20)","Bảo tàng Hồ Chí Minh – Nguyễn Sinh Cung cùng anh theo cha mẹ vào Huế: https://baotanghochiminh.vn/nguyen-sinh-cung-cung-anh-theo-cha-me-vao-hue.htm","Trung tâm Lưu trữ quốc gia I – Kinh thành Huế: dấu xưa còn lại: https://archives.org.vn/tin-hoat-dong/kinh-thanh-hue-dau-xua-con-lai.htm","Phan Thuận An – Kiến trúc Khu phố Tây ở Huế thời Pháp thuộc, Tạp chí Sông Hương, 2017: http://tapchisonghuong.com.vn/tap-chi/c375/n25741/Kien-truc-Khu-pho-Tay-o-Hue-thoi-Phap-thuoc.html","Minh Đăng – Nguyễn Tất Thành ra đi từ ngôi trường xứ Huế, Tuổi Trẻ Online, 13/2/2018: https://tuoitre.vn/nguyen-tat-thanh-ra-di-tu-ngoi-truong-xu-hue-20180205104555229.htm","Báo Dân trí – Chuyện chưa kể về 2 ngôi nhà gắn với năm tháng ấu thơ của Bác Hồ tại Huế, 17/1/2021: https://dantri.com.vn/du-lich/chuyen-chua-ke-ve-2-ngoi-nha-gan-voi-nam-thang-au-tho-cua-bac-ho-tai-hue-20210117161721895.htm"],"doc":[{"t":"Hơn tám năm ở kinh đô: nơi cậu bé làng Sen nhìn thấu bộ mặt chế độ bảo hộ. Cuối năm 1895, một gia đình nhà nho nghèo xứ Nghệ đi bộ nhiều ngày vào kinh, hai đứa trẻ ngồi trong đôi quang gánh. Kinh đô ấy có cung điện, có Kỳ Đài, có nhà vua, nhưng quyền lực thật lại nằm ở một tòa nhà bên kia sông. Qua hai lần sống ở Huế, cậu bé làng Sen mất mẹ, đổi tên, học chữ Tây và lần đầu đứng giữa đoàn người đòi giảm sưu thuế. Gian trưng bày này mở ra từng lát cắt của những năm tháng ấy."},{"t":"Chuyến đi bộ vào kinh. Cuối năm 1895, trên con đường từ Nghệ An vào Huế, có một gia đình nhỏ lặng lẽ đi về phía nam. Người cha là cử nhân Nguyễn Sinh Sắc, vừa đỗ khoa thi Hương năm Giáp Ngọ 1894 ở trường thi Nghệ An. Người mẹ là bà Hoàng Thị Loan. Đi cùng họ là hai cậu con trai, Nguyễn Sinh Khiêm và Nguyễn Sinh Cung, cậu em khi ấy mới năm tuổi. Người con gái đầu là Nguyễn Thị Thanh được gửi lại quê cho bà ngoại nuôi. Trước đó, ông Sắc đã vào kinh dự thi Hội nhưng không đỗ. Ông xin vào học Trường Quốc Tử Giám để chuẩn bị cho khoa sau, được nhận rồi mới về quê đón vợ con. Thời ấy giữa Nghệ An và Huế chưa có đường xe lửa, cũng chưa có ô tô. Theo tư liệu của Bảo tàng Hồ Chí Minh, mọi người đều đi bộ; trẻ nhỏ thường được ngồi trong quang gánh, vất vả nhiều ngày dọc đường mới tới kinh đô. Đến nơi, gia đình phải ở nhờ nhà người quen, sau đó ở tạm trong một gian của trại lính gần Viện Đô sát. Đó là cuộc sống của một sĩ tử nghèo nơi đất khách, và cũng là lúc cậu bé Cung bước vào một thế giới khác hẳn làng quê xứ Nghệ."},{"t":"Tòa thành của các vua Nguyễn. Kinh đô mà cậu bé nhìn thấy là thành quả của gần ba mươi năm xây dựng. Theo Châu bản triều Nguyễn, năm 1805 vua Gia Long cho khởi công đắp Kinh thành ở bờ bắc sông Hương. Phải đến năm Minh Mạng thứ mười ba, tức năm 1832, công trình mới hoàn thành. Kinh thành gồm ba vòng thành lồng nhau là Kinh thành, Hoàng thành và Tử Cấm thành, tất cả đều quay mặt về hướng nam. Vòng ngoài được xây theo lối kiến trúc Vauban của phương Tây, với hai mươi bốn pháo đài bố trí cách đều nhau. Bên ngoài là hệ thống hào và sông bao quanh, vừa để phòng thủ, vừa làm đường thủy. Dòng Ngự Hà chảy vắt ngang lòng thành. Mặt thành phía nam có Kỳ Đài, nơi treo cờ của triều đình. Bên trong vòng thành ngoài là khu Thành Nội, có dinh thự các bộ, các nha môn và những xóm nhà dân chen chúc. Sĩ tử các tỉnh vào kinh ôn thi thường tìm chỗ trọ ở đây. Với một đứa trẻ quen lũy tre, ao sen và cánh đồng Nam Đàn, những bức tường thành cao và dày ấy là một cảnh tượng hoàn toàn mới lạ."},{"t":"Bạn có biết? Kinh thành Huế có mười cửa chính thông ra ngoài, thêm một cửa thông tới Trấn Bình đài và hai cửa thủy quan ở phía đông và phía tây trên dòng Ngự Hà."},{"t":"Mười năm sau ngày thất thủ. Nhưng vẻ uy nghi ấy chỉ còn là vỏ ngoài. Ngày 6/6/1884, triều Nguyễn buộc phải ký Hòa ước Patenôtre, thừa nhận chế độ bảo hộ của Pháp. Đêm 4 rạng ngày 5/7/1885, tức ngày 23 tháng Năm năm Ất Dậu, cuộc tấn công của phái chủ chiến vào quân Pháp thất bại. Quân Pháp tràn vào Kinh thành, hàng nghìn người dân vô tội thiệt mạng. Vua Hàm Nghi rời kinh, phong trào Cần Vương bùng lên ở nhiều nơi. Người Huế gọi biến cố ấy là ngày thất thủ Kinh đô. Khi gia đình ông Sắc vào kinh, sự kiện ấy mới lùi xa mười năm. Theo tư liệu giới thiệu về ngôi nhà lưu niệm ở đường Mai Thúc Loan, câu chuyện thất thủ Kinh đô đã in sâu trong ký ức tuổi thơ cậu bé Cung. Lúc này trên ngai vàng là vua Thành Thái, lên ngôi năm 1889 khi mới mười tuổi. Những việc hệ trọng, từ thuế khóa, quân đội cho đến việc lập hay phế một ông vua, đều phải qua tay người Pháp. Hai bờ sông Hương vì thế như hai thế giới: bờ bắc là triều đình của nhà vua, bờ nam là bộ máy cai trị của chính quyền bảo hộ."},{"t":"Bên kia sông: khu phố của người Pháp. Theo hiệp ước năm 1874, triều đình phải để người Pháp dựng một tòa sứ ở bờ nam sông Hương. Tòa nhà xây xong năm 1878, về sau được nâng cấp và gọi là Tòa Khâm sứ Trung Kỳ. Sau năm 1885, người Pháp ép triều đình nhường thêm đất xung quanh. Từ một khoảnh nhượng địa ban đầu mỗi bề chừng hai trăm mét, dọc bờ nam lần lượt mọc lên trại lính, nhà dây thép, nhà thương, kho bạc, nhà băng, khách sạn và các trường học kiểu mới, trong đó có Trường Quốc Học. Năm 1899, cây cầu thép mà người Huế quen gọi là cầu Trường Tiền được xây dựng xong, nối hai bờ sông (xem chuyên đề Cầu Trường Tiền và sông Hương). Nhà nghiên cứu Phan Thuận An nhận xét rằng người Pháp đặt các công sở lùi xa mép nước, sau những thảm cỏ và hàng cây, để không lấn át cảnh sắc cổ kính bên kia sông. Nhưng sự hài hòa về kiến trúc không che được sự bất bình đẳng về quyền lực. Một người dân đi từ Thành Nội sang bờ nam là đi qua đúng lằn ranh ấy: từ kinh đô cũ đang mất dần thực quyền sang trung tâm của chính quyền bảo hộ."},{"t":"Bạn có biết? Khu đất của Tòa Khâm sứ Trung Kỳ, nơi nông dân Thừa Thiên kéo đến đòi giảm thuế năm 1908, nay thuộc Trường Đại học Sư phạm Huế."},{"t":"Chặng thứ nhất: sĩ tử nghèo trong Thành Nội. Chặng đầu ở Huế kéo dài hơn năm năm, từ cuối năm 1895 đến đầu năm 1901. Sau những ngày ở tạm, gia đình được ở nhờ nhà một người quen trong Thành Nội, nay là ngôi nhà lưu niệm trên đường Mai Thúc Loan. Ông Sắc ngoài giờ học phải đi chép chữ thuê để kiếm sống. Bà Loan làm nghề dệt vải. Năm 1898, ông thi Hội lần thứ hai vẫn không đỗ, cuộc sống càng thêm chật vật. Gần cuối năm ấy, nhận lời mời của ông Nguyễn Sĩ Độ, ông về dạy học ở làng Dương Nỗ, cách trung tâm Huế khoảng sáu cây số. Hai con trai theo cha, và ở lớp học nhỏ ấy, cậu bé Cung bắt đầu học chữ Hán. Theo cuốn tiểu sử do Bảo tàng Hồ Chí Minh biên soạn, những năm ấy cậu bé thấy ở Huế nhiều lớp người khác nhau. Có những người Pháp thống trị nghênh ngang, hách dịch. Có những ông quan Nam triều bệ vệ trong áo gấm, hài nhung, mũ cánh chuồn nhưng khúm núm, rụt rè. Còn phần đông là người lao động nghèo: phu khuân vác, phu kéo xe tay, trẻ em lang thang trên đường phố. Chặng này khép lại bằng một mất mát lớn: ngày 10/2/1901, bà Hoàng Thị Loan qua đời giữa kinh thành (xem chuyên đề Mất mẹ giữa kinh thành)."},{"t":"Bạn có biết? Lớp học ở làng Dương Nỗ, nơi cậu bé Nguyễn Sinh Cung học những chữ Hán đầu tiên, đặt trong ngôi nhà của ông Nguyễn Sĩ Khuyến, em trai ông Nguyễn Sĩ Độ, người đã mời ông Nguyễn Sinh Sắc về dạy học."},{"t":"Năm năm ở quê và một cái tên mới. Được tin vợ mất, ông Sắc vội trở lại Huế, đưa các con về quê. Được bà con trong họ ngoài làng động viên, ông lại vào kinh dự khoa thi Hội năm Tân Sửu, lần này với tên mới là Nguyễn Sinh Huy. Tháng 5/1901, ông đỗ Phó bảng. Khoảng tháng 9 năm ấy, cả nhà về sống ở quê nội làng Kim Liên. Trong lễ vào làng, hai con trai được đặt tên mới: Nguyễn Sinh Khiêm thành Nguyễn Tất Đạt, Nguyễn Sinh Cung thành Nguyễn Tất Thành. Năm năm tiếp theo, người thiếu niên học chữ Hán ở quê với các thầy đồ, lớn lên giữa những câu chuyện thời thế của các nhà nho yêu nước xứ Nghệ. Ông Phó bảng thì lần lữa nhiều năm, chưa chịu ra làm quan. Khi trở lại Huế, người thiếu niên đã mười sáu tuổi, mang theo một cái tên chứa đựng ước vọng của người cha: tất thành, nghĩa là ắt sẽ thành công."},{"t":"Chặng thứ hai: con quan Thừa biện đi học chữ Tây. Cuối tháng 5/1906, ông Nguyễn Sinh Huy vào kinh nhận chức Thừa biện Bộ Lễ, đưa hai con trai đi cùng. Ông được cấp một căn phòng trong khu nhà dành cho thuộc viên các bộ, thường gọi là Dãy Trại, trên đường Đông Ba, nay là đường Mai Thúc Loan. Tháng 9/1906, hai anh em vào học Trường tiểu học Pháp – Việt Đông Ba, nằm ngay sát ngoài cửa Đông Ba, cách nhà chừng hai trăm mét. Đây là bước ngoặt lớn: từ chữ Hán của cửa Khổng sân Trình, người thiếu niên bắt đầu học chữ quốc ngữ và tiếng Pháp. Nhà nghiên cứu Nguyễn Đắc Xuân đã tìm gặp những người bạn học cũ của anh ở trường Đông Ba. Nhà giáo Lê Thiện, người làng Phú Lương, kể rằng lúc mới vào trường, anh còn để tóc chỏm, đội nón tre sơn xứ Nghệ, mặc áo quần vải thô nhuộm nâu, đi guốc gỗ quai mây. Chỉ mấy tuần sau, anh đã cắt tóc ngắn, mặc quần trắng, áo đen, đội nón lá như người kinh đô. Trong giấy tờ ở Huế, anh mang tên Nguyễn Sinh Côn, nên bạn bè gọi là trò Côn. Người bạn học ấy còn giữ một ấn tượng rõ nét về cách học của anh."},{"t":"Côn học giỏi nhưng không học “gạo”. Học môn gì anh cũng hỏi cặn kẽ. Nếu thầy trả lời không thỏa mãn, anh hỏi đến khi ngã ngũ mới thôi. Hán văn anh giỏi nhất lớp. Pháp văn không có trò Nghệ nào bằng anh. — Nhà giáo Lê Thiện, bạn học ở Trường tiểu học Pháp – Việt Đông Ba"},{"t":"Kinh đô chao đảo, học trò thức tỉnh. Những năm Tất Thành đi học cũng là những năm kinh đô chao đảo. Mùa thu năm 1907, chính quyền bảo hộ buộc vua Thành Thái thoái vị và đưa người con trai còn nhỏ tuổi của ông lên ngôi, lấy niên hiệu Duy Tân. Cùng thời gian ấy, phong trào Duy Tân của các nhà nho yêu nước lan rộng ở Trung Kỳ, với việc mở trường, diễn thuyết, cắt tóc ngắn, mặc áo ngắn. Theo cuốn tiểu sử của Bảo tàng Hồ Chí Minh, ở Huế người thiếu niên được nghe kể về những hành động của các ông vua yêu nước như Thành Thái, Duy Tân, và nghe các sĩ phu bàn luận về con đường cứu nước. Mùa xuân năm 1908, làn sóng chống sưu thuế từ Quảng Nam lan ra đến kinh đô. Tháng 4/1908, khi nông dân Thừa Thiên kéo đến Tòa Khâm sứ, người học trò trường Đông Ba đã đi cùng họ và đứng ra làm thông ngôn (xem chuyên đề Người phiên dịch cho đoàn nông dân). Từ đó, anh bị thực dân Pháp để ý theo dõi. Ông Nguyễn Sinh Huy cũng bị chúng khiển trách vì đã để con trai có những hoạt động bài Pháp."},{"t":"Dưới mái tranh Trường Quốc Học. Dù đã bị để ý, tháng 8/1908 anh vẫn được Hiệu trưởng Quốc Học là ông Chouquet tiếp nhận vào học, dưới tên Nguyễn Sinh Côn. Tháng 9/1908, anh vào lớp trung đẳng của trường. Quốc Học khi ấy chưa có những dãy nhà gạch sơn đỏ quen thuộc hôm nay. Các lớp học còn là những dãy nhà tranh vách đất; dãy nhà gạch chỉ được xây từ năm 1915. Ông Lê Thanh Cảnh, một bạn học, về sau đặt tên cho bài hồi ký của mình là Dưới mái tranh Trường Quốc Học những năm 1906 – 1911. Ở đây, anh được tiếp xúc nhiều với sách báo Pháp. Thầy giáo có người Pháp, có người Việt, trong đó có những người yêu nước như thầy Hoàng Thông, thầy Lê Văn Miến. Theo lời họa sĩ Tôn Thất Sa, một thầy giáo Quốc Học đời sau, kể với nhà nghiên cứu Nguyễn Đắc Xuân, thầy dạy vẽ Lê Văn Miến hay dành thời gian kể cho học trò nghe về nước Pháp. Trò Côn thích nghe chuyện hơn học vẽ, và có lần hỏi thầy làm sao để sang Pháp xem người Pháp sống ra sao. Khoảng tháng 6/1909, anh rời trường, theo cha vào Bình Định khi ông được bổ làm Tri huyện Bình Khê."},{"t":"Những câu hỏi mang theo từ kinh đô. Cộng lại, Nguyễn Sinh Cung, rồi Nguyễn Tất Thành, đã sống ở Huế hơn tám năm, qua hai chặng cách nhau năm năm. Những năm ấy để lại trong con người anh nhiều lớp trầm tích. Đó là nỗi đau mất mẹ và mất em giữa đất khách. Đó là cảnh nghèo của một gia đình sĩ tử, là hình ảnh người lao động lam lũ ngay dưới chân thành. Đó còn là hai nền học: chữ Hán ở lớp học Dương Nỗ, chữ Pháp ở trường Đông Ba và Quốc Học. Và trên hết là cảnh một triều đình có vua, có kinh đô mà không giữ nổi chủ quyền, bên cạnh những người nông dân chỉ biết dựa vào nhau để đòi bớt gánh sưu thuế. Cuốn tiểu sử của Bảo tàng Hồ Chí Minh nhận định rằng Nguyễn Tất Thành rất khâm phục các bậc tiền bối, nhưng không đi theo con đường của họ. Thất bại của các phong trào yêu nước đầu thế kỷ XX đã đặt ra nhiều câu hỏi, để rồi anh quyết định ra nước ngoài tìm đường cứu nước. Rời Huế năm 1909, anh dạy học ở Trường Dục Thanh, Phan Thiết, rồi vào Sài Gòn. Ngày 5/6/1911, anh rời Bến Nhà Rồng trên tàu Amiral Latouche-Tréville."},{"t":"Dấu tích hôm nay. Ngày nay, những năm tháng ấy vẫn để lại dấu vết rõ ràng trên đất Huế. Ngôi nhà trong Thành Nội nơi gia đình ở chặng thứ nhất nay là nhà lưu niệm trên đường Mai Thúc Loan. Đó là một ngôi nhà gỗ ba gian kiểu nhà rường truyền thống, mái lợp ngói, bên trong trưng bày khung cửi gợi nhớ những ngày bà Hoàng Thị Loan dệt vải nuôi chồng con. Ở làng Dương Nỗ là ngôi nhà tranh ba gian hai chái, nơi ông Sắc từng ngồi trên bộ phản gỗ dạy học trò. Theo Quyết định số 2280/QĐ-TTg ngày 31/12/2020 của Thủ tướng Chính phủ, hai ngôi nhà được xếp hạng di tích quốc gia đặc biệt. Nơi an táng ban đầu của bà Hoàng Thị Loan trên núi Bân có nhà bia tưởng niệm (xem chuyên đề Mất mẹ giữa kinh thành). Bên bờ nam sông Hương, Trường Quốc Học vẫn đón học trò, với tượng người học trò Nguyễn Tất Thành giữa sân trường (xem chuyên đề Tượng học trò Nguyễn Tất Thành ở Trường Quốc Học). Khu đất Tòa Khâm sứ năm xưa nay thuộc Trường Đại học Sư phạm Huế. Còn Kinh thành, Kỳ Đài và Đại Nội nằm trong Quần thể di tích Cố đô Huế, được UNESCO công nhận là di sản văn hóa thế giới năm 1993."}],"so_chu":2590},{"i":1,"tieu_de_bang":"Mất mẹ giữa kinh thành (1901)","tieu_de":"Tháng Chạp năm Canh Tý: cậu bé mười một tuổi bồng em đi xin sữa giữa kinh thành","sapo":"Ngày 22 tháng Chạp năm Canh Tý, tức 10/2/1901, khi kinh đô đang sửa soạn đón Tết, một người mẹ ba mươi ba tuổi trút hơi thở cuối cùng trong căn nhà nhỏ ở Thành Nội. Chồng và con trưởng đang ở xa. Bên người mẹ chỉ còn cậu con trai mười một tuổi và đứa em đỏ hỏn đói sữa. Câu chuyện ấy, và hành trình hơn một thế kỷ của nấm mộ người mẹ, bắt đầu từ đây.","bia":{"src":"textures/bai/G02_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Những ngày giáp Tết năm Canh Tý","text":"Cuối tháng Chạp năm Canh Tý, kinh đô Huế đã chộn rộn không khí Tết. Ở các phố chợ, người ta sắm sửa cho những ngày đầu năm Tân Sửu. Nhưng trong một căn nhà nhỏ ở Thành Nội, không khí hoàn toàn khác. Bà Hoàng Thị Loan vừa sinh đứa con thứ tư, cậu bé Nguyễn Sinh Nhuận mà trong nhà quen gọi là bé Xin. Cuộc sống túng thiếu, lao lực nhiều năm, lại sinh nở trong cảnh khó khăn, khiến bà lâm bệnh nặng.\n\nÔng Nguyễn Sinh Sắc và người con trai cả Nguyễn Sinh Khiêm khi ấy đang ở Thanh Hóa. Người con gái đầu, Nguyễn Thị Thanh, vẫn ở quê Nghệ An với bà ngoại. Bên người mẹ ốm chỉ có cậu con trai thứ hai là Nguyễn Sinh Cung và đứa em mới chào đời. Không có tư liệu nào ghi lại những lời cuối cùng của bà. Người đời sau chỉ biết chắc một điều: ngày 22 tháng Chạp năm Canh Tý, tức ngày 10/2/1901, bà qua đời khi mới ba mươi ba tuổi. Hôm ấy chỉ còn hơn một tuần nữa là đến Tết Nguyên đán.","doc":1},{"loai":"doan","tieu_de":"Cô con gái nhà nho làng Hoàng Trù","text":"Bà Hoàng Thị Loan sinh năm Mậu Thìn 1868 tại làng Hoàng Trù, xã Kim Liên, huyện Nam Đàn, tỉnh Nghệ An. Bà là con gái cụ đồ Hoàng Xuân Đường. Chính cụ đồ đã nhận nuôi dạy cậu học trò mồ côi Nguyễn Sinh Sắc, rồi gả con gái cho. Cuốn tiểu sử do Bảo tàng Hồ Chí Minh biên soạn mô tả bà là một phụ nữ cần mẫn, đảm đang, đôn hậu, sống bằng nghề làm ruộng và dệt vải, hết lòng thương yêu và chăm lo cho chồng con.\n\nBà lần lượt sinh người con gái Nguyễn Thị Thanh, rồi hai con trai Nguyễn Sinh Khiêm và Nguyễn Sinh Cung. Cậu bé Cung chào đời ngày 19/5/1890 ngay tại quê ngoại Hoàng Trù. Những năm chồng dùi mài kinh sử, bà vừa làm ruộng vừa dệt vải, gánh phần lớn việc nuôi cả nhà. Năm 1894, ông Sắc đỗ Cử nhân khoa thi Hương. Niềm vui ấy chưa được bao lâu thì ông lại phải vào kinh thi Hội. Người vợ một lần nữa đứng ra gánh vác gia đình, lần này ở nơi đất khách.","doc":2},{"loai":"anh","src":"textures/bang_w/G02_1_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mất mẹ giữa kinh thành (1901)”, nhìn từ xa."},{"loai":"doan","tieu_de":"Theo chồng vào kinh","text":"Năm 1895, ông Sắc thi Hội không đỗ và xin vào học Trường Quốc Tử Giám để chờ khoa sau. Được nhận, ông về quê đưa vợ và hai con trai vào Huế. Bà Loan phải để người con gái đầu ở lại quê, nhờ mẹ đẻ nuôi giúp. Chuyến đi bộ nhiều ngày vào kinh (xem chuyên đề Huế – Kinh thành và trường Quốc Học) mở đầu hơn năm năm bà sống ở Huế.\n\nSau những ngày ở nhờ người quen và ở tạm trại lính, gia đình được một người quen cho ở nhờ trong Thành Nội. Ngôi nhà ấy nay là nhà lưu niệm trên đường Mai Thúc Loan. Tiền học bổng của Quốc Tử Giám không đủ sống. Ông Sắc ngoài giờ học phải đi chép chữ thuê. Khung cửi của bà Loan vì thế trở thành một nguồn sống quan trọng của gia đình. Ngày ngày bà ngồi dệt vải, may áo cho các con, lo từng bữa ăn để chồng yên tâm đèn sách. Chiếc khung cửi ấy ngày nay được tái hiện trong ngôi nhà lưu niệm, như một lời kể lặng lẽ về người mẹ tần tảo giữa đất kinh kỳ.","doc":3},{"loai":"doan","tieu_de":"Người mẹ ở lại kinh thành","text":"Năm 1898, ông Sắc thi Hội lần thứ hai vẫn chưa đỗ. Cuộc sống gia đình càng thêm chật vật. Gần cuối năm ấy, ông nhận lời về dạy học ở làng Dương Nỗ, cách Huế khoảng sáu cây số. Hai con trai theo cha về làng, vừa đỡ gánh nặng cho mẹ, vừa được cha dạy chữ Hán. Bà Loan vẫn ở lại Thành Nội với khung cửi của mình.\n\nTheo tư liệu giới thiệu tại ngôi nhà lưu niệm, trong những năm ở Huế, ông Sắc ngoài việc học còn bốc thuốc, chẩn bệnh giúp bà con quanh vùng. Gia đình nhỏ dần hòa vào đời sống của người dân kinh kỳ, có láng giềng, có bà con lối phố. Những mối quan hệ ấy về sau trở nên vô cùng quý giá. Cuối năm 1900, ông Sắc được cử đi làm việc ở trường thi Hương Thanh Hóa và đưa con trai cả đi cùng. Cậu bé Cung trở về Thành Nội sống với mẹ, khi bà sắp đến ngày sinh nở. Đó là những tháng cuối cùng hai mẹ con được ở bên nhau.","doc":4},{"loai":"anh","src":"textures/bai/G02_v0.jpg","chu_thich":"Không gian 3D tái hiện toàn cảnh gian Huế – Kinh thành và trường Quốc Học. Bên kia sông Hương là tường Kinh thành, phía trong là khu Thành Nội, nơi gia đình từng ở nhờ những năm 1895 – 1901.","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Bồng em đi xin sữa","text":"Mẹ mất, đứa trẻ sơ sinh khóc vì đói sữa. Các sách tiểu sử đều nhắc lại hình ảnh cậu bé Cung bồng em đi khắp xóm, nhờ những người mẹ đang nuôi con nhỏ cho em bú. Nhà nghiên cứu Hà Văn Thịnh, viết trên Tạp chí Sông Hương năm 2008, kể rằng cậu bé đã vừa khóc vừa chạy từ nhà này sang nhà khác để xin sữa cho em. Bà con láng giềng thương cảnh mẹ mất, cha vắng, đã cưu mang hai anh em trong những ngày tang tóc.\n\nNỗi đau ấy thật quá sức với một đứa trẻ. Cũng theo nhà nghiên cứu Hà Văn Thịnh, nhiều tài liệu ghi nhận rằng sau biến cố này, vẻ vui tươi thường ngày của cậu bé nhường chỗ cho sự trầm tư. Ít lâu sau, bé Xin quá yếu cũng mất theo mẹ. Cuốn tiểu sử do Bảo tàng Hồ Chí Minh biên soạn chỉ viết một câu ngắn gọn: mới mười một tuổi, Nguyễn Sinh Cung đã chịu nỗi đau mất mẹ và em. Câu chuyện bồng em đi xin sữa từ đó trở thành một trong những ký ức được nhắc lại nhiều nhất về tuổi thơ của Người.","doc":5},{"loai":"ban_co_biet","text":"Bà Hoàng Thị Loan sống ở Huế hơn năm năm, nhưng nấm mộ của bà nằm trên đất Huế tới hai mươi mốt năm, từ năm 1901 đến năm 1922.","nguon_ten":"Báo Dân trí – Thăm nơi từng an táng thân mẫu Bác Hồ ở Huế, 15/5/2024","doc":6},{"loai":"doan","tieu_de":"Đám tang lặng lẽ những ngày giáp Tết","text":"Tang lễ của bà Loan diễn ra trong một hoàn cảnh đặc biệt. Theo tư liệu được Bảo tàng Hồ Chí Minh thành phố Huế giới thiệu, lệ triều đình thời ấy không cho đưa đám tang của dân thường trong Thành Nội qua các cổng thành vào những ngày giáp Tết. Người đưa tang cũng không được khóc than. Vì vậy, bà con lối phố đã lặng lẽ đưa thi hài bà xuống thuyền, đi qua cống Thanh Long để sang bờ nam sông Hương.\n\nTừ đó, linh cữu được gánh bộ theo đường Ngự Bình, đưa lên mai táng ở triền phía tây núi Bân. Núi Bân còn có các tên gọi Hòn Thiên, núi Ba Tầng, là một ngọn núi thấp cao chừng bốn mươi ba mét, nằm ở phía nam núi Ngự Bình. Ông Sắc và con trưởng ở xa, nhận tin dữ mới vội trở về. Tiễn đưa người mẹ là cậu con trai mười một tuổi cùng những người láng giềng nghèo. Một đám tang lặng lẽ, không được khóc than, phải đi đường vòng qua sông: hình ảnh ấy cho thấy phận người dân thường nơi kinh đô dưới những lệ luật khắt khe.","doc":7},{"loai":"anh","src":"textures/bang_w/G02_1_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mất mẹ giữa kinh thành (1901)”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Người cha trở về, người con mang tên mới","text":"Nhận được tin vợ qua đời, ông Nguyễn Sinh Sắc vội từ Thanh Hóa trở lại Huế và đưa các con về quê. Sau khi thu xếp cuộc sống cho các con, được bà con trong họ ngoài làng động viên, ông lại vào kinh dự khoa thi Hội năm Tân Sửu. Lần này ông đi thi với tên mới là Nguyễn Sinh Huy. Tháng 5/1901, ông đỗ Phó bảng. Niềm vui khoa bảng đến chỉ khoảng ba tháng sau ngày người vợ tần tảo qua đời, khi bà không còn để chứng kiến.\n\nKhoảng tháng 9/1901, gia đình chuyển về sống ở quê nội làng Kim Liên. Ông Phó bảng làm lễ vào làng cho hai con trai với tên mới: Nguyễn Sinh Khiêm thành Nguyễn Tất Đạt, Nguyễn Sinh Cung thành Nguyễn Tất Thành. Cái tên mang nghĩa ắt sẽ thành công ra đời đúng vào năm gia đình mất đi người mẹ. Năm năm sau, khi Nguyễn Tất Thành theo cha trở lại Huế, căn nhà ở Thành Nội năm xưa đã không còn bóng mẹ (xem chuyên đề Huế – Kinh thành và trường Quốc Học).","doc":8},{"loai":"doan","tieu_de":"Hành trình của một nấm mộ","text":"Suốt hai mươi mốt năm, người mẹ yên nghỉ một mình trên triền núi Bân, cách quê nhà hàng trăm cây số. Năm 1922, người con gái cả Nguyễn Thị Thanh đã dời hài cốt mẹ về an táng ở quê nhà Nghệ An. Khi ấy, người con trai thứ hai của bà đang hoạt động ở Pháp với cái tên Nguyễn Ái Quốc. Về sau, mộ bà được cải táng lên núi Động Tranh ở huyện Nam Đàn. Khu mộ bà Hoàng Thị Loan ngày nay là một điểm trong Khu Di tích Kim Liên mà du khách thường đến thắp hương.\n\nỞ Huế, vị trí huyệt mộ cũ không bị lãng quên. Năm 1990, nhân kỷ niệm một trăm năm ngày sinh Chủ tịch Hồ Chí Minh, Đảng bộ, chính quyền và nhân dân thành phố Huế đã xây dựng nhà bia tưởng niệm ngay trên vị trí huyệt mộ. Năm 2008, nơi đây được công nhận là di tích lịch sử cấp tỉnh. Công trình được tu bổ nhiều lần. Đợt tu bổ, tôn tạo gần nhất hoàn thành vào đầu tháng 12/2025, với nhà bia được tu bổ, nền được gia cố, sân lát đá, đường vào mở rộng và cổng di tích xây mới.","doc":9},{"loai":"ban_co_biet","text":"Núi Bân, nơi bà Hoàng Thị Loan được an táng lần đầu, cũng là nơi cuối năm 1788 Nguyễn Huệ cho đắp đàn làm lễ lên ngôi hoàng đế, lấy niên hiệu Quang Trung, trước khi tiến quân ra Bắc đánh tan quân Thanh.","nguon_ten":"Báo Dân trí – Thăm nơi từng an táng thân mẫu Bác Hồ ở Huế, 15/5/2024","doc":10},{"loai":"anh","src":"textures/bang_w/G02_1_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mất mẹ giữa kinh thành (1901)”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngôi nhà nơi bà Hoàng Thị Loan sinh bé Xin và trút hơi thở cuối cùng nay là nhà lưu niệm trên đường Mai Thúc Loan. Cuốn tiểu sử của Bảo tàng Hồ Chí Minh ghi địa chỉ là số 112; các bài viết gần đây ghi số 158, theo cách đánh số mới. Đó là một ngôi nhà gỗ ba gian kiểu nhà rường truyền thống xứ Huế, mái lợp ngói liệt, tường gạch vồ. Bên trong trưng bày khung cửi dệt vải, gợi lại công việc hằng ngày của người mẹ năm xưa.\n\nNgôi nhà được Bộ Văn hóa – Thông tin xếp hạng di tích lịch sử văn hóa cấp quốc gia theo Quyết định số 74/VH-QĐ ngày 2/2/1993. Ngày 31/12/2020, cùng với ngôi nhà ở làng Dương Nỗ, nơi đây được Thủ tướng Chính phủ xếp hạng di tích quốc gia đặc biệt. Những ngày gần sinh nhật Bác, nhiều người tìm về ngôi nhà nhỏ này. Từ đây, du khách có thể sang bờ nam sông Hương, lên triền núi Bân viếng nhà bia tưởng niệm. Hai địa điểm nối với nhau bằng chặng đường tiễn đưa năm 1901, khi những người láng giềng nghèo lặng lẽ đưa một người mẹ về nơi an nghỉ.","doc":11}],"nguon":["Bảo tàng Hồ Chí Minh – Hồ Chí Minh: Tiểu sử, NXB Chính trị quốc gia, Hà Nội, 2008 (bản điện tử: https://tulieuvankien.dangcongsan.vn/c-mac-angghen-lenin-ho-chi-minh/book/ho-chi-minh/tieu-su-cuoc-doi-va-su-nghiep/ho-chi-minh-tieu-su-bao-tang-ho-chi-minh-nxb-chinh-tri-quoc-gia-ha-noi-nam-2008-20)","VTV.vn – Ngôi nhà lưu dấu tuổi thơ của Bác Hồ ở Huế, 18/5/2025: https://vtv.vn/doi-song/ngoi-nha-luu-dau-tuoi-tho-cua-bac-ho-o-hue-20250518051708808.htm","Báo Dân trí – Chuyện chưa kể về 2 ngôi nhà gắn với năm tháng ấu thơ của Bác Hồ tại Huế, 17/1/2021: https://dantri.com.vn/du-lich/chuyen-chua-ke-ve-2-ngoi-nha-gan-voi-nam-thang-au-tho-cua-bac-ho-tai-hue-20210117161721895.htm","Báo Dân trí – Thăm nơi từng an táng thân mẫu Bác Hồ ở Huế, 15/5/2024: https://dantri.com.vn/thoi-su/tham-noi-tung-an-tang-than-mau-bac-ho-o-hue-20240515171945462.htm","Báo Dân trí – Diện mạo mới địa điểm mai táng ban đầu thân mẫu Bác Hồ, 19/5/2026: https://dantri.com.vn/thoi-su/dien-mao-moi-dia-diem-mai-tang-ban-dau-than-mau-bac-ho-20260519181432975.htm","Hà Văn Thịnh – Nguyễn Tất Thành với Huế và phong trào chống thuế năm 1908, Tạp chí Sông Hương, 2008: http://tapchisonghuong.com.vn/tap-chi/c107/n804/Nguyen-Tat-Thanh-voi-Hue-va-phong-trao-chong-thue-nam-1908.html"],"doc":[{"t":"Tháng Chạp năm Canh Tý: cậu bé mười một tuổi bồng em đi xin sữa giữa kinh thành. Ngày 22 tháng Chạp năm Canh Tý, tức 10/2/1901, khi kinh đô đang sửa soạn đón Tết, một người mẹ ba mươi ba tuổi trút hơi thở cuối cùng trong căn nhà nhỏ ở Thành Nội. Chồng và con trưởng đang ở xa. Bên người mẹ chỉ còn cậu con trai mười một tuổi và đứa em đỏ hỏn đói sữa. Câu chuyện ấy, và hành trình hơn một thế kỷ của nấm mộ người mẹ, bắt đầu từ đây."},{"t":"Những ngày giáp Tết năm Canh Tý. Cuối tháng Chạp năm Canh Tý, kinh đô Huế đã chộn rộn không khí Tết. Ở các phố chợ, người ta sắm sửa cho những ngày đầu năm Tân Sửu. Nhưng trong một căn nhà nhỏ ở Thành Nội, không khí hoàn toàn khác. Bà Hoàng Thị Loan vừa sinh đứa con thứ tư, cậu bé Nguyễn Sinh Nhuận mà trong nhà quen gọi là bé Xin. Cuộc sống túng thiếu, lao lực nhiều năm, lại sinh nở trong cảnh khó khăn, khiến bà lâm bệnh nặng. Ông Nguyễn Sinh Sắc và người con trai cả Nguyễn Sinh Khiêm khi ấy đang ở Thanh Hóa. Người con gái đầu, Nguyễn Thị Thanh, vẫn ở quê Nghệ An với bà ngoại. Bên người mẹ ốm chỉ có cậu con trai thứ hai là Nguyễn Sinh Cung và đứa em mới chào đời. Không có tư liệu nào ghi lại những lời cuối cùng của bà. Người đời sau chỉ biết chắc một điều: ngày 22 tháng Chạp năm Canh Tý, tức ngày 10/2/1901, bà qua đời khi mới ba mươi ba tuổi. Hôm ấy chỉ còn hơn một tuần nữa là đến Tết Nguyên đán."},{"t":"Cô con gái nhà nho làng Hoàng Trù. Bà Hoàng Thị Loan sinh năm Mậu Thìn 1868 tại làng Hoàng Trù, xã Kim Liên, huyện Nam Đàn, tỉnh Nghệ An. Bà là con gái cụ đồ Hoàng Xuân Đường. Chính cụ đồ đã nhận nuôi dạy cậu học trò mồ côi Nguyễn Sinh Sắc, rồi gả con gái cho. Cuốn tiểu sử do Bảo tàng Hồ Chí Minh biên soạn mô tả bà là một phụ nữ cần mẫn, đảm đang, đôn hậu, sống bằng nghề làm ruộng và dệt vải, hết lòng thương yêu và chăm lo cho chồng con. Bà lần lượt sinh người con gái Nguyễn Thị Thanh, rồi hai con trai Nguyễn Sinh Khiêm và Nguyễn Sinh Cung. Cậu bé Cung chào đời ngày 19/5/1890 ngay tại quê ngoại Hoàng Trù. Những năm chồng dùi mài kinh sử, bà vừa làm ruộng vừa dệt vải, gánh phần lớn việc nuôi cả nhà. Năm 1894, ông Sắc đỗ Cử nhân khoa thi Hương. Niềm vui ấy chưa được bao lâu thì ông lại phải vào kinh thi Hội. Người vợ một lần nữa đứng ra gánh vác gia đình, lần này ở nơi đất khách."},{"t":"Theo chồng vào kinh. Năm 1895, ông Sắc thi Hội không đỗ và xin vào học Trường Quốc Tử Giám để chờ khoa sau. Được nhận, ông về quê đưa vợ và hai con trai vào Huế. Bà Loan phải để người con gái đầu ở lại quê, nhờ mẹ đẻ nuôi giúp. Chuyến đi bộ nhiều ngày vào kinh (xem chuyên đề Huế – Kinh thành và trường Quốc Học) mở đầu hơn năm năm bà sống ở Huế. Sau những ngày ở nhờ người quen và ở tạm trại lính, gia đình được một người quen cho ở nhờ trong Thành Nội. Ngôi nhà ấy nay là nhà lưu niệm trên đường Mai Thúc Loan. Tiền học bổng của Quốc Tử Giám không đủ sống. Ông Sắc ngoài giờ học phải đi chép chữ thuê. Khung cửi của bà Loan vì thế trở thành một nguồn sống quan trọng của gia đình. Ngày ngày bà ngồi dệt vải, may áo cho các con, lo từng bữa ăn để chồng yên tâm đèn sách. Chiếc khung cửi ấy ngày nay được tái hiện trong ngôi nhà lưu niệm, như một lời kể lặng lẽ về người mẹ tần tảo giữa đất kinh kỳ."},{"t":"Người mẹ ở lại kinh thành. Năm 1898, ông Sắc thi Hội lần thứ hai vẫn chưa đỗ. Cuộc sống gia đình càng thêm chật vật. Gần cuối năm ấy, ông nhận lời về dạy học ở làng Dương Nỗ, cách Huế khoảng sáu cây số. Hai con trai theo cha về làng, vừa đỡ gánh nặng cho mẹ, vừa được cha dạy chữ Hán. Bà Loan vẫn ở lại Thành Nội với khung cửi của mình. Theo tư liệu giới thiệu tại ngôi nhà lưu niệm, trong những năm ở Huế, ông Sắc ngoài việc học còn bốc thuốc, chẩn bệnh giúp bà con quanh vùng. Gia đình nhỏ dần hòa vào đời sống của người dân kinh kỳ, có láng giềng, có bà con lối phố. Những mối quan hệ ấy về sau trở nên vô cùng quý giá. Cuối năm 1900, ông Sắc được cử đi làm việc ở trường thi Hương Thanh Hóa và đưa con trai cả đi cùng. Cậu bé Cung trở về Thành Nội sống với mẹ, khi bà sắp đến ngày sinh nở. Đó là những tháng cuối cùng hai mẹ con được ở bên nhau."},{"t":"Bồng em đi xin sữa. Mẹ mất, đứa trẻ sơ sinh khóc vì đói sữa. Các sách tiểu sử đều nhắc lại hình ảnh cậu bé Cung bồng em đi khắp xóm, nhờ những người mẹ đang nuôi con nhỏ cho em bú. Nhà nghiên cứu Hà Văn Thịnh, viết trên Tạp chí Sông Hương năm 2008, kể rằng cậu bé đã vừa khóc vừa chạy từ nhà này sang nhà khác để xin sữa cho em. Bà con láng giềng thương cảnh mẹ mất, cha vắng, đã cưu mang hai anh em trong những ngày tang tóc. Nỗi đau ấy thật quá sức với một đứa trẻ. Cũng theo nhà nghiên cứu Hà Văn Thịnh, nhiều tài liệu ghi nhận rằng sau biến cố này, vẻ vui tươi thường ngày của cậu bé nhường chỗ cho sự trầm tư. Ít lâu sau, bé Xin quá yếu cũng mất theo mẹ. Cuốn tiểu sử do Bảo tàng Hồ Chí Minh biên soạn chỉ viết một câu ngắn gọn: mới mười một tuổi, Nguyễn Sinh Cung đã chịu nỗi đau mất mẹ và em. Câu chuyện bồng em đi xin sữa từ đó trở thành một trong những ký ức được nhắc lại nhiều nhất về tuổi thơ của Người."},{"t":"Bạn có biết? Bà Hoàng Thị Loan sống ở Huế hơn năm năm, nhưng nấm mộ của bà nằm trên đất Huế tới hai mươi mốt năm, từ năm 1901 đến năm 1922."},{"t":"Đám tang lặng lẽ những ngày giáp Tết. Tang lễ của bà Loan diễn ra trong một hoàn cảnh đặc biệt. Theo tư liệu được Bảo tàng Hồ Chí Minh thành phố Huế giới thiệu, lệ triều đình thời ấy không cho đưa đám tang của dân thường trong Thành Nội qua các cổng thành vào những ngày giáp Tết. Người đưa tang cũng không được khóc than. Vì vậy, bà con lối phố đã lặng lẽ đưa thi hài bà xuống thuyền, đi qua cống Thanh Long để sang bờ nam sông Hương. Từ đó, linh cữu được gánh bộ theo đường Ngự Bình, đưa lên mai táng ở triền phía tây núi Bân. Núi Bân còn có các tên gọi Hòn Thiên, núi Ba Tầng, là một ngọn núi thấp cao chừng bốn mươi ba mét, nằm ở phía nam núi Ngự Bình. Ông Sắc và con trưởng ở xa, nhận tin dữ mới vội trở về. Tiễn đưa người mẹ là cậu con trai mười một tuổi cùng những người láng giềng nghèo. Một đám tang lặng lẽ, không được khóc than, phải đi đường vòng qua sông: hình ảnh ấy cho thấy phận người dân thường nơi kinh đô dưới những lệ luật khắt khe."},{"t":"Người cha trở về, người con mang tên mới. Nhận được tin vợ qua đời, ông Nguyễn Sinh Sắc vội từ Thanh Hóa trở lại Huế và đưa các con về quê. Sau khi thu xếp cuộc sống cho các con, được bà con trong họ ngoài làng động viên, ông lại vào kinh dự khoa thi Hội năm Tân Sửu. Lần này ông đi thi với tên mới là Nguyễn Sinh Huy. Tháng 5/1901, ông đỗ Phó bảng. Niềm vui khoa bảng đến chỉ khoảng ba tháng sau ngày người vợ tần tảo qua đời, khi bà không còn để chứng kiến. Khoảng tháng 9/1901, gia đình chuyển về sống ở quê nội làng Kim Liên. Ông Phó bảng làm lễ vào làng cho hai con trai với tên mới: Nguyễn Sinh Khiêm thành Nguyễn Tất Đạt, Nguyễn Sinh Cung thành Nguyễn Tất Thành. Cái tên mang nghĩa ắt sẽ thành công ra đời đúng vào năm gia đình mất đi người mẹ. Năm năm sau, khi Nguyễn Tất Thành theo cha trở lại Huế, căn nhà ở Thành Nội năm xưa đã không còn bóng mẹ (xem chuyên đề Huế – Kinh thành và trường Quốc Học)."},{"t":"Hành trình của một nấm mộ. Suốt hai mươi mốt năm, người mẹ yên nghỉ một mình trên triền núi Bân, cách quê nhà hàng trăm cây số. Năm 1922, người con gái cả Nguyễn Thị Thanh đã dời hài cốt mẹ về an táng ở quê nhà Nghệ An. Khi ấy, người con trai thứ hai của bà đang hoạt động ở Pháp với cái tên Nguyễn Ái Quốc. Về sau, mộ bà được cải táng lên núi Động Tranh ở huyện Nam Đàn. Khu mộ bà Hoàng Thị Loan ngày nay là một điểm trong Khu Di tích Kim Liên mà du khách thường đến thắp hương. Ở Huế, vị trí huyệt mộ cũ không bị lãng quên. Năm 1990, nhân kỷ niệm một trăm năm ngày sinh Chủ tịch Hồ Chí Minh, Đảng bộ, chính quyền và nhân dân thành phố Huế đã xây dựng nhà bia tưởng niệm ngay trên vị trí huyệt mộ. Năm 2008, nơi đây được công nhận là di tích lịch sử cấp tỉnh. Công trình được tu bổ nhiều lần. Đợt tu bổ, tôn tạo gần nhất hoàn thành vào đầu tháng 12/2025, với nhà bia được tu bổ, nền được gia cố, sân lát đá, đường vào mở rộng và cổng di tích xây mới."},{"t":"Bạn có biết? Núi Bân, nơi bà Hoàng Thị Loan được an táng lần đầu, cũng là nơi cuối năm 1788 Nguyễn Huệ cho đắp đàn làm lễ lên ngôi hoàng đế, lấy niên hiệu Quang Trung, trước khi tiến quân ra Bắc đánh tan quân Thanh."},{"t":"Dấu tích hôm nay. Ngôi nhà nơi bà Hoàng Thị Loan sinh bé Xin và trút hơi thở cuối cùng nay là nhà lưu niệm trên đường Mai Thúc Loan. Cuốn tiểu sử của Bảo tàng Hồ Chí Minh ghi địa chỉ là số 112; các bài viết gần đây ghi số 158, theo cách đánh số mới. Đó là một ngôi nhà gỗ ba gian kiểu nhà rường truyền thống xứ Huế, mái lợp ngói liệt, tường gạch vồ. Bên trong trưng bày khung cửi dệt vải, gợi lại công việc hằng ngày của người mẹ năm xưa. Ngôi nhà được Bộ Văn hóa – Thông tin xếp hạng di tích lịch sử văn hóa cấp quốc gia theo Quyết định số 74/VH-QĐ ngày 2/2/1993. Ngày 31/12/2020, cùng với ngôi nhà ở làng Dương Nỗ, nơi đây được Thủ tướng Chính phủ xếp hạng di tích quốc gia đặc biệt. Những ngày gần sinh nhật Bác, nhiều người tìm về ngôi nhà nhỏ này. Từ đây, du khách có thể sang bờ nam sông Hương, lên triền núi Bân viếng nhà bia tưởng niệm. Hai địa điểm nối với nhau bằng chặng đường tiễn đưa năm 1901, khi những người láng giềng nghèo lặng lẽ đưa một người mẹ về nơi an nghỉ."}],"so_chu":1940},{"i":2,"tieu_de_bang":"Người phiên dịch cho đoàn nông dân (1908)","tieu_de":"Buổi sáng trước Tòa Khâm sứ: người học trò lật ngược chiếc nón, đứng ra làm thông ngôn cho dân","sapo":"Sáng 11/4/1908, khoảng một nghìn nông dân Thừa Thiên vây quanh Tòa Khâm sứ Trung Kỳ, đòi giảm thuế. Họ có lý lẽ, nhưng không nói được thứ tiếng của những người đang cai trị mình. Một học trò trường Pháp – Việt sắp tròn mười tám tuổi đã lật ngược chiếc nón, bước lên đứng giữa hai bên. Từ buổi sáng ấy, tên anh bắt đầu có trong hồ sơ theo dõi của mật thám Pháp.","bia":{"src":"textures/bai/G02_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Buổi sáng trước Tòa Khâm sứ","text":"Sáng ngày 11/4/1908, khu vực trước Tòa Khâm sứ Trung Kỳ bên bờ nam sông Hương đông nghịt người. Theo báo cáo của viên Công sứ Thừa Thiên gửi Khâm sứ, hiện lưu tại Trung tâm Lưu trữ quốc gia IV, hôm ấy có lúc khoảng một nghìn người biểu tình tụ tập quanh văn phòng Tòa Khâm sứ để yêu cầu giảm thuế. Họ là nông dân các làng ven kinh đô. Theo các nhà nghiên cứu ở Huế, đoàn người áo quần rách rưới, chân không, tóc cắt ngắn, vừa đi vừa hô vang.\n\nTrước đó một ngày, dân làng Công Lương đã bắt trói viên Phủ doãn Thừa Thiên, tức quan đầu tỉnh. Sáng hôm ấy, vài trăm người giải ông ta đến trước văn phòng Tòa Khâm sứ. Đám đông có yêu sách, có quyết tâm, nhưng thiếu một thứ: người nói được tiếng Pháp để chuyển lời của họ đến tai những viên quan cai trị. Trong đám đông ấy có một thanh niên người Nghệ An, dáng cao lớn, là học trò Trường tiểu học Pháp – Việt Đông Ba. Hơn sáu mươi năm sau, một người bạn học vẫn còn nhớ rõ hình ảnh của anh trong buổi sáng hôm đó.","doc":1},{"loai":"doan","tieu_de":"Những ngày tháng Tư ở ven kinh đô","text":"Phong trào chống sưu thuế năm 1908 khởi phát ở Quảng Nam từ tháng 3, rồi lan ra nhiều tỉnh Trung Kỳ (xem chuyên đề Phong trào chống sưu thuế 1908). Ở Thừa Thiên, người nông dân cũng oằn lưng dưới gánh sưu thuế như mọi nơi: thuế thân đóng theo đầu người, thuế ruộng, cùng những ngày đi phu làm đường, đắp đê. Điều đặc biệt là họ sống ngay dưới chân kinh đô. Đích đến của họ không phải dinh quan Nam triều, mà là Tòa Khâm sứ, nơi nắm quyền quyết định thật sự.\n\nBáo cáo của người Pháp ghi lại diễn biến khá tỉ mỉ. Ngày 9/4/1908, từng nhóm đông người từ nhiều làng phía nam tỉnh tập trung ở các tổng An Cựu và Cư Chánh. Ngày 10/4, họ kéo đến gần thành phố, tụ lại ở các làng An Hòa, An Cựu, Công Lương. Tại Công Lương, viên Phủ doãn đi thuyền tam bản đến thì bị ném đá. Dân làng bắt giữ ông ta cùng viên phó quản và mấy người lính, trói lại. Từ một cuộc kéo nhau đi xin giảm sưu, sự việc đã thành cuộc đối đầu trực diện với chính quyền.","doc":2},{"loai":"anh","src":"textures/bang_w/G02_2_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Người phiên dịch cho đoàn nông dân (1908)”, nhìn từ xa."},{"loai":"doan","tieu_de":"Người học trò ở Dãy Trại","text":"Người thanh niên cao lớn ấy là Nguyễn Tất Thành, trong giấy tờ ở Huế mang tên Nguyễn Sinh Côn. Mùa xuân năm 1908, anh còn hơn một tháng nữa mới tròn mười tám tuổi. Anh là con trai ông Thừa biện Bộ Lễ Nguyễn Sinh Huy. Gia đình ở một căn phòng thuộc Dãy Trại, khu nhà của thuộc viên các bộ trên đường Đông Ba. Từ tháng 9/1906, anh học ở Trường tiểu học Pháp – Việt Đông Ba, ngay sát ngoài cửa Đông Ba.\n\nNhiều sách trước đây gọi anh là học trò Quốc Học khi tham gia biểu tình. Tuy nhiên, Bảo tàng Hồ Chí Minh chi nhánh Thừa Thiên Huế đã xác định rằng vào tháng 4/1908, anh còn là học sinh trường Đông Ba; phải đến tháng 9/1908 anh mới vào Quốc Học. Sau gần hai năm học trường Pháp – Việt, vốn tiếng Pháp của anh đã đủ để nói chuyện với người Pháp. Con đường trước mắt người học trò con nhà quan gần như đã mở sẵn: học xong, làm thông ngôn hay thư ký cho nhà nước bảo hộ. Chỉ cần đứng ngoài đám đông, con đường ấy sẽ không bị ảnh hưởng. Nhưng sáng 11/4, anh đã chọn bước vào giữa đám đông.","doc":3},{"loai":"ban_co_biet","text":"Ở Huế những năm 1906 – 1909, Nguyễn Tất Thành còn có tên Nguyễn Sinh Côn, còn người cha, ông Phó bảng Nguyễn Sinh Sắc, dùng tên Nguyễn Sinh Huy từ khoa thi Hội năm 1901.","nguon_ten":"Tuổi Trẻ Online, 13/2/2018; Bảo tàng Hồ Chí Minh – Hồ Chí Minh: Tiểu sử, 2008","doc":4},{"loai":"doan","tieu_de":"Lật ngược chiếc nón","text":"Diễn biến buổi sáng ấy được ông Lê Thanh Cảnh, một bạn học, kể lại chi tiết trong bài hồi ký Dưới mái tranh Trường Quốc Học những năm 1906 – 1911, đăng trên đặc san Ái Hữu Quốc Học năm 1970. Điều đáng chú ý là về sau, ông Cảnh làm viên chức ngay tại Tòa Khâm sứ này. Theo lời ông, khi đoàn người đang kéo xuống Tòa Khâm sứ thì nhóm học sinh của ông gặp trò Côn. Côn rủ các bạn đi theo ủng hộ đồng bào và làm thông ngôn cho họ.\n\nRồi anh lật ngược chiếc nón đang đội, đội lên đầu như muốn nói rằng phải lật ngược tình trạng hiện tại. Côn đi trước, kéo theo nhóm học sinh rành tiếng Pháp. Thấy có học trò đi cùng, bà con kéo theo rất đông. Đến cửa Tòa Khâm sứ, đoàn người bị chặn lại. Chiếc nón lật ngược chỉ là một cử chỉ nhỏ, nhưng ông Cảnh vẫn nhớ nó sau hơn sáu mươi năm. Theo cuốn tiểu sử do Bảo tàng Hồ Chí Minh biên soạn, cuộc biểu tình tháng 4/1908 là khởi đầu cho cuộc tranh đấu suốt đời Người vì quyền lợi của nhân dân lao động.","doc":5},{"loai":"trich","text":"Đồng bào đi xin xâu, chúng mình phải đi theo ủng hộ họ, để làm thông ngôn cho họ. Nào chúng ta cùng đi xuống tòa khâm!","nguoi":"Lời trò Côn, theo hồi ký của ông Lê Thanh Cảnh","nguon_ten":"Lê Thanh Cảnh, Dưới mái tranh Trường Quốc Học những năm 1906 – 1911, đặc san Ái Hữu Quốc Học, 1970; dẫn theo Tuổi Trẻ Online, 13/2/2018","doc":6},{"loai":"doan","tieu_de":"Người đứng giữa hai thứ tiếng","text":"Theo tài liệu của nhà nghiên cứu Nguyễn Hữu Châu Phan, trò Côn đã vào trước, gặp các viên quan Pháp và trình bày bằng tiếng Pháp nguyện vọng của bà con. Sau đó, anh dịch lại những lời đối đáp giữa quan Pháp với người dân. Vai trò ấy nghe thì đơn giản, nhưng đầy hiểm nguy. Người thông ngôn đứng ở chỗ dễ thấy nhất, nói những điều nhà cầm quyền không muốn nghe, bằng chính ngôn ngữ của nhà cầm quyền. Với đám đông, anh là tiếng nói của họ. Với viên chức Pháp, anh là một học sinh trường nhà nước đang đứng về phía người biểu tình.\n\nNhà nghiên cứu Hà Văn Thịnh viết rằng dù nhà cầm quyền đã chịu thương thuyết, cuộc biểu tình vẫn bị đàn áp. Ông Lê Thanh Cảnh nhớ lại cảnh lính khố xanh dùng gậy tre quất túi bụi vào đám đông. Theo lời ông, trò Côn hôm ấy đi đầu, lại là người cao lớn, nên “lãnh đủ hơn ai hết”. Đó là cái giá đầu tiên người thanh niên phải trả. Tiếng Pháp, thứ ngôn ngữ nhà trường dạy để đào tạo người phục vụ bộ máy bảo hộ, lần đầu được anh dùng để nói thay cho người dân bị áp bức.","doc":7},{"loai":"anh","src":"textures/bang_w/G02_2_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Người phiên dịch cho đoàn nông dân (1908)”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Những ngày đàn áp","text":"Cuộc biểu tình ở Huế không dừng lại sau buổi sáng 11/4. Theo báo cáo của người Pháp, ngày 12/4, một đội khoảng một trăm lính bộ binh hải quân được phái đến Công Lương và bắt giữ ba mươi tư người biểu tình. Ngày 13 và 14/4, biểu tình vẫn tiếp diễn trong thành phố. Hai người biểu tình bị thương khá nặng vì bị đánh bằng báng súng. Báo cáo ghi nhận tổng cộng sáu mươi tư người bị bắt. Phong trào ở Thừa Thiên kéo dài chưa đầy một tuần thì bị dập tắt.\n\nỞ các tỉnh khác trong Trung Kỳ, sự đàn áp còn khốc liệt hơn. Nhiều nhà nho của phong trào Duy Tân bị quy trách nhiệm, người bị xử tử, người bị đày ra Côn Đảo. Với người thanh niên phiên dịch, hậu quả không đến bằng xiềng xích mà bằng một thứ khác. Theo cuốn tiểu sử của Bảo tàng Hồ Chí Minh, vì những hoạt động yêu nước ấy, Nguyễn Tất Thành bị thực dân Pháp để ý theo dõi. Ông Nguyễn Sinh Huy cũng bị chúng khiển trách vì đã để con trai có những hoạt động bài Pháp. Từ đây, cái tên Nguyễn Sinh Côn đã có trong sổ sách của nhà cầm quyền.","doc":8},{"loai":"ban_co_biet","text":"Trong số ba mươi tư người bị bắt ở Công Lương ngày 12/4/1908, chỉ có mười ba người là dân làng này. Số còn lại từ nhiều làng khác kéo về, cho thấy phong trào đã lan khắp vùng ven kinh đô.","nguon_ten":"Trung tâm Lưu trữ quốc gia IV – Phong trào chống thuế tại Huế năm 1908 qua báo cáo của người Pháp (mocban.vn)","doc":9},{"loai":"doan","tieu_de":"Bức thư ngày 7 tháng 8","text":"Nhiều sách phổ thông từng viết rằng sau cuộc biểu tình, Nguyễn Tất Thành bị đuổi khỏi Trường Quốc Học. Tư liệu lưu trữ tìm được về sau cho thấy câu chuyện có phần khác. Ngày 4/8/1908, Khâm sứ Trung Kỳ Lévecque gửi thư yêu cầu hiệu trưởng Trường Quốc Học cho biết lai lịch của Nguyễn Sinh Côn. Đây là một trong những học sinh vừa đỗ tiểu học và được chuyển lên Quốc Học. Chỉ ba ngày sau, ngày 7/8/1908, hiệu trưởng Chouquet gửi văn thư phúc đáp.\n\nNhững giấy tờ này nằm trong bộ hồ sơ mà mật thám Pháp lập về Nguyễn Ái Quốc, hiện lưu tại Trung tâm Lưu trữ hải ngoại ở Aix-en-Provence, nước Pháp. Bảo tàng Hồ Chí Minh ở Huế lưu giữ bản thư của ông Chouquet như một hiện vật. Việc Khâm sứ đích thân hỏi đến một học trò mười tám tuổi cho thấy buổi sáng tháng Tư đã để lại dấu vết trong mắt chính quyền. Nhưng câu trả lời của nhà trường lại mở cửa cho anh. Cuốn tiểu sử của Bảo tàng Hồ Chí Minh ghi rõ: tháng 8/1908, anh vẫn được ông Chouquet tiếp nhận; tháng 9/1908, anh vào lớp trung đẳng của Trường Quốc Học.","doc":10},{"loai":"trich","text":"Tôi hân hạnh báo cho ngài rõ sẽ có thể tiếp nhận vào Trường Quốc Học học sinh có tên Nguyễn Sinh Côn, gốc người Nghệ An, học sinh Trường Pháp – An Nam tỉnh Thừa Thiên.","nguoi":"Hiệu trưởng Trường Quốc Học Chouquet, thư phúc đáp Khâm sứ Trung Kỳ ngày 7/8/1908, bản dịch","nguon_ten":"Hồ sơ lưu tại Trung tâm Lưu trữ hải ngoại Pháp, Aix-en-Provence; dẫn theo Tuổi Trẻ Online, 13/2/2018","doc":11},{"loai":"anh","src":"textures/ht/ht_anh_college_quoc_hoc_a_hue_2e_annee_complementaire.jpg","chu_thich":"Một lớp học tại Trường Quốc Học Huế đầu thế kỷ XX, ảnh công bố năm 1913. Tháng 9/1908, Nguyễn Tất Thành vào học lớp trung đẳng của ngôi trường này.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Rời trường, rời Huế","text":"Vậy anh rời Quốc Học như thế nào? Một số tài liệu cho rằng chỉ sau vài tháng, anh bị đuổi học vì thái độ ngang bướng với những thầy giáo Pháp coi thường học trò Việt. Các nhà nghiên cứu Nguyễn Đắc Xuân và Nguyễn Hồng Việt lại cho rằng anh không bị đuổi học. Theo ông Xuân, vì bị theo dõi, anh đã tự nghỉ học, ẩn ở Huế một thời gian rồi theo cha vào Bình Định. Bảo tàng Hồ Chí Minh chi nhánh Thừa Thiên Huế xác định lập luận này là phù hợp.\n\nCuốn tiểu sử của Bảo tàng Hồ Chí Minh ghi rằng khoảng tháng 6/1909, anh rời Trường Quốc Học theo cha vào Bình Định, khi ông được bổ làm Tri huyện Bình Khê. Dù chi tiết còn được bàn luận, các nguồn đều thống nhất rằng từ sau tháng 4/1908, người học trò đã bị chính quyền thuộc địa để mắt tới. Anh cũng không đi theo con đường làm thông ngôn, làm công chức cho nhà nước bảo hộ. Từ Bình Định, anh xuôi vào Phan Thiết dạy học ở Trường Dục Thanh, rồi vào Sài Gòn. Ngày 5/6/1911, anh rời Bến Nhà Rồng ra đi tìm đường cứu nước.","doc":12},{"loai":"doan","tieu_de":"Từ thông ngôn cho dân đến tiếng nói của dân tộc","text":"Thứ tiếng Pháp mà người học trò dùng để thông ngôn cho nông dân Thừa Thiên, ít năm sau đã trở thành công cụ để Nguyễn Ái Quốc viết báo ở Paris. Từ những bài báo viết trong những năm 1921 – 1924, Người bổ sung, sửa chữa thành cuốn Bản án chế độ thực dân Pháp. Cuốn sách tố cáo tội ác của chủ nghĩa thực dân Pháp đối với người dân các thuộc địa, và kêu gọi các dân tộc bị áp bức thức tỉnh.\n\nCâu chuyện khép lại một vòng tròn vào năm 1945. Sáng 3/9/1945, tại phiên họp đầu tiên của Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa, Chủ tịch Hồ Chí Minh nêu sáu vấn đề cấp bách. Một trong số đó là xóa bỏ ngay những thứ thuế bóc lột vô nhân đạo. Chính phủ sau đó ban hành các sắc lệnh bãi bỏ thuế thân, thuế chợ, thuế đò. Thuế thân từng là một trong những gánh nặng khiến nông dân Trung Kỳ nổi dậy năm 1908. Ba mươi bảy năm sau, chính người học trò làm thông ngôn năm xưa cùng Chính phủ của Người đã xóa bỏ nó.","doc":13},{"loai":"anh","src":"textures/bang_w/G02_2_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Người phiên dịch cho đoàn nông dân (1908)”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Tòa Khâm sứ Trung Kỳ được dựng từ năm 1878 ở bờ nam sông Hương, theo một hiệp ước ký năm 1874. Theo nhà nghiên cứu Phan Thuận An, khu đất ấy nay thuộc Trường Đại học Sư phạm Huế. Dãy công sở thời Pháp ở bờ nam phần lớn nằm lùi vào lề phía nam con đường ven sông, thời Pháp mang tên Jules Ferry, nay là đường Lê Lợi. Trên cùng con đường ấy có Trường Quốc Học, nơi người học trò bước vào học mấy tháng sau cuộc biểu tình.\n\nNgày nay, sinh viên sư phạm, những thầy cô giáo tương lai, học tập ngay trên mảnh đất từng chứng kiến hoạt động đấu tranh đầu tiên của Nguyễn Tất Thành. Ở Bảo tàng Hồ Chí Minh thành phố Huế, khách tham quan có thể tìm hiểu về những năm tháng Người sống ở kinh đô, trong đó có phong trào chống thuế năm 1908. Đi dọc đường Lê Lợi bên sông Hương, từ Trường Quốc Học đến khu Tòa Khâm sứ cũ, người hôm nay có thể hình dung lại khung cảnh buổi sáng tháng Tư năm 1908. Đó là buổi sáng một người học trò lật ngược chiếc nón và bước lên đứng về phía nhân dân.","doc":14}],"nguon":["Bảo tàng Hồ Chí Minh – Hồ Chí Minh: Tiểu sử, NXB Chính trị quốc gia, Hà Nội, 2008 (bản điện tử: https://tulieuvankien.dangcongsan.vn/c-mac-angghen-lenin-ho-chi-minh/book/ho-chi-minh/tieu-su-cuoc-doi-va-su-nghiep/ho-chi-minh-tieu-su-bao-tang-ho-chi-minh-nxb-chinh-tri-quoc-gia-ha-noi-nam-2008-20)","Minh Đăng – Nguyễn Tất Thành ra đi từ ngôi trường xứ Huế, Tuổi Trẻ Online, 13/2/2018: https://tuoitre.vn/nguyen-tat-thanh-ra-di-tu-ngoi-truong-xu-hue-20180205104555229.htm","Trung tâm Lưu trữ quốc gia IV – Phong trào chống thuế tại Huế năm 1908 qua báo cáo của người Pháp: https://mocban.vn/phong-trao-chong-thue-tai-hue-nam-1908-qua-bao-cao-cua-nguoi-phap/","Báo Nghệ An – Những cựu trò xuất sắc người Nghệ ở Trường Quốc học Huế: https://baonghean.vn/en/nhung-cuu-tro-xuat-sac-nguoi-nghe-o-truong-quoc-hoc-hue-10056663.html","Hà Văn Thịnh – Nguyễn Tất Thành với Huế và phong trào chống thuế năm 1908, Tạp chí Sông Hương, 2008: http://tapchisonghuong.com.vn/tap-chi/c107/n804/Nguyen-Tat-Thanh-voi-Hue-va-phong-trao-chong-thue-nam-1908.html","Phan Thuận An – Kiến trúc Khu phố Tây ở Huế thời Pháp thuộc, Tạp chí Sông Hương, 2017: http://tapchisonghuong.com.vn/tap-chi/c375/n25741/Kien-truc-Khu-pho-Tay-o-Hue-thoi-Phap-thuoc.html"],"doc":[{"t":"Buổi sáng trước Tòa Khâm sứ: người học trò lật ngược chiếc nón, đứng ra làm thông ngôn cho dân. Sáng 11/4/1908, khoảng một nghìn nông dân Thừa Thiên vây quanh Tòa Khâm sứ Trung Kỳ, đòi giảm thuế. Họ có lý lẽ, nhưng không nói được thứ tiếng của những người đang cai trị mình. Một học trò trường Pháp – Việt sắp tròn mười tám tuổi đã lật ngược chiếc nón, bước lên đứng giữa hai bên. Từ buổi sáng ấy, tên anh bắt đầu có trong hồ sơ theo dõi của mật thám Pháp."},{"t":"Buổi sáng trước Tòa Khâm sứ. Sáng ngày 11/4/1908, khu vực trước Tòa Khâm sứ Trung Kỳ bên bờ nam sông Hương đông nghịt người. Theo báo cáo của viên Công sứ Thừa Thiên gửi Khâm sứ, hiện lưu tại Trung tâm Lưu trữ quốc gia IV, hôm ấy có lúc khoảng một nghìn người biểu tình tụ tập quanh văn phòng Tòa Khâm sứ để yêu cầu giảm thuế. Họ là nông dân các làng ven kinh đô. Theo các nhà nghiên cứu ở Huế, đoàn người áo quần rách rưới, chân không, tóc cắt ngắn, vừa đi vừa hô vang. Trước đó một ngày, dân làng Công Lương đã bắt trói viên Phủ doãn Thừa Thiên, tức quan đầu tỉnh. Sáng hôm ấy, vài trăm người giải ông ta đến trước văn phòng Tòa Khâm sứ. Đám đông có yêu sách, có quyết tâm, nhưng thiếu một thứ: người nói được tiếng Pháp để chuyển lời của họ đến tai những viên quan cai trị. Trong đám đông ấy có một thanh niên người Nghệ An, dáng cao lớn, là học trò Trường tiểu học Pháp – Việt Đông Ba. Hơn sáu mươi năm sau, một người bạn học vẫn còn nhớ rõ hình ảnh của anh trong buổi sáng hôm đó."},{"t":"Những ngày tháng Tư ở ven kinh đô. Phong trào chống sưu thuế năm 1908 khởi phát ở Quảng Nam từ tháng 3, rồi lan ra nhiều tỉnh Trung Kỳ (xem chuyên đề Phong trào chống sưu thuế 1908). Ở Thừa Thiên, người nông dân cũng oằn lưng dưới gánh sưu thuế như mọi nơi: thuế thân đóng theo đầu người, thuế ruộng, cùng những ngày đi phu làm đường, đắp đê. Điều đặc biệt là họ sống ngay dưới chân kinh đô. Đích đến của họ không phải dinh quan Nam triều, mà là Tòa Khâm sứ, nơi nắm quyền quyết định thật sự. Báo cáo của người Pháp ghi lại diễn biến khá tỉ mỉ. Ngày 9/4/1908, từng nhóm đông người từ nhiều làng phía nam tỉnh tập trung ở các tổng An Cựu và Cư Chánh. Ngày 10/4, họ kéo đến gần thành phố, tụ lại ở các làng An Hòa, An Cựu, Công Lương. Tại Công Lương, viên Phủ doãn đi thuyền tam bản đến thì bị ném đá. Dân làng bắt giữ ông ta cùng viên phó quản và mấy người lính, trói lại. Từ một cuộc kéo nhau đi xin giảm sưu, sự việc đã thành cuộc đối đầu trực diện với chính quyền."},{"t":"Người học trò ở Dãy Trại. Người thanh niên cao lớn ấy là Nguyễn Tất Thành, trong giấy tờ ở Huế mang tên Nguyễn Sinh Côn. Mùa xuân năm 1908, anh còn hơn một tháng nữa mới tròn mười tám tuổi. Anh là con trai ông Thừa biện Bộ Lễ Nguyễn Sinh Huy. Gia đình ở một căn phòng thuộc Dãy Trại, khu nhà của thuộc viên các bộ trên đường Đông Ba. Từ tháng 9/1906, anh học ở Trường tiểu học Pháp – Việt Đông Ba, ngay sát ngoài cửa Đông Ba. Nhiều sách trước đây gọi anh là học trò Quốc Học khi tham gia biểu tình. Tuy nhiên, Bảo tàng Hồ Chí Minh chi nhánh Thừa Thiên Huế đã xác định rằng vào tháng 4/1908, anh còn là học sinh trường Đông Ba; phải đến tháng 9/1908 anh mới vào Quốc Học. Sau gần hai năm học trường Pháp – Việt, vốn tiếng Pháp của anh đã đủ để nói chuyện với người Pháp. Con đường trước mắt người học trò con nhà quan gần như đã mở sẵn: học xong, làm thông ngôn hay thư ký cho nhà nước bảo hộ. Chỉ cần đứng ngoài đám đông, con đường ấy sẽ không bị ảnh hưởng. Nhưng sáng 11/4, anh đã chọn bước vào giữa đám đông."},{"t":"Bạn có biết? Ở Huế những năm 1906 – 1909, Nguyễn Tất Thành còn có tên Nguyễn Sinh Côn, còn người cha, ông Phó bảng Nguyễn Sinh Sắc, dùng tên Nguyễn Sinh Huy từ khoa thi Hội năm 1901."},{"t":"Lật ngược chiếc nón. Diễn biến buổi sáng ấy được ông Lê Thanh Cảnh, một bạn học, kể lại chi tiết trong bài hồi ký Dưới mái tranh Trường Quốc Học những năm 1906 – 1911, đăng trên đặc san Ái Hữu Quốc Học năm 1970. Điều đáng chú ý là về sau, ông Cảnh làm viên chức ngay tại Tòa Khâm sứ này. Theo lời ông, khi đoàn người đang kéo xuống Tòa Khâm sứ thì nhóm học sinh của ông gặp trò Côn. Côn rủ các bạn đi theo ủng hộ đồng bào và làm thông ngôn cho họ. Rồi anh lật ngược chiếc nón đang đội, đội lên đầu như muốn nói rằng phải lật ngược tình trạng hiện tại. Côn đi trước, kéo theo nhóm học sinh rành tiếng Pháp. Thấy có học trò đi cùng, bà con kéo theo rất đông. Đến cửa Tòa Khâm sứ, đoàn người bị chặn lại. Chiếc nón lật ngược chỉ là một cử chỉ nhỏ, nhưng ông Cảnh vẫn nhớ nó sau hơn sáu mươi năm. Theo cuốn tiểu sử do Bảo tàng Hồ Chí Minh biên soạn, cuộc biểu tình tháng 4/1908 là khởi đầu cho cuộc tranh đấu suốt đời Người vì quyền lợi của nhân dân lao động."},{"t":"Đồng bào đi xin xâu, chúng mình phải đi theo ủng hộ họ, để làm thông ngôn cho họ. Nào chúng ta cùng đi xuống tòa khâm! — Lời trò Côn, theo hồi ký của ông Lê Thanh Cảnh"},{"t":"Người đứng giữa hai thứ tiếng. Theo tài liệu của nhà nghiên cứu Nguyễn Hữu Châu Phan, trò Côn đã vào trước, gặp các viên quan Pháp và trình bày bằng tiếng Pháp nguyện vọng của bà con. Sau đó, anh dịch lại những lời đối đáp giữa quan Pháp với người dân. Vai trò ấy nghe thì đơn giản, nhưng đầy hiểm nguy. Người thông ngôn đứng ở chỗ dễ thấy nhất, nói những điều nhà cầm quyền không muốn nghe, bằng chính ngôn ngữ của nhà cầm quyền. Với đám đông, anh là tiếng nói của họ. Với viên chức Pháp, anh là một học sinh trường nhà nước đang đứng về phía người biểu tình. Nhà nghiên cứu Hà Văn Thịnh viết rằng dù nhà cầm quyền đã chịu thương thuyết, cuộc biểu tình vẫn bị đàn áp. Ông Lê Thanh Cảnh nhớ lại cảnh lính khố xanh dùng gậy tre quất túi bụi vào đám đông. Theo lời ông, trò Côn hôm ấy đi đầu, lại là người cao lớn, nên “lãnh đủ hơn ai hết”. Đó là cái giá đầu tiên người thanh niên phải trả. Tiếng Pháp, thứ ngôn ngữ nhà trường dạy để đào tạo người phục vụ bộ máy bảo hộ, lần đầu được anh dùng để nói thay cho người dân bị áp bức."},{"t":"Những ngày đàn áp. Cuộc biểu tình ở Huế không dừng lại sau buổi sáng 11/4. Theo báo cáo của người Pháp, ngày 12/4, một đội khoảng một trăm lính bộ binh hải quân được phái đến Công Lương và bắt giữ ba mươi tư người biểu tình. Ngày 13 và 14/4, biểu tình vẫn tiếp diễn trong thành phố. Hai người biểu tình bị thương khá nặng vì bị đánh bằng báng súng. Báo cáo ghi nhận tổng cộng sáu mươi tư người bị bắt. Phong trào ở Thừa Thiên kéo dài chưa đầy một tuần thì bị dập tắt. Ở các tỉnh khác trong Trung Kỳ, sự đàn áp còn khốc liệt hơn. Nhiều nhà nho của phong trào Duy Tân bị quy trách nhiệm, người bị xử tử, người bị đày ra Côn Đảo. Với người thanh niên phiên dịch, hậu quả không đến bằng xiềng xích mà bằng một thứ khác. Theo cuốn tiểu sử của Bảo tàng Hồ Chí Minh, vì những hoạt động yêu nước ấy, Nguyễn Tất Thành bị thực dân Pháp để ý theo dõi. Ông Nguyễn Sinh Huy cũng bị chúng khiển trách vì đã để con trai có những hoạt động bài Pháp. Từ đây, cái tên Nguyễn Sinh Côn đã có trong sổ sách của nhà cầm quyền."},{"t":"Bạn có biết? Trong số ba mươi tư người bị bắt ở Công Lương ngày 12/4/1908, chỉ có mười ba người là dân làng này. Số còn lại từ nhiều làng khác kéo về, cho thấy phong trào đã lan khắp vùng ven kinh đô."},{"t":"Bức thư ngày 7 tháng 8. Nhiều sách phổ thông từng viết rằng sau cuộc biểu tình, Nguyễn Tất Thành bị đuổi khỏi Trường Quốc Học. Tư liệu lưu trữ tìm được về sau cho thấy câu chuyện có phần khác. Ngày 4/8/1908, Khâm sứ Trung Kỳ Lévecque gửi thư yêu cầu hiệu trưởng Trường Quốc Học cho biết lai lịch của Nguyễn Sinh Côn. Đây là một trong những học sinh vừa đỗ tiểu học và được chuyển lên Quốc Học. Chỉ ba ngày sau, ngày 7/8/1908, hiệu trưởng Chouquet gửi văn thư phúc đáp. Những giấy tờ này nằm trong bộ hồ sơ mà mật thám Pháp lập về Nguyễn Ái Quốc, hiện lưu tại Trung tâm Lưu trữ hải ngoại ở Aix-en-Provence, nước Pháp. Bảo tàng Hồ Chí Minh ở Huế lưu giữ bản thư của ông Chouquet như một hiện vật. Việc Khâm sứ đích thân hỏi đến một học trò mười tám tuổi cho thấy buổi sáng tháng Tư đã để lại dấu vết trong mắt chính quyền. Nhưng câu trả lời của nhà trường lại mở cửa cho anh. Cuốn tiểu sử của Bảo tàng Hồ Chí Minh ghi rõ: tháng 8/1908, anh vẫn được ông Chouquet tiếp nhận; tháng 9/1908, anh vào lớp trung đẳng của Trường Quốc Học."},{"t":"Tôi hân hạnh báo cho ngài rõ sẽ có thể tiếp nhận vào Trường Quốc Học học sinh có tên Nguyễn Sinh Côn, gốc người Nghệ An, học sinh Trường Pháp – An Nam tỉnh Thừa Thiên. — Hiệu trưởng Trường Quốc Học Chouquet, thư phúc đáp Khâm sứ Trung Kỳ ngày 7/8/1908, bản dịch"},{"t":"Rời trường, rời Huế. Vậy anh rời Quốc Học như thế nào? Một số tài liệu cho rằng chỉ sau vài tháng, anh bị đuổi học vì thái độ ngang bướng với những thầy giáo Pháp coi thường học trò Việt. Các nhà nghiên cứu Nguyễn Đắc Xuân và Nguyễn Hồng Việt lại cho rằng anh không bị đuổi học. Theo ông Xuân, vì bị theo dõi, anh đã tự nghỉ học, ẩn ở Huế một thời gian rồi theo cha vào Bình Định. Bảo tàng Hồ Chí Minh chi nhánh Thừa Thiên Huế xác định lập luận này là phù hợp. Cuốn tiểu sử của Bảo tàng Hồ Chí Minh ghi rằng khoảng tháng 6/1909, anh rời Trường Quốc Học theo cha vào Bình Định, khi ông được bổ làm Tri huyện Bình Khê. Dù chi tiết còn được bàn luận, các nguồn đều thống nhất rằng từ sau tháng 4/1908, người học trò đã bị chính quyền thuộc địa để mắt tới. Anh cũng không đi theo con đường làm thông ngôn, làm công chức cho nhà nước bảo hộ. Từ Bình Định, anh xuôi vào Phan Thiết dạy học ở Trường Dục Thanh, rồi vào Sài Gòn. Ngày 5/6/1911, anh rời Bến Nhà Rồng ra đi tìm đường cứu nước."},{"t":"Từ thông ngôn cho dân đến tiếng nói của dân tộc. Thứ tiếng Pháp mà người học trò dùng để thông ngôn cho nông dân Thừa Thiên, ít năm sau đã trở thành công cụ để Nguyễn Ái Quốc viết báo ở Paris. Từ những bài báo viết trong những năm 1921 – 1924, Người bổ sung, sửa chữa thành cuốn Bản án chế độ thực dân Pháp. Cuốn sách tố cáo tội ác của chủ nghĩa thực dân Pháp đối với người dân các thuộc địa, và kêu gọi các dân tộc bị áp bức thức tỉnh. Câu chuyện khép lại một vòng tròn vào năm 1945. Sáng 3/9/1945, tại phiên họp đầu tiên của Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa, Chủ tịch Hồ Chí Minh nêu sáu vấn đề cấp bách. Một trong số đó là xóa bỏ ngay những thứ thuế bóc lột vô nhân đạo. Chính phủ sau đó ban hành các sắc lệnh bãi bỏ thuế thân, thuế chợ, thuế đò. Thuế thân từng là một trong những gánh nặng khiến nông dân Trung Kỳ nổi dậy năm 1908. Ba mươi bảy năm sau, chính người học trò làm thông ngôn năm xưa cùng Chính phủ của Người đã xóa bỏ nó."},{"t":"Dấu tích hôm nay. Tòa Khâm sứ Trung Kỳ được dựng từ năm 1878 ở bờ nam sông Hương, theo một hiệp ước ký năm 1874. Theo nhà nghiên cứu Phan Thuận An, khu đất ấy nay thuộc Trường Đại học Sư phạm Huế. Dãy công sở thời Pháp ở bờ nam phần lớn nằm lùi vào lề phía nam con đường ven sông, thời Pháp mang tên Jules Ferry, nay là đường Lê Lợi. Trên cùng con đường ấy có Trường Quốc Học, nơi người học trò bước vào học mấy tháng sau cuộc biểu tình. Ngày nay, sinh viên sư phạm, những thầy cô giáo tương lai, học tập ngay trên mảnh đất từng chứng kiến hoạt động đấu tranh đầu tiên của Nguyễn Tất Thành. Ở Bảo tàng Hồ Chí Minh thành phố Huế, khách tham quan có thể tìm hiểu về những năm tháng Người sống ở kinh đô, trong đó có phong trào chống thuế năm 1908. Đi dọc đường Lê Lợi bên sông Hương, từ Trường Quốc Học đến khu Tòa Khâm sứ cũ, người hôm nay có thể hình dung lại khung cảnh buổi sáng tháng Tư năm 1908. Đó là buổi sáng một người học trò lật ngược chiếc nón và bước lên đứng về phía nhân dân."}],"so_chu":2315},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ làng Sen đến Bến Nhà Rồng: những mốc thời gian gắn với kinh đô Huế","sapo":"Hai lần vào kinh, cách nhau năm năm ở quê nhà, rồi một hành trình xuôi về phương Nam. Xếp các mốc theo thứ tự, ta thấy Huế chiếm trọn tuổi thơ và tuổi thiếu niên của Người. Cũng từ những mốc ấy, ta thấy tư liệu lưu trữ đã giúp đính chính những điều từng được kể lại suốt nhiều năm.","bia":{"src":"textures/bai/G02_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Hai chặng ở kinh đô","text":"Dòng thời gian của gian trưng bày này trải từ năm 1890 đến năm 1911, nhưng tâm điểm là hai chặng sống ở Huế. Chặng thứ nhất, từ cuối năm 1895 đến đầu năm 1901, gắn với con đường khoa cử của ông Nguyễn Sinh Sắc. Gia đình theo ông vào kinh khi ông học Quốc Tử Giám chờ khoa thi Hội, rồi rời kinh sau khi bà Hoàng Thị Loan qua đời. Chặng thứ hai, từ cuối tháng 5/1906 đến khoảng giữa năm 1909, gắn với việc ông ra làm quan ở Bộ Lễ. Giữa hai chặng là năm năm ở làng Sen.\n\nCộng lại, Nguyễn Sinh Cung, rồi Nguyễn Tất Thành, sống ở Huế hơn tám năm, gần một nửa quãng đời tính từ lúc chào đời đến khi rời Huế. Hai chặng ấy ứng với hai lứa tuổi rất khác nhau: một cậu bé từ năm đến mười một tuổi, và một thiếu niên từ mười sáu đến mười chín tuổi. Cậu bé thứ nhất nhìn kinh đô qua vòng tay của mẹ. Người thiếu niên thứ hai nhìn kinh đô bằng đôi mắt của chính mình.","doc":1},{"loai":"anh","src":"textures/bang_w/G02_3_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn từ xa."},{"loai":"moc","items":[["19/5/1890","Nguyễn Sinh Cung chào đời tại quê ngoại, làng Hoàng Trù, xã Kim Liên, huyện Nam Đàn, tỉnh Nghệ An, là con thứ ba của ông Nguyễn Sinh Sắc và bà Hoàng Thị Loan"],["1894","Ông Nguyễn Sinh Sắc đỗ Cử nhân khoa thi Hương năm Giáp Ngọ tại trường thi Nghệ An"],["1895","Ông Sắc vào kinh đô Huế dự thi Hội nhưng không đỗ, xin vào học Trường Quốc Tử Giám để chuẩn bị cho khoa sau"],["Cuối năm 1895","Bà Hoàng Thị Loan cùng hai con trai Nguyễn Sinh Khiêm, Nguyễn Sinh Cung theo ông Sắc đi bộ vào Huế; con gái đầu Nguyễn Thị Thanh ở lại quê với bà ngoại"],["1895 – 1898","Gia đình ở nhờ người quen, ở tạm trại lính gần Viện Đô sát, rồi ở nhờ nhà một người quen trong Thành Nội, nay là nhà lưu niệm trên đường Mai Thúc Loan; bà Loan dệt vải, ông Sắc chép chữ thuê"],["1898","Ông Sắc dự thi Hội lần thứ hai, vẫn không đỗ"],["Gần cuối năm 1898","Theo lời mời của ông Nguyễn Sĩ Độ, ông Sắc về dạy học ở làng Dương Nỗ, cách Huế khoảng sáu cây số; Nguyễn Sinh Cung theo cha và bắt đầu học chữ Hán"],["Cuối năm 1900","Ông Sắc được cử đi làm việc ở trường thi Hương Thanh Hóa, đưa con trưởng đi cùng; Nguyễn Sinh Cung về Thành Nội sống với mẹ; bà Loan sinh con út Nguyễn Sinh Nhuận, thường gọi là bé Xin"],["10/2/1901","Tức 22 tháng Chạp năm Canh Tý: bà Hoàng Thị Loan qua đời tại Huế khi mới 33 tuổi, được an táng trên triền núi Bân ở bờ nam sông Hương"],["Đầu năm 1901","Ông Sắc trở về Huế, đưa các con về quê; ít lâu sau, bé Xin cũng qua đời"],["Tháng 5/1901","Ông Sắc dự khoa thi Hội năm Tân Sửu với tên mới là Nguyễn Sinh Huy và đỗ Phó bảng"],["Khoảng tháng 9/1901","Gia đình về sống ở quê nội làng Kim Liên; trong lễ vào làng, Nguyễn Sinh Khiêm được đặt tên là Nguyễn Tất Đạt, Nguyễn Sinh Cung được đặt tên là Nguyễn Tất Thành"],["1901 – 1906","Nguyễn Tất Thành học chữ Hán ở quê với các thầy đồ, trong đó có thầy Vương Thúc Quý"],["Cuối tháng 5/1906","Ông Nguyễn Sinh Huy vào kinh nhậm chức Thừa biện Bộ Lễ, đưa hai con trai theo; gia đình ở một căn phòng trong Dãy Trại trên đường Đông Ba"],["Tháng 9/1906","Nguyễn Tất Thành cùng anh vào lớp dự bị Trường tiểu học Pháp – Việt Đông Ba của tỉnh Thừa Thiên"],["Tháng 9/1907","Nguyễn Tất Thành lên lớp sơ đẳng ở trường Đông Ba"],["Mùa thu 1907","Chính quyền bảo hộ buộc vua Thành Thái thoái vị; người con trai nhỏ tuổi của ông lên ngôi, lấy niên hiệu Duy Tân"],["Tháng 3/1908","Phong trào chống sưu thuế bùng lên ở Quảng Nam, rồi lan ra nhiều tỉnh Trung Kỳ"],["9 – 10/4/1908","Nông dân nhiều làng phía nam Thừa Thiên tập trung ở các tổng An Cựu, Cư Chánh, rồi kéo về các làng An Hòa, An Cựu, Công Lương ven kinh đô; dân Công Lương bắt trói viên Phủ doãn"],["11/4/1908","Khoảng một nghìn người vây quanh Tòa Khâm sứ Trung Kỳ đòi giảm thuế; học trò Nguyễn Tất Thành đi cùng đoàn biểu tình và làm thông ngôn cho bà con"],["12 – 14/4/1908","Lính Pháp được phái đến Công Lương bắt người; biểu tình tiếp diễn trong thành phố rồi bị dập tắt; Nguyễn Tất Thành bắt đầu bị theo dõi, ông Nguyễn Sinh Huy bị khiển trách"],["4/8/1908","Khâm sứ Trung Kỳ gửi thư hỏi hiệu trưởng Trường Quốc Học về lai lịch học sinh Nguyễn Sinh Côn"],["7/8/1908","Hiệu trưởng Chouquet phúc đáp, cho biết nhà trường có thể tiếp nhận học sinh Nguyễn Sinh Côn"],["Tháng 9/1908","Nguyễn Tất Thành vào lớp trung đẳng Trường Quốc Học Huế, nơi có những thầy giáo yêu nước như thầy Hoàng Thông, thầy Lê Văn Miến"],["Khoảng tháng 6/1909","Rời Trường Quốc Học, theo cha vào Bình Định khi ông được bổ làm Tri huyện Bình Khê"],["1910","Ông Nguyễn Sinh Huy bị cách chức; Nguyễn Tất Thành không trở về Huế mà đi tiếp vào Nam, làm trợ giáo ở Trường Dục Thanh, Phan Thiết"],["5/6/1911","Rời Bến Nhà Rồng, Sài Gòn, trên tàu Amiral Latouche-Tréville, bắt đầu hành trình ra đi tìm đường cứu nước"],["1922","Bà Nguyễn Thị Thanh dời hài cốt mẹ từ núi Bân về an táng ở quê nhà Nghệ An"],["1990","Nhân kỷ niệm 100 năm ngày sinh Chủ tịch Hồ Chí Minh, nhà bia tưởng niệm bà Hoàng Thị Loan được dựng tại vị trí huyệt mộ cũ trên núi Bân"],["2/2/1993","Ngôi nhà ở đường Mai Thúc Loan được xếp hạng di tích lịch sử văn hóa cấp quốc gia"],["31/12/2020","Nhà lưu niệm ở đường Mai Thúc Loan và ở làng Dương Nỗ được Thủ tướng Chính phủ xếp hạng di tích quốc gia đặc biệt"]],"doc":2},{"loai":"ban_co_biet","text":"Lớp học của ông Nguyễn Sinh Sắc ở làng Dương Nỗ rất đơn sơ: giữa nhà là bộ phản gỗ gõ để thầy ngồi dạy, hai bên là hai bộ phản cho học trò. Cậu bé Nguyễn Sinh Cung học những chữ Hán đầu tiên ở đây.","nguon_ten":"Báo Dân trí – Chuyện chưa kể về 2 ngôi nhà gắn với năm tháng ấu thơ của Bác Hồ tại Huế, 17/1/2021","doc":3},{"loai":"doan","tieu_de":"Nhịp ba năm của khoa cử","text":"Các mốc của chặng thứ nhất đi theo nhịp thi cử của triều Nguyễn. Ông Nguyễn Sinh Sắc đỗ Cử nhân khoa thi Hương năm Giáp Ngọ 1894, rồi vào kinh thi Hội các năm Ất Mùi 1895, Mậu Tuất 1898 và Tân Sửu 1901. Khoảng cách đều đặn ba năm ấy quyết định nơi ở của cả gia đình. Trượt khoa đầu, ông ở lại kinh học Quốc Tử Giám và đón vợ con vào. Trượt khoa thứ hai, cuộc sống càng chật vật, ông về Dương Nỗ dạy học. Đến khoa thứ ba, ông đỗ Phó bảng, nhưng niềm vui ấy đến sau nỗi đau mất vợ chỉ khoảng ba tháng.\n\nĐọc các mốc theo nhịp ấy, ta hiểu vì sao tuổi thơ của cậu bé Cung gắn với nhiều lần chuyển chỗ ở. Từ nhà người quen đến gian trại lính gần Viện Đô sát, từ căn nhà trong Thành Nội về làng Dương Nỗ, rồi lại trở về Thành Nội sống với mẹ. Qua tất cả những lần chuyển chỗ ấy, khung cửi của người mẹ vẫn là chỗ dựa của gia đình.","doc":4},{"loai":"doan","tieu_de":"Năm 1901 và những cái tên","text":"Năm 1901 là năm dày đặc biến cố nhất trên dòng thời gian này. Tháng 2, bà Hoàng Thị Loan qua đời; ít lâu sau, bé Xin cũng mất. Tháng 5, ông Sắc đỗ Phó bảng. Khoảng tháng 9, gia đình về quê nội và hai anh em có tên mới. Năm ấy còn cho thấy một điều ít người để ý: các nhân vật trong câu chuyện này mang nhiều tên gọi.\n\nNgười cha dự thi năm 1901 với tên Nguyễn Sinh Huy và dùng tên ấy khi làm quan ở Huế. Người con từ Nguyễn Sinh Cung đổi thành Nguyễn Tất Thành. Trong giấy tờ ở Huế những năm 1906 – 1909, anh lại mang tên Nguyễn Sinh Côn. Về sau, từ năm 1919, Người dùng tên Nguyễn Ái Quốc, và từ tháng 8/1942 là Hồ Chí Minh. Người nghiên cứu vì thế phải nhận ra một con người qua nhiều cái tên khác nhau. Chính cái tên Nguyễn Sinh Côn trong những bức thư năm 1908 đã giúp xác định chính xác thời điểm Người vào Trường Quốc Học.","doc":5},{"loai":"anh","src":"textures/bang_w/G02_3_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Chặng thứ hai: từ chữ Hán sang chữ Pháp","text":"Các mốc của chặng thứ hai lại đi theo nhịp năm học của trường Pháp – Việt, bắt đầu vào tháng 9 hằng năm. Tháng 9/1906, Nguyễn Tất Thành vào lớp dự bị Trường tiểu học Pháp – Việt Đông Ba. Tháng 9/1907, anh lên lớp sơ đẳng. Tháng 9/1908, anh vào lớp trung đẳng của Trường Quốc Học. Ba mốc tháng 9 liên tiếp cho thấy một thanh niên mười sáu tuổi bắt đầu lại từ lớp đầu tiên của một nền học hoàn toàn mới, rồi tiến lên rất nhanh.\n\nTrước đó, anh đã có khoảng bảy, tám năm học chữ Hán, từ lớp học của cha ở Dương Nỗ đến các thầy đồ ở làng Sen. Một người đã thông chữ Hán chịu ngồi học lại từ đầu bằng tiếng Pháp, điều đó cho thấy mong muốn tìm hiểu nền văn minh phương Tây đã thành hình từ sớm. Những tháng năm ấy trao cho anh công cụ quan trọng cho hành trình về sau: ngôn ngữ của chính những người đang cai trị đất nước mình.","doc":6},{"loai":"doan","tieu_de":"Lịch sử lớn chạy song song","text":"Đặt các mốc đời riêng bên cạnh các mốc của đất nước, ta thấy rõ hơn thời đại của cậu học trò. Nguyễn Sinh Cung ra đời năm 1890, sáu năm sau Hòa ước Patenôtre năm 1884 xác lập chế độ bảo hộ của Pháp, và năm năm sau ngày thất thủ Kinh đô năm 1885. Khi gia đình vào kinh cuối năm 1895, vua Thành Thái đã ở ngôi sáu năm. Năm 1899, cầu Trường Tiền được xây dựng xong, nối Kinh thành với khu phố của người Pháp ở bờ nam.\n\nMùa thu năm 1907, vua Thành Thái bị buộc thoái vị, đúng lúc Tất Thành bước vào năm học thứ hai ở trường Đông Ba. Tháng 3/1908, phong trào chống sưu thuế nổ ra ở Quảng Nam, chỉ một tháng sau đã lan đến Huế. Những biến cố của đất nước không đứng ngoài đời riêng của người học trò. Chúng đi vào căn phòng ở Dãy Trại, vào lớp học, và cuối cùng đưa anh ra đứng giữa đám đông trước Tòa Khâm sứ vào tháng 4/1908 (xem chuyên đề Người phiên dịch cho đoàn nông dân).","doc":7},{"loai":"ban_co_biet","text":"Theo các mốc trong cuốn tiểu sử của Bảo tàng Hồ Chí Minh, Nguyễn Tất Thành học ở Trường Quốc Học chỉ khoảng chín tháng, từ tháng 9/1908 đến khoảng tháng 6/1909.","nguon_ten":"Bảo tàng Hồ Chí Minh – Hồ Chí Minh: Tiểu sử, NXB Chính trị quốc gia, 2008","doc":8},{"loai":"doan","tieu_de":"Khi tư liệu lưu trữ đính chính một mốc","text":"Không phải mốc nào trên dòng thời gian cũng được biết chính xác ngay từ đầu. Nhiều sách phổ thông trước đây ghi rằng Nguyễn Tất Thành vào Trường Quốc Học từ năm 1907, tham gia biểu tình chống thuế vào tháng 5/1908 và bị đuổi học ngay sau đó. Các tư liệu công bố về sau đã làm rõ nhiều điều. Báo cáo của viên Công sứ Thừa Thiên, lưu tại Trung tâm Lưu trữ quốc gia IV, cho thấy các cuộc biểu tình ở Huế bắt đầu từ ngày 9/4/1908 và kéo dài chưa đầy một tuần.\n\nBức thư ngày 7/8/1908 của hiệu trưởng Chouquet, lưu tại Aix-en-Provence, cho thấy Nguyễn Sinh Côn được nhận vào Quốc Học sau cuộc biểu tình, chứ không phải trước đó. Bảo tàng Hồ Chí Minh chi nhánh Thừa Thiên Huế cũng xác định anh tham gia biểu tình khi còn là học sinh trường Đông Ba. Cuốn tiểu sử do Bảo tàng Hồ Chí Minh biên soạn năm 2008 ghi các mốc phù hợp với những tư liệu ấy. Dòng thời gian trong bài này đi theo các mốc đã được đính chính.","doc":9},{"loai":"anh","src":"textures/bang_w/G02_3_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Từ Huế đến Bến Nhà Rồng","text":"Sau Huế, các mốc trên dòng thời gian dồn dập hơn. Khoảng tháng 6/1909, Tất Thành theo cha vào Bình Khê, Bình Định. Ở đó, anh thường được cha dẫn đi thăm các sĩ phu trong vùng và thăm di tích lịch sử vùng Tây Sơn. Năm 1910, nghe tin cha bị cách chức và bị triệu hồi về kinh, anh không trở lại Huế mà đi tiếp về phương Nam. Dừng chân ở Phan Thiết, anh làm trợ giáo ở Trường Dục Thanh, một trường tư thục thành lập năm 1907, gắn với gia đình nhà nho yêu nước Nguyễn Thông.\n\nRồi anh vào Sài Gòn. Ngày 5/6/1911, người thanh niên hai mươi mốt tuổi rời Bến Nhà Rồng trên tàu Amiral Latouche-Tréville. Từ ngày rời Huế đến ngày xuống tàu chỉ khoảng hai năm. Nhìn trên dòng thời gian, Huế là chặng dài nhất và gần nhất trước chuyến đi ấy. Ở đó, người thanh niên có được tiếng Pháp, có được những câu hỏi về vận mệnh dân tộc, và có bài học đầu tiên về sức mạnh cũng như giới hạn của những cuộc đấu tranh tự phát.","doc":10},{"loai":"anh","src":"textures/ht/ht_anh_tuong_nguyen_tat_thanh_tai_quoc_hoc_hue.jpg","chu_thich":"Tượng người học trò Nguyễn Tất Thành trong sân Trường Quốc Học Huế, ảnh chụp năm 2008.","credit":"Ảnh: Lưu Ly at Vietnamese Wikipedia · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Những mốc của ký ức","text":"Dòng thời gian không dừng lại ở năm 1911. Có những mốc đến sau, khi con người đã đi xa nhưng ký ức vẫn được gìn giữ. Năm 1922, người chị cả Nguyễn Thị Thanh dời hài cốt mẹ từ núi Bân về quê. Năm 1990, nhân kỷ niệm một trăm năm ngày sinh Chủ tịch Hồ Chí Minh, thành phố Huế dựng nhà bia tưởng niệm trên vị trí huyệt mộ cũ. Năm 1993, ngôi nhà trong Thành Nội được xếp hạng di tích quốc gia. Năm 2008, nơi an táng ban đầu của bà Hoàng Thị Loan được công nhận là di tích cấp tỉnh.\n\nNgày 31/12/2020, hai ngôi nhà ở đường Mai Thúc Loan và làng Dương Nỗ được nâng lên hàng di tích quốc gia đặc biệt. Cuối năm 2025, khu nhà bia trên núi Bân được tu bổ, tôn tạo. Mỗi địa điểm ấy là một mốc thời gian được đánh dấu trên mặt đất. Người hôm nay có thể lần theo chúng, từ căn nhà nhỏ trong Thành Nội đến sân trường Quốc Học, để đi lại hành trình của cậu bé làng Sen giữa kinh đô.","doc":11}],"nguon":["Bảo tàng Hồ Chí Minh – Hồ Chí Minh: Tiểu sử, NXB Chính trị quốc gia, Hà Nội, 2008 (bản điện tử: https://tulieuvankien.dangcongsan.vn/c-mac-angghen-lenin-ho-chi-minh/book/ho-chi-minh/tieu-su-cuoc-doi-va-su-nghiep/ho-chi-minh-tieu-su-bao-tang-ho-chi-minh-nxb-chinh-tri-quoc-gia-ha-noi-nam-2008-20)","Minh Đăng – Nguyễn Tất Thành ra đi từ ngôi trường xứ Huế, Tuổi Trẻ Online, 13/2/2018: https://tuoitre.vn/nguyen-tat-thanh-ra-di-tu-ngoi-truong-xu-hue-20180205104555229.htm","Trung tâm Lưu trữ quốc gia IV – Phong trào chống thuế tại Huế năm 1908 qua báo cáo của người Pháp: https://mocban.vn/phong-trao-chong-thue-tai-hue-nam-1908-qua-bao-cao-cua-nguoi-phap/","Báo Dân trí – Chuyện chưa kể về 2 ngôi nhà gắn với năm tháng ấu thơ của Bác Hồ tại Huế, 17/1/2021: https://dantri.com.vn/du-lich/chuyen-chua-ke-ve-2-ngoi-nha-gan-voi-nam-thang-au-tho-cua-bac-ho-tai-hue-20210117161721895.htm","Báo Dân trí – Diện mạo mới địa điểm mai táng ban đầu thân mẫu Bác Hồ, 19/5/2026: https://dantri.com.vn/thoi-su/dien-mao-moi-dia-diem-mai-tang-ban-dau-than-mau-bac-ho-20260519181432975.htm","VTV.vn – Ngôi nhà lưu dấu tuổi thơ của Bác Hồ ở Huế, 18/5/2025: https://vtv.vn/doi-song/ngoi-nha-luu-dau-tuoi-tho-cua-bac-ho-o-hue-20250518051708808.htm"],"doc":[{"t":"Từ làng Sen đến Bến Nhà Rồng: những mốc thời gian gắn với kinh đô Huế. Hai lần vào kinh, cách nhau năm năm ở quê nhà, rồi một hành trình xuôi về phương Nam. Xếp các mốc theo thứ tự, ta thấy Huế chiếm trọn tuổi thơ và tuổi thiếu niên của Người. Cũng từ những mốc ấy, ta thấy tư liệu lưu trữ đã giúp đính chính những điều từng được kể lại suốt nhiều năm."},{"t":"Hai chặng ở kinh đô. Dòng thời gian của gian trưng bày này trải từ năm 1890 đến năm 1911, nhưng tâm điểm là hai chặng sống ở Huế. Chặng thứ nhất, từ cuối năm 1895 đến đầu năm 1901, gắn với con đường khoa cử của ông Nguyễn Sinh Sắc. Gia đình theo ông vào kinh khi ông học Quốc Tử Giám chờ khoa thi Hội, rồi rời kinh sau khi bà Hoàng Thị Loan qua đời. Chặng thứ hai, từ cuối tháng 5/1906 đến khoảng giữa năm 1909, gắn với việc ông ra làm quan ở Bộ Lễ. Giữa hai chặng là năm năm ở làng Sen. Cộng lại, Nguyễn Sinh Cung, rồi Nguyễn Tất Thành, sống ở Huế hơn tám năm, gần một nửa quãng đời tính từ lúc chào đời đến khi rời Huế. Hai chặng ấy ứng với hai lứa tuổi rất khác nhau: một cậu bé từ năm đến mười một tuổi, và một thiếu niên từ mười sáu đến mười chín tuổi. Cậu bé thứ nhất nhìn kinh đô qua vòng tay của mẹ. Người thiếu niên thứ hai nhìn kinh đô bằng đôi mắt của chính mình."},{"t":"Các mốc thời gian. 19/5/1890: Nguyễn Sinh Cung chào đời tại quê ngoại, làng Hoàng Trù, xã Kim Liên, huyện Nam Đàn, tỉnh Nghệ An, là con thứ ba của ông Nguyễn Sinh Sắc và bà Hoàng Thị Loan. 1894: Ông Nguyễn Sinh Sắc đỗ Cử nhân khoa thi Hương năm Giáp Ngọ tại trường thi Nghệ An. 1895: Ông Sắc vào kinh đô Huế dự thi Hội nhưng không đỗ, xin vào học Trường Quốc Tử Giám để chuẩn bị cho khoa sau. Cuối năm 1895: Bà Hoàng Thị Loan cùng hai con trai Nguyễn Sinh Khiêm, Nguyễn Sinh Cung theo ông Sắc đi bộ vào Huế; con gái đầu Nguyễn Thị Thanh ở lại quê với bà ngoại. 1895 – 1898: Gia đình ở nhờ người quen, ở tạm trại lính gần Viện Đô sát, rồi ở nhờ nhà một người quen trong Thành Nội, nay là nhà lưu niệm trên đường Mai Thúc Loan; bà Loan dệt vải, ông Sắc chép chữ thuê. 1898: Ông Sắc dự thi Hội lần thứ hai, vẫn không đỗ. Gần cuối năm 1898: Theo lời mời của ông Nguyễn Sĩ Độ, ông Sắc về dạy học ở làng Dương Nỗ, cách Huế khoảng sáu cây số; Nguyễn Sinh Cung theo cha và bắt đầu học chữ Hán. Cuối năm 1900: Ông Sắc được cử đi làm việc ở trường thi Hương Thanh Hóa, đưa con trưởng đi cùng; Nguyễn Sinh Cung về Thành Nội sống với mẹ; bà Loan sinh con út Nguyễn Sinh Nhuận, thường gọi là bé Xin. 10/2/1901: Tức 22 tháng Chạp năm Canh Tý: bà Hoàng Thị Loan qua đời tại Huế khi mới 33 tuổi, được an táng trên triền núi Bân ở bờ nam sông Hương. Đầu năm 1901: Ông Sắc trở về Huế, đưa các con về quê; ít lâu sau, bé Xin cũng qua đời. Tháng 5/1901: Ông Sắc dự khoa thi Hội năm Tân Sửu với tên mới là Nguyễn Sinh Huy và đỗ Phó bảng. Khoảng tháng 9/1901: Gia đình về sống ở quê nội làng Kim Liên; trong lễ vào làng, Nguyễn Sinh Khiêm được đặt tên là Nguyễn Tất Đạt, Nguyễn Sinh Cung được đặt tên là Nguyễn Tất Thành. 1901 – 1906: Nguyễn Tất Thành học chữ Hán ở quê với các thầy đồ, trong đó có thầy Vương Thúc Quý. Cuối tháng 5/1906: Ông Nguyễn Sinh Huy vào kinh nhậm chức Thừa biện Bộ Lễ, đưa hai con trai theo; gia đình ở một căn phòng trong Dãy Trại trên đường Đông Ba. Tháng 9/1906: Nguyễn Tất Thành cùng anh vào lớp dự bị Trường tiểu học Pháp – Việt Đông Ba của tỉnh Thừa Thiên. Tháng 9/1907: Nguyễn Tất Thành lên lớp sơ đẳng ở trường Đông Ba. Mùa thu 1907: Chính quyền bảo hộ buộc vua Thành Thái thoái vị; người con trai nhỏ tuổi của ông lên ngôi, lấy niên hiệu Duy Tân. Tháng 3/1908: Phong trào chống sưu thuế bùng lên ở Quảng Nam, rồi lan ra nhiều tỉnh Trung Kỳ. 9 – 10/4/1908: Nông dân nhiều làng phía nam Thừa Thiên tập trung ở các tổng An Cựu, Cư Chánh, rồi kéo về các làng An Hòa, An Cựu, Công Lương ven kinh đô; dân Công Lương bắt trói viên Phủ doãn. 11/4/1908: Khoảng một nghìn người vây quanh Tòa Khâm sứ Trung Kỳ đòi giảm thuế; học trò Nguyễn Tất Thành đi cùng đoàn biểu tình và làm thông ngôn cho bà con. 12 – 14/4/1908: Lính Pháp được phái đến Công Lương bắt người; biểu tình tiếp diễn trong thành phố rồi bị dập tắt; Nguyễn Tất Thành bắt đầu bị theo dõi, ông Nguyễn Sinh Huy bị khiển trách. 4/8/1908: Khâm sứ Trung Kỳ gửi thư hỏi hiệu trưởng Trường Quốc Học về lai lịch học sinh Nguyễn Sinh Côn. 7/8/1908: Hiệu trưởng Chouquet phúc đáp, cho biết nhà trường có thể tiếp nhận học sinh Nguyễn Sinh Côn. Tháng 9/1908: Nguyễn Tất Thành vào lớp trung đẳng Trường Quốc Học Huế, nơi có những thầy giáo yêu nước như thầy Hoàng Thông, thầy Lê Văn Miến. Khoảng tháng 6/1909: Rời Trường Quốc Học, theo cha vào Bình Định khi ông được bổ làm Tri huyện Bình Khê. 1910: Ông Nguyễn Sinh Huy bị cách chức; Nguyễn Tất Thành không trở về Huế mà đi tiếp vào Nam, làm trợ giáo ở Trường Dục Thanh, Phan Thiết. 5/6/1911: Rời Bến Nhà Rồng, Sài Gòn, trên tàu Amiral Latouche-Tréville, bắt đầu hành trình ra đi tìm đường cứu nước. 1922: Bà Nguyễn Thị Thanh dời hài cốt mẹ từ núi Bân về an táng ở quê nhà Nghệ An. 1990: Nhân kỷ niệm 100 năm ngày sinh Chủ tịch Hồ Chí Minh, nhà bia tưởng niệm bà Hoàng Thị Loan được dựng tại vị trí huyệt mộ cũ trên núi Bân. 2/2/1993: Ngôi nhà ở đường Mai Thúc Loan được xếp hạng di tích lịch sử văn hóa cấp quốc gia. 31/12/2020: Nhà lưu niệm ở đường Mai Thúc Loan và ở làng Dương Nỗ được Thủ tướng Chính phủ xếp hạng di tích quốc gia đặc biệt."},{"t":"Bạn có biết? Lớp học của ông Nguyễn Sinh Sắc ở làng Dương Nỗ rất đơn sơ: giữa nhà là bộ phản gỗ gõ để thầy ngồi dạy, hai bên là hai bộ phản cho học trò. Cậu bé Nguyễn Sinh Cung học những chữ Hán đầu tiên ở đây."},{"t":"Nhịp ba năm của khoa cử. Các mốc của chặng thứ nhất đi theo nhịp thi cử của triều Nguyễn. Ông Nguyễn Sinh Sắc đỗ Cử nhân khoa thi Hương năm Giáp Ngọ 1894, rồi vào kinh thi Hội các năm Ất Mùi 1895, Mậu Tuất 1898 và Tân Sửu 1901. Khoảng cách đều đặn ba năm ấy quyết định nơi ở của cả gia đình. Trượt khoa đầu, ông ở lại kinh học Quốc Tử Giám và đón vợ con vào. Trượt khoa thứ hai, cuộc sống càng chật vật, ông về Dương Nỗ dạy học. Đến khoa thứ ba, ông đỗ Phó bảng, nhưng niềm vui ấy đến sau nỗi đau mất vợ chỉ khoảng ba tháng. Đọc các mốc theo nhịp ấy, ta hiểu vì sao tuổi thơ của cậu bé Cung gắn với nhiều lần chuyển chỗ ở. Từ nhà người quen đến gian trại lính gần Viện Đô sát, từ căn nhà trong Thành Nội về làng Dương Nỗ, rồi lại trở về Thành Nội sống với mẹ. Qua tất cả những lần chuyển chỗ ấy, khung cửi của người mẹ vẫn là chỗ dựa của gia đình."},{"t":"Năm 1901 và những cái tên. Năm 1901 là năm dày đặc biến cố nhất trên dòng thời gian này. Tháng 2, bà Hoàng Thị Loan qua đời; ít lâu sau, bé Xin cũng mất. Tháng 5, ông Sắc đỗ Phó bảng. Khoảng tháng 9, gia đình về quê nội và hai anh em có tên mới. Năm ấy còn cho thấy một điều ít người để ý: các nhân vật trong câu chuyện này mang nhiều tên gọi. Người cha dự thi năm 1901 với tên Nguyễn Sinh Huy và dùng tên ấy khi làm quan ở Huế. Người con từ Nguyễn Sinh Cung đổi thành Nguyễn Tất Thành. Trong giấy tờ ở Huế những năm 1906 – 1909, anh lại mang tên Nguyễn Sinh Côn. Về sau, từ năm 1919, Người dùng tên Nguyễn Ái Quốc, và từ tháng 8/1942 là Hồ Chí Minh. Người nghiên cứu vì thế phải nhận ra một con người qua nhiều cái tên khác nhau. Chính cái tên Nguyễn Sinh Côn trong những bức thư năm 1908 đã giúp xác định chính xác thời điểm Người vào Trường Quốc Học."},{"t":"Chặng thứ hai: từ chữ Hán sang chữ Pháp. Các mốc của chặng thứ hai lại đi theo nhịp năm học của trường Pháp – Việt, bắt đầu vào tháng 9 hằng năm. Tháng 9/1906, Nguyễn Tất Thành vào lớp dự bị Trường tiểu học Pháp – Việt Đông Ba. Tháng 9/1907, anh lên lớp sơ đẳng. Tháng 9/1908, anh vào lớp trung đẳng của Trường Quốc Học. Ba mốc tháng 9 liên tiếp cho thấy một thanh niên mười sáu tuổi bắt đầu lại từ lớp đầu tiên của một nền học hoàn toàn mới, rồi tiến lên rất nhanh. Trước đó, anh đã có khoảng bảy, tám năm học chữ Hán, từ lớp học của cha ở Dương Nỗ đến các thầy đồ ở làng Sen. Một người đã thông chữ Hán chịu ngồi học lại từ đầu bằng tiếng Pháp, điều đó cho thấy mong muốn tìm hiểu nền văn minh phương Tây đã thành hình từ sớm. Những tháng năm ấy trao cho anh công cụ quan trọng cho hành trình về sau: ngôn ngữ của chính những người đang cai trị đất nước mình."},{"t":"Lịch sử lớn chạy song song. Đặt các mốc đời riêng bên cạnh các mốc của đất nước, ta thấy rõ hơn thời đại của cậu học trò. Nguyễn Sinh Cung ra đời năm 1890, sáu năm sau Hòa ước Patenôtre năm 1884 xác lập chế độ bảo hộ của Pháp, và năm năm sau ngày thất thủ Kinh đô năm 1885. Khi gia đình vào kinh cuối năm 1895, vua Thành Thái đã ở ngôi sáu năm. Năm 1899, cầu Trường Tiền được xây dựng xong, nối Kinh thành với khu phố của người Pháp ở bờ nam. Mùa thu năm 1907, vua Thành Thái bị buộc thoái vị, đúng lúc Tất Thành bước vào năm học thứ hai ở trường Đông Ba. Tháng 3/1908, phong trào chống sưu thuế nổ ra ở Quảng Nam, chỉ một tháng sau đã lan đến Huế. Những biến cố của đất nước không đứng ngoài đời riêng của người học trò. Chúng đi vào căn phòng ở Dãy Trại, vào lớp học, và cuối cùng đưa anh ra đứng giữa đám đông trước Tòa Khâm sứ vào tháng 4/1908 (xem chuyên đề Người phiên dịch cho đoàn nông dân)."},{"t":"Bạn có biết? Theo các mốc trong cuốn tiểu sử của Bảo tàng Hồ Chí Minh, Nguyễn Tất Thành học ở Trường Quốc Học chỉ khoảng chín tháng, từ tháng 9/1908 đến khoảng tháng 6/1909."},{"t":"Khi tư liệu lưu trữ đính chính một mốc. Không phải mốc nào trên dòng thời gian cũng được biết chính xác ngay từ đầu. Nhiều sách phổ thông trước đây ghi rằng Nguyễn Tất Thành vào Trường Quốc Học từ năm 1907, tham gia biểu tình chống thuế vào tháng 5/1908 và bị đuổi học ngay sau đó. Các tư liệu công bố về sau đã làm rõ nhiều điều. Báo cáo của viên Công sứ Thừa Thiên, lưu tại Trung tâm Lưu trữ quốc gia IV, cho thấy các cuộc biểu tình ở Huế bắt đầu từ ngày 9/4/1908 và kéo dài chưa đầy một tuần. Bức thư ngày 7/8/1908 của hiệu trưởng Chouquet, lưu tại Aix-en-Provence, cho thấy Nguyễn Sinh Côn được nhận vào Quốc Học sau cuộc biểu tình, chứ không phải trước đó. Bảo tàng Hồ Chí Minh chi nhánh Thừa Thiên Huế cũng xác định anh tham gia biểu tình khi còn là học sinh trường Đông Ba. Cuốn tiểu sử do Bảo tàng Hồ Chí Minh biên soạn năm 2008 ghi các mốc phù hợp với những tư liệu ấy. Dòng thời gian trong bài này đi theo các mốc đã được đính chính."},{"t":"Từ Huế đến Bến Nhà Rồng. Sau Huế, các mốc trên dòng thời gian dồn dập hơn. Khoảng tháng 6/1909, Tất Thành theo cha vào Bình Khê, Bình Định. Ở đó, anh thường được cha dẫn đi thăm các sĩ phu trong vùng và thăm di tích lịch sử vùng Tây Sơn. Năm 1910, nghe tin cha bị cách chức và bị triệu hồi về kinh, anh không trở lại Huế mà đi tiếp về phương Nam. Dừng chân ở Phan Thiết, anh làm trợ giáo ở Trường Dục Thanh, một trường tư thục thành lập năm 1907, gắn với gia đình nhà nho yêu nước Nguyễn Thông. Rồi anh vào Sài Gòn. Ngày 5/6/1911, người thanh niên hai mươi mốt tuổi rời Bến Nhà Rồng trên tàu Amiral Latouche-Tréville. Từ ngày rời Huế đến ngày xuống tàu chỉ khoảng hai năm. Nhìn trên dòng thời gian, Huế là chặng dài nhất và gần nhất trước chuyến đi ấy. Ở đó, người thanh niên có được tiếng Pháp, có được những câu hỏi về vận mệnh dân tộc, và có bài học đầu tiên về sức mạnh cũng như giới hạn của những cuộc đấu tranh tự phát."},{"t":"Những mốc của ký ức. Dòng thời gian không dừng lại ở năm 1911. Có những mốc đến sau, khi con người đã đi xa nhưng ký ức vẫn được gìn giữ. Năm 1922, người chị cả Nguyễn Thị Thanh dời hài cốt mẹ từ núi Bân về quê. Năm 1990, nhân kỷ niệm một trăm năm ngày sinh Chủ tịch Hồ Chí Minh, thành phố Huế dựng nhà bia tưởng niệm trên vị trí huyệt mộ cũ. Năm 1993, ngôi nhà trong Thành Nội được xếp hạng di tích quốc gia. Năm 2008, nơi an táng ban đầu của bà Hoàng Thị Loan được công nhận là di tích cấp tỉnh. Ngày 31/12/2020, hai ngôi nhà ở đường Mai Thúc Loan và làng Dương Nỗ được nâng lên hàng di tích quốc gia đặc biệt. Cuối năm 2025, khu nhà bia trên núi Bân được tu bổ, tôn tạo. Mỗi địa điểm ấy là một mốc thời gian được đánh dấu trên mặt đất. Người hôm nay có thể lần theo chúng, từ căn nhà nhỏ trong Thành Nội đến sân trường Quốc Học, để đi lại hành trình của cậu bé làng Sen giữa kinh đô."}],"so_chu":1648},{"i":4,"tieu_de_bang":"Lớp học Trường Quốc Học Huế đầu thế kỷ XX","tieu_de":"Bên trong lớp học Quốc Học: người học trò Nguyễn Sinh Côn và ngôi trường Pháp – Việt","sapo":"Một văn thư hành chính đề ngày 7/8/1908 nhắc đến một cái tên ít người biết: Nguyễn Sinh Côn, quê Nghệ An. Người học trò ấy về sau là Chủ tịch Hồ Chí Minh. Tấm ảnh một lớp học Quốc Học công bố năm 1913 mở cửa vào thế giới mà cậu học trò mười tám tuổi từng sống: những giờ tiếng Pháp, những người thầy yêu nước, và một câu hỏi day dứt về nước Pháp thật sự.","bia":{"src":"textures/ht/ht_anh_college_quoc_hoc_a_hue_2e_annee_complementaire.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một lá thư mang tên Nguyễn Sinh Côn","text":"Ngày 7/8/1908, Hiệu trưởng Trường Quốc Học Huế là ông Chouquet ký văn thư trả lời Khâm sứ Trung Kỳ về một học sinh xin vào trường. Văn thư cho biết nhà trường có thể nhận học sinh Nguyễn Sinh Côn, quê tỉnh Nghệ An, vốn là học trò trường Pháp – Việt. Tài liệu ấy hiện lưu tại kho lưu trữ ở thành phố Aix-en-Provence, miền nam nước Pháp, và đã được các nhà nghiên cứu ở Huế giới thiệu trên báo chí. Cái tên Nguyễn Sinh Côn nghe lạ với nhiều người. Nhưng đó chính là tên dùng trong giấy tờ học đường của người thanh niên mà gia đình và bạn bè gọi là Nguyễn Tất Thành.\n\nTheo cuốn Hồ Chí Minh – Tiểu sử do Bảo tàng Hồ Chí Minh biên soạn, tháng 9/1908, người học trò mười tám tuổi chính thức bước vào lớp trung đẳng, tức lớp nhì, của Trường Quốc Học. Tài liệu của tỉnh Thừa Thiên Huế thì ghi anh thi vượt cấp vào lớp đệ nhị niên, niên khóa 1908 – 1909. Dù cách gọi tên lớp có khác nhau, các nguồn đều cho thấy người học trò được nhận vào trường chỉ vài tháng sau những ngày biến động mùa xuân năm 1908 ở kinh đô.","doc":1},{"loai":"doan","tieu_de":"Tấm ảnh năm 1913","text":"Tấm ảnh ở bảng này mang tên tiếng Pháp là Collège Quốc Học à Hué – 2e année complémentaire, nghĩa là lớp năm thứ hai bậc bổ túc của Trường Quốc Học ở Huế. Người chụp không rõ tên. Ảnh được công bố ngày 3/6/1913 và nay thuộc phạm vi công cộng. Đó không phải lớp học của Nguyễn Tất Thành, và không ai trong ảnh được xác định là bạn học của Người. Nhưng ảnh ra đời chỉ bốn năm sau khi Người rời trường, nên là một trong những hình ảnh gần nhất còn lại về môi trường học tập của Quốc Học thời ấy. Cùng loạt với tấm ảnh này còn có ảnh một giờ thể dục của học sinh Quốc Học (xem chuyên đề Giờ thể dục ở Trường Quốc Học Huế).","doc":2},{"loai":"anh","src":"textures/ht/ht_anh_college_quoc_hoc_a_hue_2e_annee_complementaire.jpg","chu_thich":"Lớp học Trường Quốc Học Huế đầu thế kỷ XX: lớp năm thứ hai bậc bổ túc. Ảnh không rõ người chụp, công bố ngày 3/6/1913, phạm vi công cộng.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Ngôi trường của con nhà quan","text":"Muốn hiểu lớp học trong ảnh, cần trở lại năm 1896. Theo tài liệu lưu trữ do Trung tâm Lưu trữ quốc gia I giới thiệu, trường được lập theo đạo dụ ngày 17 tháng 9 năm Thành Thái thứ tám, tức ngày 23/10/1896, và nghị định ngày 18/11/1896 của Toàn quyền Đông Dương. Trong giấy tờ của người Pháp, trường thuộc bậc cao đẳng tiểu học, nhưng người Huế quen gọi là trường Quốc Học. Học sinh buổi đầu là con các hoàng thân, thanh niên trong hoàng tộc và con em quan lại, tuổi từ mười ba đến hai mươi, cùng những nho sinh đủ trình độ. Bộ máy giảng dạy gồm một trưởng giáo, bốn đốc giáo các hạng và một đốc giáo lo lớp sơ đẳng. Triều đình chịu toàn bộ chi phí về người, đồ dùng và xây cất. Người đứng đầu trường đầu tiên là ông Ngô Đình Khả. Câu chuyện về chiếc cổng và hai chữ Quốc Học trên biển trường được kể ở một bảng khác (xem chuyên đề Cổng Trường Quốc Học).","doc":3},{"loai":"ban_co_biet","text":"Tại Bảo tàng Confluences ở thành phố Lyon, nước Pháp, còn lưu một tấm ảnh nhỏ in trên giấy albumin, cỡ 8,5 x 14 cm, nhan đề Personnel enseignant du collège Quôc Hoc, Indochine. 1908, tức đội ngũ giáo viên Trường Quốc Học năm 1908. Đó chính là năm Nguyễn Tất Thành được nhận vào trường. Ảnh thuộc bộ sưu tập ảnh trường học thuộc địa của Bảo tàng Thuộc địa Lyon trước đây.","nguon_ten":"Musée des Confluences (Lyon) – hồ sơ hiện vật “Personnel enseignant du collège Quôc Hoc, Indochine. 1908”: https://portail.museedesconfluences.fr/notice211839998084551785?lang=en","doc":4},{"loai":"doan","tieu_de":"Ba thứ chữ trong một lớp học","text":"Ở Quốc Học, tiếng Pháp là môn học chính, chữ Hán được dạy song song, bên cạnh chữ quốc ngữ. Học trò làm quen với số học, địa lý và khoa học thường thức theo chương trình của người Pháp, những môn chưa từng có trong lối học khoa cử. Trường tiểu học Pháp – Việt ở Đông Ba, nơi Nguyễn Tất Thành học từ năm 1906, cũng dạy cả ba thứ chữ ấy. Mục tiêu của chính quyền bảo hộ rất rõ ràng: đào tạo thông ngôn, thư ký, giáo học cho bộ máy cai trị. Một tấm bằng của trường Pháp – Việt là tấm vé vào chốn công đường, nơi có đồng lương ổn định và địa vị được xóm giềng nể trọng. Với con trai một viên Thừa biện Bộ Lễ như Nguyễn Tất Thành, con đường ấy gần như đã mở sẵn.\n\nThế nhưng ngôn ngữ nào cũng chở theo tư tưởng. Người học trò đọc được tiếng Pháp thì cũng đọc được những trang viết về tự do, về dân quyền. Cuốn Tiểu sử của Bảo tàng Hồ Chí Minh ghi rằng ở Quốc Học, Người được tiếp xúc với sách báo Pháp, một cánh cửa mà nhà trường thuộc địa không hề định mở.","doc":5},{"loai":"anh","src":"textures/bang_w/G02_4_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lớp học Trường Quốc Học Huế đầu thế kỷ XX”, nhìn từ xa."},{"loai":"doan","tieu_de":"Những người thầy yêu nước","text":"Trong những lớp học ấy có những người thầy để lại dấu ấn. Cuốn Tiểu sử của Bảo tàng Hồ Chí Minh nhắc tên hai thầy giáo yêu nước là thầy Hoàng Thông và thầy Lê Văn Miến. Thầy Miến quê Nghi Lộc, Nghệ An, sinh năm 1874. Thời trẻ, ông từng sang Pháp, học vẽ bốn năm trong xưởng của danh họa Jean-Léon Gérôme ở Paris. Trở về nước, ông làm đốc giáo trường Pháp – Việt ở Vinh, rồi từ năm 1907 dạy tiếng Pháp và môn vẽ ở Quốc Học.\n\nTheo cuốn tiểu sử Hồ Chí Minh của nhà sử học Mỹ William J. Duiker, thầy Miến là một trong những người thầy mà Nguyễn Tất Thành quý mến. Thầy hay nói với học trò rằng người Pháp ở chính quốc khác xa những viên chức thực dân ở Đông Dương. Cậu học trò say mê những câu chuyện về Paris, với những thư viện và bảo tàng. Một số nhà nghiên cứu ở Huế còn ghi lại rằng người học trò từng hỏi thầy làm thế nào để sang Pháp, xem người Pháp sống ra sao. Chỉ ít năm sau, câu hỏi ấy đã thành một chuyến đi có thật.","doc":6},{"loai":"ban_co_biet","text":"Thầy Lê Văn Miến, người dạy tiếng Pháp và môn vẽ ở Quốc Học, được coi là họa sĩ Việt Nam đầu tiên vẽ tranh sơn dầu. Bức tranh Bình văn của ông được Bảo tàng Mỹ thuật Việt Nam mua về năm 1972.","nguon_ten":"Thúy Hương, “Lê Văn Miến, người thầy truyền lửa, họa sĩ đầu tiên của Việt Nam”, báo Tuổi Trẻ, 2026","doc":7},{"loai":"anh","src":"textures/bang_w/G02_4_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lớp học Trường Quốc Học Huế đầu thế kỷ XX”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Ba chữ trên tấm biển của nước Pháp","text":"Mối quan tâm của Nguyễn Tất Thành đến nước Pháp có từ trước khi vào Quốc Học. Cuốn Tiểu sử của Bảo tàng Hồ Chí Minh cho biết khoảng năm 1905, khi học lớp dự bị ở Trường tiểu học Pháp – bản xứ tại Vinh, Người lần đầu nghe khẩu hiệu Tự do – Bình đẳng – Bác ái. Nhiều năm sau, năm 1923, khi trò chuyện với nhà thơ Xô-viết Ô-xíp Man-đen-xtam ở Mát-xcơ-va, Người nhắc lại kỷ niệm ấy. Giữa lời hứa đẹp đẽ trong ba chữ kia và thực tế sưu cao thuế nặng ở Trung Kỳ là một khoảng cách mà người học trò ngày càng thấy rõ. Mùa xuân năm 1908, trước khi được nhận vào Quốc Học, anh đã đứng giữa đoàn nông dân biểu tình chống sưu thuế ở Huế và làm phiên dịch cho bà con (xem chuyên đề Người phiên dịch cho đoàn nông dân). Như vậy, vốn tiếng Pháp của người học trò lần đầu được dùng không phải để phục vụ công đường, mà để nói thay những người nông dân.","doc":8},{"loai":"trich","text":"Khi tôi độ mười ba tuổi, lần đầu tiên tôi được nghe ba chữ Pháp: Tự do, Bình đẳng, Bác ái. Đối với chúng tôi, người da trắng nào cũng là người Pháp. Người Pháp đã nói thế. Và từ thuở ấy, tôi rất muốn làm quen với nền văn minh Pháp, muốn tìm xem những gì ẩn giấu đằng sau những chữ ấy.","nguoi":"Nguyễn Ái Quốc","nguon_ten":"Trả lời nhà thơ Ô-xíp Man-đen-xtam, tạp chí Ogoniok (Liên Xô), năm 1923; in trong Hồ Chí Minh Toàn tập, tập 1, NXB Chính trị quốc gia","doc":9},{"loai":"doan","tieu_de":"Lớp học dưới những mái tranh","text":"Lớp học của Nguyễn Tất Thành không giống hình ảnh ngôi trường đỏ son ngày nay. Theo các tài liệu của tỉnh Thừa Thiên Huế, những năm ấy trường gồm các dãy nhà lợp tranh, vốn là trại lính thủy của triều đình được cải tạo lại, cùng chiếc cổng xây hai tầng. Những dãy nhà lầu bằng gạch mà du khách quen thuộc hôm nay chỉ được xây từ năm 1915 (xem chuyên đề Trường Quốc Học Huế bên bờ sông Hương). Nghĩa là khi tấm ảnh lớp học được công bố năm 1913, những tòa nhà ấy vẫn chưa xuất hiện.\n\nMang tiếng là ngôi trường danh giá bậc nhất xứ Trung Kỳ, nhưng điều kiện học tập thời ấy còn đơn sơ. Chính dưới những mái tranh đó, người học trò mười tám tuổi học tiếng Pháp, đọc sách báo Pháp và nghe thầy kể chuyện Paris. Thứ mà người học trò mang theo khi rời trường không phải ký ức về một tòa nhà đẹp, mà là những câu hỏi đã dần thành hình về thân phận người dân mất nước.","doc":10},{"loai":"anh","src":"textures/bang_w/G02_4_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lớp học Trường Quốc Học Huế đầu thế kỷ XX”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Rời lớp học, mang theo một câu hỏi","text":"Người học ở Quốc Học chưa trọn một năm. Khoảng tháng 6/1909, khi ông Nguyễn Sinh Sắc được bổ làm Tri huyện Bình Khê, Nguyễn Tất Thành rời trường theo cha vào Bình Định. Một số tài liệu in trước đây ghi Người vào Quốc Học từ mùa thu năm 1907 và phải rời trường ngay sau cuộc biểu tình năm 1908. Các công bố gần đây của Bảo tàng Hồ Chí Minh và ngành di sản văn hóa, dựa trên tư liệu lưu trữ, xác định Người học ở trường trong niên khóa 1908 – 1909. Dù theo cách ghi nào, quãng thời gian ấy đều ngắn ngủi, và Người không nhận tấm bằng nào của Quốc Học.\n\nNhưng vốn tiếng Pháp, thói quen đọc sách báo và hình ảnh nước Pháp trong lời kể của thầy giáo đã thành hành trang. Ngày 5/6/1911, người học trò năm xưa rời Bến Nhà Rồng trên tàu Amiral Latouche-Tréville, đi tìm câu trả lời ở chính nước Pháp. Câu hỏi nảy sinh trong một lớp học thuộc địa đã đưa người thanh niên ra với cả thế giới.","doc":11},{"loai":"anh","src":"textures/ht/ht_anh_college_quoc_hoc_a_hue_cours_de_gymnastique.jpg","chu_thich":"Giờ thể dục ở Trường Quốc Học Huế, ảnh cùng loạt với ảnh lớp học. Ảnh không rõ người chụp, công bố ngày 3/6/1913, phạm vi công cộng.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, Trường Quốc Học vẫn là một ngôi trường đang dạy học ở số 12 đường Lê Lợi, thành phố Huế. Trường là một điểm của Di tích lưu niệm Chủ tịch Hồ Chí Minh tại Thừa Thiên Huế, được xếp hạng di tích quốc gia đặc biệt. Ảnh chụp học trò Quốc Học đầu thế kỷ XX còn nằm rải rác trong nhiều bộ sưu tập, kể cả ở Pháp; hai tấm ảnh công bố năm 1913 nay thuộc phạm vi công cộng, ai cũng có thể xem.\n\nTrong không gian 3D của bảo tàng, góc lớp học với những dãy bàn và tấm bảng đen là hình ảnh minh họa, được dựng để khách tham quan hình dung một giờ học của trường Pháp – Việt, không phải hiện vật gốc. Đứng trước bảng này, người xem có thể thử đặt mình vào chỗ ngồi của người học trò Nguyễn Sinh Côn năm ấy. Trước mặt là thầy giáo giảng bài bằng tiếng Pháp. Bên kia sông là kinh thành đang mất dần thực quyền. Còn trong lòng người học trò là câu hỏi vì sao dân mình khổ.","doc":12}],"nguon":["Bảo tàng Hồ Chí Minh, Hồ Chí Minh – Tiểu sử, NXB Chính trị quốc gia, Hà Nội, 2008: https://tulieuvankien.dangcongsan.vn/c-mac-angghen-lenin-ho-chi-minh/book/ho-chi-minh/tieu-su-cuoc-doi-va-su-nghiep/ho-chi-minh-tieu-su-bao-tang-ho-chi-minh-nxb-chinh-tri-quoc-gia-ha-noi-nam-2008-20","Hoàng Hằng (Trung tâm Lưu trữ quốc gia I), “Sự thành lập Trường Quốc học Huế qua tài liệu lưu trữ”, Cục Văn thư và Lưu trữ nhà nước, 2016: https://www.archives.org.vn/gioi-thieu-tai-lieu-nghiep-vu/su-thanh-lap-truong-quoc-hoc-hue-qua-tai-lieu-luu-tru.htm","Minh Đăng, “Nguyễn Tất Thành ra đi từ ngôi trường xứ Huế”, báo Tuổi Trẻ, 2018: https://tuoitre.vn/nguyen-tat-thanh-ra-di-tu-ngoi-truong-xu-hue-20180205104555229.htm","Thúy Hương, “Lê Văn Miến, người thầy truyền lửa, họa sĩ đầu tiên của Việt Nam”, báo Tuổi Trẻ, 2026: https://tuoitre.vn/le-van-mien-nguoi-thay-truyen-lua-hoa-si-dau-tien-cua-viet-nam-20260427221531166.htm","William J. Duiker, Ho Chi Minh: A Life, Hyperion, New York, 2000","Hồ Chí Minh Toàn tập, tập 1, NXB Chính trị quốc gia"],"doc":[{"t":"Bên trong lớp học Quốc Học: người học trò Nguyễn Sinh Côn và ngôi trường Pháp – Việt. Một văn thư hành chính đề ngày 7/8/1908 nhắc đến một cái tên ít người biết: Nguyễn Sinh Côn, quê Nghệ An. Người học trò ấy về sau là Chủ tịch Hồ Chí Minh. Tấm ảnh một lớp học Quốc Học công bố năm 1913 mở cửa vào thế giới mà cậu học trò mười tám tuổi từng sống: những giờ tiếng Pháp, những người thầy yêu nước, và một câu hỏi day dứt về nước Pháp thật sự."},{"t":"Một lá thư mang tên Nguyễn Sinh Côn. Ngày 7/8/1908, Hiệu trưởng Trường Quốc Học Huế là ông Chouquet ký văn thư trả lời Khâm sứ Trung Kỳ về một học sinh xin vào trường. Văn thư cho biết nhà trường có thể nhận học sinh Nguyễn Sinh Côn, quê tỉnh Nghệ An, vốn là học trò trường Pháp – Việt. Tài liệu ấy hiện lưu tại kho lưu trữ ở thành phố Aix-en-Provence, miền nam nước Pháp, và đã được các nhà nghiên cứu ở Huế giới thiệu trên báo chí. Cái tên Nguyễn Sinh Côn nghe lạ với nhiều người. Nhưng đó chính là tên dùng trong giấy tờ học đường của người thanh niên mà gia đình và bạn bè gọi là Nguyễn Tất Thành. Theo cuốn Hồ Chí Minh – Tiểu sử do Bảo tàng Hồ Chí Minh biên soạn, tháng 9/1908, người học trò mười tám tuổi chính thức bước vào lớp trung đẳng, tức lớp nhì, của Trường Quốc Học. Tài liệu của tỉnh Thừa Thiên Huế thì ghi anh thi vượt cấp vào lớp đệ nhị niên, niên khóa 1908 – 1909. Dù cách gọi tên lớp có khác nhau, các nguồn đều cho thấy người học trò được nhận vào trường chỉ vài tháng sau những ngày biến động mùa xuân năm 1908 ở kinh đô."},{"t":"Tấm ảnh năm 1913. Tấm ảnh ở bảng này mang tên tiếng Pháp là Collège Quốc Học à Hué – 2e année complémentaire, nghĩa là lớp năm thứ hai bậc bổ túc của Trường Quốc Học ở Huế. Người chụp không rõ tên. Ảnh được công bố ngày 3/6/1913 và nay thuộc phạm vi công cộng. Đó không phải lớp học của Nguyễn Tất Thành, và không ai trong ảnh được xác định là bạn học của Người. Nhưng ảnh ra đời chỉ bốn năm sau khi Người rời trường, nên là một trong những hình ảnh gần nhất còn lại về môi trường học tập của Quốc Học thời ấy. Cùng loạt với tấm ảnh này còn có ảnh một giờ thể dục của học sinh Quốc Học (xem chuyên đề Giờ thể dục ở Trường Quốc Học Huế)."},{"t":"Ngôi trường của con nhà quan. Muốn hiểu lớp học trong ảnh, cần trở lại năm 1896. Theo tài liệu lưu trữ do Trung tâm Lưu trữ quốc gia I giới thiệu, trường được lập theo đạo dụ ngày 17 tháng 9 năm Thành Thái thứ tám, tức ngày 23/10/1896, và nghị định ngày 18/11/1896 của Toàn quyền Đông Dương. Trong giấy tờ của người Pháp, trường thuộc bậc cao đẳng tiểu học, nhưng người Huế quen gọi là trường Quốc Học. Học sinh buổi đầu là con các hoàng thân, thanh niên trong hoàng tộc và con em quan lại, tuổi từ mười ba đến hai mươi, cùng những nho sinh đủ trình độ. Bộ máy giảng dạy gồm một trưởng giáo, bốn đốc giáo các hạng và một đốc giáo lo lớp sơ đẳng. Triều đình chịu toàn bộ chi phí về người, đồ dùng và xây cất. Người đứng đầu trường đầu tiên là ông Ngô Đình Khả. Câu chuyện về chiếc cổng và hai chữ Quốc Học trên biển trường được kể ở một bảng khác (xem chuyên đề Cổng Trường Quốc Học)."},{"t":"Bạn có biết? Tại Bảo tàng Confluences ở thành phố Lyon, nước Pháp, còn lưu một tấm ảnh nhỏ in trên giấy albumin, cỡ 8,5 x 14 cm, nhan đề Personnel enseignant du collège Quôc Hoc, Indochine. 1908, tức đội ngũ giáo viên Trường Quốc Học năm 1908. Đó chính là năm Nguyễn Tất Thành được nhận vào trường. Ảnh thuộc bộ sưu tập ảnh trường học thuộc địa của Bảo tàng Thuộc địa Lyon trước đây."},{"t":"Ba thứ chữ trong một lớp học. Ở Quốc Học, tiếng Pháp là môn học chính, chữ Hán được dạy song song, bên cạnh chữ quốc ngữ. Học trò làm quen với số học, địa lý và khoa học thường thức theo chương trình của người Pháp, những môn chưa từng có trong lối học khoa cử. Trường tiểu học Pháp – Việt ở Đông Ba, nơi Nguyễn Tất Thành học từ năm 1906, cũng dạy cả ba thứ chữ ấy. Mục tiêu của chính quyền bảo hộ rất rõ ràng: đào tạo thông ngôn, thư ký, giáo học cho bộ máy cai trị. Một tấm bằng của trường Pháp – Việt là tấm vé vào chốn công đường, nơi có đồng lương ổn định và địa vị được xóm giềng nể trọng. Với con trai một viên Thừa biện Bộ Lễ như Nguyễn Tất Thành, con đường ấy gần như đã mở sẵn. Thế nhưng ngôn ngữ nào cũng chở theo tư tưởng. Người học trò đọc được tiếng Pháp thì cũng đọc được những trang viết về tự do, về dân quyền. Cuốn Tiểu sử của Bảo tàng Hồ Chí Minh ghi rằng ở Quốc Học, Người được tiếp xúc với sách báo Pháp, một cánh cửa mà nhà trường thuộc địa không hề định mở."},{"t":"Những người thầy yêu nước. Trong những lớp học ấy có những người thầy để lại dấu ấn. Cuốn Tiểu sử của Bảo tàng Hồ Chí Minh nhắc tên hai thầy giáo yêu nước là thầy Hoàng Thông và thầy Lê Văn Miến. Thầy Miến quê Nghi Lộc, Nghệ An, sinh năm 1874. Thời trẻ, ông từng sang Pháp, học vẽ bốn năm trong xưởng của danh họa Jean-Léon Gérôme ở Paris. Trở về nước, ông làm đốc giáo trường Pháp – Việt ở Vinh, rồi từ năm 1907 dạy tiếng Pháp và môn vẽ ở Quốc Học. Theo cuốn tiểu sử Hồ Chí Minh của nhà sử học Mỹ William J. Duiker, thầy Miến là một trong những người thầy mà Nguyễn Tất Thành quý mến. Thầy hay nói với học trò rằng người Pháp ở chính quốc khác xa những viên chức thực dân ở Đông Dương. Cậu học trò say mê những câu chuyện về Paris, với những thư viện và bảo tàng. Một số nhà nghiên cứu ở Huế còn ghi lại rằng người học trò từng hỏi thầy làm thế nào để sang Pháp, xem người Pháp sống ra sao. Chỉ ít năm sau, câu hỏi ấy đã thành một chuyến đi có thật."},{"t":"Bạn có biết? Thầy Lê Văn Miến, người dạy tiếng Pháp và môn vẽ ở Quốc Học, được coi là họa sĩ Việt Nam đầu tiên vẽ tranh sơn dầu. Bức tranh Bình văn của ông được Bảo tàng Mỹ thuật Việt Nam mua về năm 1972."},{"t":"Ba chữ trên tấm biển của nước Pháp. Mối quan tâm của Nguyễn Tất Thành đến nước Pháp có từ trước khi vào Quốc Học. Cuốn Tiểu sử của Bảo tàng Hồ Chí Minh cho biết khoảng năm 1905, khi học lớp dự bị ở Trường tiểu học Pháp – bản xứ tại Vinh, Người lần đầu nghe khẩu hiệu Tự do – Bình đẳng – Bác ái. Nhiều năm sau, năm 1923, khi trò chuyện với nhà thơ Xô-viết Ô-xíp Man-đen-xtam ở Mát-xcơ-va, Người nhắc lại kỷ niệm ấy. Giữa lời hứa đẹp đẽ trong ba chữ kia và thực tế sưu cao thuế nặng ở Trung Kỳ là một khoảng cách mà người học trò ngày càng thấy rõ. Mùa xuân năm 1908, trước khi được nhận vào Quốc Học, anh đã đứng giữa đoàn nông dân biểu tình chống sưu thuế ở Huế và làm phiên dịch cho bà con (xem chuyên đề Người phiên dịch cho đoàn nông dân). Như vậy, vốn tiếng Pháp của người học trò lần đầu được dùng không phải để phục vụ công đường, mà để nói thay những người nông dân."},{"t":"Khi tôi độ mười ba tuổi, lần đầu tiên tôi được nghe ba chữ Pháp: Tự do, Bình đẳng, Bác ái. Đối với chúng tôi, người da trắng nào cũng là người Pháp. Người Pháp đã nói thế. Và từ thuở ấy, tôi rất muốn làm quen với nền văn minh Pháp, muốn tìm xem những gì ẩn giấu đằng sau những chữ ấy. — Nguyễn Ái Quốc"},{"t":"Lớp học dưới những mái tranh. Lớp học của Nguyễn Tất Thành không giống hình ảnh ngôi trường đỏ son ngày nay. Theo các tài liệu của tỉnh Thừa Thiên Huế, những năm ấy trường gồm các dãy nhà lợp tranh, vốn là trại lính thủy của triều đình được cải tạo lại, cùng chiếc cổng xây hai tầng. Những dãy nhà lầu bằng gạch mà du khách quen thuộc hôm nay chỉ được xây từ năm 1915 (xem chuyên đề Trường Quốc Học Huế bên bờ sông Hương). Nghĩa là khi tấm ảnh lớp học được công bố năm 1913, những tòa nhà ấy vẫn chưa xuất hiện. Mang tiếng là ngôi trường danh giá bậc nhất xứ Trung Kỳ, nhưng điều kiện học tập thời ấy còn đơn sơ. Chính dưới những mái tranh đó, người học trò mười tám tuổi học tiếng Pháp, đọc sách báo Pháp và nghe thầy kể chuyện Paris. Thứ mà người học trò mang theo khi rời trường không phải ký ức về một tòa nhà đẹp, mà là những câu hỏi đã dần thành hình về thân phận người dân mất nước."},{"t":"Rời lớp học, mang theo một câu hỏi. Người học ở Quốc Học chưa trọn một năm. Khoảng tháng 6/1909, khi ông Nguyễn Sinh Sắc được bổ làm Tri huyện Bình Khê, Nguyễn Tất Thành rời trường theo cha vào Bình Định. Một số tài liệu in trước đây ghi Người vào Quốc Học từ mùa thu năm 1907 và phải rời trường ngay sau cuộc biểu tình năm 1908. Các công bố gần đây của Bảo tàng Hồ Chí Minh và ngành di sản văn hóa, dựa trên tư liệu lưu trữ, xác định Người học ở trường trong niên khóa 1908 – 1909. Dù theo cách ghi nào, quãng thời gian ấy đều ngắn ngủi, và Người không nhận tấm bằng nào của Quốc Học. Nhưng vốn tiếng Pháp, thói quen đọc sách báo và hình ảnh nước Pháp trong lời kể của thầy giáo đã thành hành trang. Ngày 5/6/1911, người học trò năm xưa rời Bến Nhà Rồng trên tàu Amiral Latouche-Tréville, đi tìm câu trả lời ở chính nước Pháp. Câu hỏi nảy sinh trong một lớp học thuộc địa đã đưa người thanh niên ra với cả thế giới."},{"t":"Dấu tích hôm nay. Ngày nay, Trường Quốc Học vẫn là một ngôi trường đang dạy học ở số 12 đường Lê Lợi, thành phố Huế. Trường là một điểm của Di tích lưu niệm Chủ tịch Hồ Chí Minh tại Thừa Thiên Huế, được xếp hạng di tích quốc gia đặc biệt. Ảnh chụp học trò Quốc Học đầu thế kỷ XX còn nằm rải rác trong nhiều bộ sưu tập, kể cả ở Pháp; hai tấm ảnh công bố năm 1913 nay thuộc phạm vi công cộng, ai cũng có thể xem. Trong không gian 3D của bảo tàng, góc lớp học với những dãy bàn và tấm bảng đen là hình ảnh minh họa, được dựng để khách tham quan hình dung một giờ học của trường Pháp – Việt, không phải hiện vật gốc. Đứng trước bảng này, người xem có thể thử đặt mình vào chỗ ngồi của người học trò Nguyễn Sinh Côn năm ấy. Trước mặt là thầy giáo giảng bài bằng tiếng Pháp. Bên kia sông là kinh thành đang mất dần thực quyền. Còn trong lòng người học trò là câu hỏi vì sao dân mình khổ."}],"so_chu":1956},{"i":5,"tieu_de_bang":"Giờ thể dục ở Trường Quốc Học Huế","tieu_de":"Giờ thể dục giữa sân Quốc Học: từ một môn học lạ lẫm đến lời kêu gọi “Dân cường thì quốc thịnh”","sapo":"Học trò kinh đô xưa quen ngồi bên án thư, cúi đầu trên trang sách thánh hiền. Vậy mà trong một tấm ảnh công bố năm 1913, học sinh Quốc Học lại đang ra sân trong giờ thể dục. Môn học lạ lẫm ấy mở đầu cho một câu chuyện dài. Gần bốn mươi năm sau khi rời ghế Quốc Học, người học trò năm nào kêu gọi cả nước mỗi sáng tập thể dục.","bia":{"src":"textures/ht/ht_anh_college_quoc_hoc_a_hue_cours_de_gymnastique.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một giờ học không có sách vở","text":"Tấm ảnh ở bảng này mang tên tiếng Pháp Collège Quốc Học à Hué – Cours de gymnastique, nghĩa là giờ thể dục ở Trường Quốc Học Huế. Người chụp không rõ tên. Ảnh được công bố ngày 3/6/1913, cùng ngày với tấm ảnh một lớp học của trường, nên có thể coi là hai ảnh trong cùng một loạt (xem chuyên đề Lớp học Trường Quốc Học Huế đầu thế kỷ XX). Nay ảnh thuộc phạm vi công cộng.\n\nKhác với tấm ảnh chụp trong lớp, ở đây học trò không ngồi sau bàn học mà ra giữa sân trường. Không có sách, không có bảng đen, bài học là những động tác của chính thân thể. Tư liệu không cho biết Nguyễn Tất Thành đã học môn thể dục như thế nào trong quãng thời gian ngắn ngủi ở Quốc Học. Ảnh cũng ra đời vài năm sau khi Người rời trường. Nhưng nó cho thấy nhà trường Pháp – Việt đã khác xa lớp học chữ Hán ở làng quê xứ Nghệ đến mức nào.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_college_quoc_hoc_a_hue_cours_de_gymnastique.jpg","chu_thich":"Giờ thể dục ngoài sân Trường Quốc Học Huế. Ảnh không rõ người chụp, công bố ngày 3/6/1913, phạm vi công cộng.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Thư sinh “trói gà không chặt”","text":"Trong lối học khoa cử truyền thống, việc học gần như chỉ diễn ra bên án thư. Nho sinh thuộc lòng Tứ thư, Ngũ kinh, tập làm văn bài, luyện chữ bằng bút lông, dồn hết sức cho những kỳ thi Hương, thi Hội. Rèn luyện thân thể không có chỗ trong chương trình ấy. Triều Nguyễn có những khoa thi võ riêng cho người theo nghiệp binh, còn kẻ sĩ theo nghiệp văn thì ít khi đụng đến cung kiếm. Dân gian vì thế mới có câu “thư sinh trói gà không chặt” để nói về những người chỉ quen đèn sách.\n\nTuổi thơ của Nguyễn Sinh Cung cũng bắt đầu trong khuôn khổ ấy. Cậu học những chữ Hán đầu tiên với cha ở làng Dương Nỗ ven Huế, rồi về làng Sen học với các thầy đồ, trong đó có thầy Vương Thúc Quý. Bước vào trường Pháp – Việt, người thiếu niên ấy gặp một quan niệm hoàn toàn khác: nhà trường không chỉ dạy chữ, mà còn dạy cả cách rèn luyện thân thể.","doc":2},{"loai":"doan","tieu_de":"Một môn học đến từ nước Pháp","text":"Ở chính nước Pháp, thể dục cũng mới trở thành môn học bắt buộc chưa lâu. Sau thất bại trong chiến tranh Pháp – Phổ những năm 1870 – 1871, giới cầm quyền Pháp lo lắng về sức vóc của lớp thanh niên. Luật ngày 27/1/1880 buộc các trường công lập dành cho nam sinh phải dạy thể dục. Từ chính quốc, môn học ấy theo chân nhà trường Pháp sang các thuộc địa, trong đó có Đông Dương.\n\nChữ “thể dục” là từ Hán Việt: “thể” là thân thể, “dục” là nuôi dạy. Với người Huế đầu thế kỷ XX, cảnh những cậu học trò con nhà quan ra giữa sân tập luyện theo hiệu lệnh của thầy là điều lạ mắt. Những năm ấy, hai nền giáo dục cùng tồn tại ở kinh đô. Bên này, sĩ tử vẫn dùi mài kinh sử chờ khoa thi. Bên kia, trường Pháp – Việt dạy tiếng Pháp, số học, địa lý và thể dục. Phải đến khoa thi Hội năm 1919, lối học khoa cử mới chính thức khép lại.","doc":3},{"loai":"ban_co_biet","text":"Ở Pháp, Luật ngày 27/1/1880 quy định các trường công lập dành cho nam sinh phải dạy thể dục. Hơn ba mươi năm sau, tấm ảnh công bố năm 1913 cho thấy môn học ấy đã có mặt ở ngôi trường Pháp – Việt bên bờ sông Hương.","nguon_ten":"Luật ngày 27/1/1880 của Cộng hòa Pháp về việc dạy thể dục bắt buộc trong các trường công lập nam sinh; ảnh Collège Quốc Học à Hué – Cours de gymnastique (1913)","doc":4},{"loai":"doan","tieu_de":"Sức vóc cho một hành trình dài","text":"Không có tư liệu nào ghi lại điểm môn thể dục của Nguyễn Tất Thành. Nhưng những năm sau đó cho thấy người thanh niên ấy cần đến sức vóc biết bao. Ngày 5/6/1911, Người rời Bến Nhà Rồng trên tàu Amiral Latouche-Tréville, làm phụ bếp với cái tên Văn Ba. Theo sách của Trần Dân Tiên, anh Ba làm việc từ bốn giờ sáng đến tối: quét dọn, rửa nồi, đốt lò, khuân than, xuống hầm tàu lấy thực phẩm. Con tàu chòng chành giữa biển khơi, công việc nặng nhọc kéo dài suốt hành trình.\n\nNhững năm tiếp theo ở nước ngoài, Người kiếm sống bằng đủ nghề lao động chân tay. Cũng theo Trần Dân Tiên, ở Luân Đôn, Người từng cào tuyết cho một trường học, đốt lò, rồi làm phụ bếp trong khách sạn. Một thân thể dẻo dai là điều kiện đầu tiên để người thanh niên xứ Nghệ trụ lại nơi đất khách, vừa làm thuê vừa học hỏi, suốt ba mươi năm đi tìm đường cứu nước.","doc":5},{"loai":"anh","src":"textures/bang_w/G02_5_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Giờ thể dục ở Trường Quốc Học Huế”, nhìn từ xa."},{"loai":"doan","tieu_de":"Qua gần ba mươi nhà lao","text":"Thử thách thể chất khắc nghiệt nhất đến vào những năm 1942 – 1943. Tháng 8/1942, trên đường sang Trung Quốc để liên lạc với các lực lượng cách mạng và Đồng minh, Hồ Chí Minh bị chính quyền địa phương bắt giữ. Hơn một năm sau đó, Người bị giải qua khoảng ba mươi nhà lao của mười ba huyện thuộc tỉnh Quảng Tây. Chân bị xiềng, bụng đói, nhiều chặng phải đi bộ dưới mưa nắng. Tập thơ Nhật ký trong tù ghi lại chặng đường ấy, như hai câu quen thuộc trong bài Đi đường: “Đi đường mới biết gian lao, Núi cao rồi lại núi cao trập trùng”.\n\nTháng 9/1943, Người được trả tự do. Sau thời gian dài bị giam cầm, sức khỏe suy kiệt, đôi chân yếu hẳn. Người kiên trì tập đi, rồi tập leo núi. Bài thơ chữ Hán Mới ra tù, tập leo núi viết trong những ngày ấy kể cảnh Người dạo bước trên đỉnh núi, trông về trời Nam mà nhớ bạn cũ. Với Người, giữ gìn sức khỏe chưa bao giờ là chuyện riêng, mà là giữ sức cho việc nước.","doc":6},{"loai":"doan","tieu_de":"Mùa xuân năm 1946","text":"Tháng 3/1946, nước Việt Nam Dân chủ Cộng hòa mới ra đời được hơn nửa năm. Nạn đói năm 1945 vừa cướp đi sinh mạng khoảng hai triệu đồng bào. Giặc đói, giặc dốt và giặc ngoại xâm cùng một lúc đe dọa chính quyền non trẻ. Ngày 6/3/1946, Chính phủ ký Hiệp định sơ bộ với Pháp để tranh thủ thời gian hòa hoãn. Giữa muôn vàn việc lớn ấy, Chủ tịch Hồ Chí Minh vẫn dành sự quan tâm đặc biệt cho sức khỏe của người dân.\n\nNgày 27/3/1946, báo Cứu quốc đăng Lời kêu gọi toàn dân tập thể dục của Người. Văn bản chưa đầy hai trăm chữ, lời lẽ giản dị như một lời trò chuyện, nhưng đặt việc tập thể dục vào đúng giữa những nhiệm vụ lớn của đất nước. Người mở đầu bằng chính những việc hệ trọng nhất lúc bấy giờ: giữ gìn dân chủ, xây dựng nước nhà, gây đời sống mới.","doc":7},{"loai":"trich","text":"Giữ gìn dân chủ, xây dựng nước nhà, gây đời sống mới, việc gì cũng cần có sức khoẻ mới thành công. Mỗi một người dân yếu ớt, tức là cả nước yếu ớt, mỗi một người dân mạnh khoẻ là cả nước mạnh khoẻ.","nguoi":"Chủ tịch Hồ Chí Minh","nguon_ten":"Lời kêu gọi toàn dân tập thể dục, báo Cứu quốc, 27/3/1946; Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia","doc":8},{"loai":"doan","tieu_de":"Đọc lại một lời kêu gọi","text":"Điều đáng chú ý đầu tiên là cách Người nối sức khỏe của từng người với sức mạnh của cả nước. Vì thế, luyện tập thể dục, bồi bổ sức khỏe được Người gọi là bổn phận của mỗi một người yêu nước. Điều thứ hai, đó là việc ai cũng làm được: không tốn kém, không khó khăn, gái trai, già trẻ đều tập được. Người chỉ cách rất cụ thể: mỗi ngày lúc ngủ dậy, tập một ít thể dục; ngày nào cũng tập thì khí huyết lưu thông, tinh thần đầy đủ.\n\nRồi Người đúc kết bằng một câu ngắn gọn: “Dân cường thì quốc thịnh”, dân mạnh thì nước thịnh. Câu cuối cùng mang giọng một lời tâm sự: “Tự tôi, ngày nào tôi cũng tập”. Vị Chủ tịch nước không chỉ khuyên đồng bào, mà nhận mình là người tập luyện trước tiên. Môn học từng chỉ dành cho số ít học trò trường Pháp – Việt, nay trở thành lời kêu gọi gửi tới cả một dân tộc vừa giành được độc lập.","doc":9},{"loai":"ban_co_biet","text":"Gần hai tháng trước Lời kêu gọi toàn dân tập thể dục, ngày 30/1/1946, Chủ tịch Hồ Chí Minh đã ký sắc lệnh thành lập Nha Thể dục Trung ương, cơ quan đầu tiên của Nhà nước chuyên lo việc thể dục cho toàn dân.","nguon_ten":"Cục Văn thư và Lưu trữ nhà nước, “Những Sắc lệnh đầu tiên của ngành Thể dục thể thao Việt Nam”","doc":10},{"loai":"anh","src":"textures/bang_w/G02_5_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Giờ thể dục ở Trường Quốc Học Huế”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Tiếng vọng của ngày 27 tháng 3","text":"Ngày ra đời Lời kêu gọi, 27/3/1946, được lấy làm ngày truyền thống của ngành thể dục thể thao Việt Nam. Ngày nay, 27/3 hằng năm cũng là Ngày Thể thao Việt Nam. Vào dịp này, nhiều nơi tổ chức ngày chạy vì sức khỏe, hội thao, những buổi đồng diễn thể dục. Cuộc vận động Toàn dân rèn luyện thân thể theo gương Bác Hồ vĩ đại đưa tinh thần của lời kêu gọi năm xưa vào từng khu dân cư, trường học, đơn vị.\n\nTrong nhà trường ngày nay, thể dục là môn học quen thuộc với mọi học sinh, từ bậc tiểu học đến trung học. Khó ai còn thấy lạ khi học trò ra sân tập luyện. Nhưng nhìn lại tấm ảnh năm 1913, người xem hiểu rằng cảnh ấy từng là điều mới mẻ. Và từ những ngôi trường kiểu mới như Quốc Học, thanh niên đầu thế kỷ XX bắt đầu làm quen với ý niệm rằng một dân tộc muốn mạnh thì từng con người phải mạnh.","doc":11},{"loai":"ban_co_biet","text":"Câu “Dân cường thì quốc thịnh” trong lời kêu gọi năm 1946 về sau trở thành phương châm quen thuộc của ngành thể dục thể thao, được nhắc lại trong mỗi dịp kỷ niệm ngày truyền thống 27/3.","nguon_ten":"Bộ Văn hóa, Thể thao và Du lịch, “77 năm ngành Thể dục thể thao Việt Nam: Vì mục tiêu dân cường thì quốc thịnh”, 28/3/2023","doc":12},{"loai":"anh","src":"textures/bang_w/G02_5_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Giờ thể dục ở Trường Quốc Học Huế”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Hai tấm ảnh Quốc Học công bố năm 1913 nay thuộc phạm vi công cộng, được giới thiệu trên kho ảnh Wikimedia Commons, ai cũng có thể xem. Trường Quốc Học ở số 12 đường Lê Lợi, thành phố Huế, vẫn là một ngôi trường đang dạy học, sân trường vẫn rộn tiếng học sinh. Các dãy nhà quanh sân đã được xây lại bằng gạch từ năm 1915, nên khung cảnh hôm nay khác xa cảnh trong ảnh.\n\nTrong không gian 3D của gian trưng bày, sân trường giữa những dãy lớp mái tranh là hình ảnh phục dựng minh họa, giúp khách tham quan hình dung ngôi trường thời Nguyễn Tất Thành theo học. Đứng trước bảng này, người xem có thể nối hai hình ảnh cách nhau hơn ba mươi năm. Một bên là những cậu học trò tập thể dục giữa sân một trường thuộc địa. Bên kia là lời kêu gọi năm 1946 của vị Chủ tịch nước mong mỗi người dân Việt Nam đều khỏe mạnh.","doc":13}],"nguon":["Hồ Chí Minh, “Lời kêu gọi toàn dân tập thể dục”, báo Cứu quốc, 27/3/1946; Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia","Trần Dân Tiên, Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch, NXB Chính trị quốc gia","Hồ Chí Minh, Nhật ký trong tù (bản dịch thơ), NXB Văn học","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Bộ Văn hóa, Thể thao và Du lịch, “77 năm ngành Thể dục thể thao Việt Nam: Vì mục tiêu dân cường thì quốc thịnh”, 28/3/2023","Ảnh Collège Quốc Học à Hué – Cours de gymnastique, không rõ người chụp, công bố ngày 3/6/1913, phạm vi công cộng (Wikimedia Commons)"],"doc":[{"t":"Giờ thể dục giữa sân Quốc Học: từ một môn học lạ lẫm đến lời kêu gọi “Dân cường thì quốc thịnh”. Học trò kinh đô xưa quen ngồi bên án thư, cúi đầu trên trang sách thánh hiền. Vậy mà trong một tấm ảnh công bố năm 1913, học sinh Quốc Học lại đang ra sân trong giờ thể dục. Môn học lạ lẫm ấy mở đầu cho một câu chuyện dài. Gần bốn mươi năm sau khi rời ghế Quốc Học, người học trò năm nào kêu gọi cả nước mỗi sáng tập thể dục."},{"t":"Một giờ học không có sách vở. Tấm ảnh ở bảng này mang tên tiếng Pháp Collège Quốc Học à Hué – Cours de gymnastique, nghĩa là giờ thể dục ở Trường Quốc Học Huế. Người chụp không rõ tên. Ảnh được công bố ngày 3/6/1913, cùng ngày với tấm ảnh một lớp học của trường, nên có thể coi là hai ảnh trong cùng một loạt (xem chuyên đề Lớp học Trường Quốc Học Huế đầu thế kỷ XX). Nay ảnh thuộc phạm vi công cộng. Khác với tấm ảnh chụp trong lớp, ở đây học trò không ngồi sau bàn học mà ra giữa sân trường. Không có sách, không có bảng đen, bài học là những động tác của chính thân thể. Tư liệu không cho biết Nguyễn Tất Thành đã học môn thể dục như thế nào trong quãng thời gian ngắn ngủi ở Quốc Học. Ảnh cũng ra đời vài năm sau khi Người rời trường. Nhưng nó cho thấy nhà trường Pháp – Việt đã khác xa lớp học chữ Hán ở làng quê xứ Nghệ đến mức nào."},{"t":"Thư sinh “trói gà không chặt”. Trong lối học khoa cử truyền thống, việc học gần như chỉ diễn ra bên án thư. Nho sinh thuộc lòng Tứ thư, Ngũ kinh, tập làm văn bài, luyện chữ bằng bút lông, dồn hết sức cho những kỳ thi Hương, thi Hội. Rèn luyện thân thể không có chỗ trong chương trình ấy. Triều Nguyễn có những khoa thi võ riêng cho người theo nghiệp binh, còn kẻ sĩ theo nghiệp văn thì ít khi đụng đến cung kiếm. Dân gian vì thế mới có câu “thư sinh trói gà không chặt” để nói về những người chỉ quen đèn sách. Tuổi thơ của Nguyễn Sinh Cung cũng bắt đầu trong khuôn khổ ấy. Cậu học những chữ Hán đầu tiên với cha ở làng Dương Nỗ ven Huế, rồi về làng Sen học với các thầy đồ, trong đó có thầy Vương Thúc Quý. Bước vào trường Pháp – Việt, người thiếu niên ấy gặp một quan niệm hoàn toàn khác: nhà trường không chỉ dạy chữ, mà còn dạy cả cách rèn luyện thân thể."},{"t":"Một môn học đến từ nước Pháp. Ở chính nước Pháp, thể dục cũng mới trở thành môn học bắt buộc chưa lâu. Sau thất bại trong chiến tranh Pháp – Phổ những năm 1870 – 1871, giới cầm quyền Pháp lo lắng về sức vóc của lớp thanh niên. Luật ngày 27/1/1880 buộc các trường công lập dành cho nam sinh phải dạy thể dục. Từ chính quốc, môn học ấy theo chân nhà trường Pháp sang các thuộc địa, trong đó có Đông Dương. Chữ “thể dục” là từ Hán Việt: “thể” là thân thể, “dục” là nuôi dạy. Với người Huế đầu thế kỷ XX, cảnh những cậu học trò con nhà quan ra giữa sân tập luyện theo hiệu lệnh của thầy là điều lạ mắt. Những năm ấy, hai nền giáo dục cùng tồn tại ở kinh đô. Bên này, sĩ tử vẫn dùi mài kinh sử chờ khoa thi. Bên kia, trường Pháp – Việt dạy tiếng Pháp, số học, địa lý và thể dục. Phải đến khoa thi Hội năm 1919, lối học khoa cử mới chính thức khép lại."},{"t":"Bạn có biết? Ở Pháp, Luật ngày 27/1/1880 quy định các trường công lập dành cho nam sinh phải dạy thể dục. Hơn ba mươi năm sau, tấm ảnh công bố năm 1913 cho thấy môn học ấy đã có mặt ở ngôi trường Pháp – Việt bên bờ sông Hương."},{"t":"Sức vóc cho một hành trình dài. Không có tư liệu nào ghi lại điểm môn thể dục của Nguyễn Tất Thành. Nhưng những năm sau đó cho thấy người thanh niên ấy cần đến sức vóc biết bao. Ngày 5/6/1911, Người rời Bến Nhà Rồng trên tàu Amiral Latouche-Tréville, làm phụ bếp với cái tên Văn Ba. Theo sách của Trần Dân Tiên, anh Ba làm việc từ bốn giờ sáng đến tối: quét dọn, rửa nồi, đốt lò, khuân than, xuống hầm tàu lấy thực phẩm. Con tàu chòng chành giữa biển khơi, công việc nặng nhọc kéo dài suốt hành trình. Những năm tiếp theo ở nước ngoài, Người kiếm sống bằng đủ nghề lao động chân tay. Cũng theo Trần Dân Tiên, ở Luân Đôn, Người từng cào tuyết cho một trường học, đốt lò, rồi làm phụ bếp trong khách sạn. Một thân thể dẻo dai là điều kiện đầu tiên để người thanh niên xứ Nghệ trụ lại nơi đất khách, vừa làm thuê vừa học hỏi, suốt ba mươi năm đi tìm đường cứu nước."},{"t":"Qua gần ba mươi nhà lao. Thử thách thể chất khắc nghiệt nhất đến vào những năm 1942 – 1943. Tháng 8/1942, trên đường sang Trung Quốc để liên lạc với các lực lượng cách mạng và Đồng minh, Hồ Chí Minh bị chính quyền địa phương bắt giữ. Hơn một năm sau đó, Người bị giải qua khoảng ba mươi nhà lao của mười ba huyện thuộc tỉnh Quảng Tây. Chân bị xiềng, bụng đói, nhiều chặng phải đi bộ dưới mưa nắng. Tập thơ Nhật ký trong tù ghi lại chặng đường ấy, như hai câu quen thuộc trong bài Đi đường: “Đi đường mới biết gian lao, Núi cao rồi lại núi cao trập trùng”. Tháng 9/1943, Người được trả tự do. Sau thời gian dài bị giam cầm, sức khỏe suy kiệt, đôi chân yếu hẳn. Người kiên trì tập đi, rồi tập leo núi. Bài thơ chữ Hán Mới ra tù, tập leo núi viết trong những ngày ấy kể cảnh Người dạo bước trên đỉnh núi, trông về trời Nam mà nhớ bạn cũ. Với Người, giữ gìn sức khỏe chưa bao giờ là chuyện riêng, mà là giữ sức cho việc nước."},{"t":"Mùa xuân năm 1946. Tháng 3/1946, nước Việt Nam Dân chủ Cộng hòa mới ra đời được hơn nửa năm. Nạn đói năm 1945 vừa cướp đi sinh mạng khoảng hai triệu đồng bào. Giặc đói, giặc dốt và giặc ngoại xâm cùng một lúc đe dọa chính quyền non trẻ. Ngày 6/3/1946, Chính phủ ký Hiệp định sơ bộ với Pháp để tranh thủ thời gian hòa hoãn. Giữa muôn vàn việc lớn ấy, Chủ tịch Hồ Chí Minh vẫn dành sự quan tâm đặc biệt cho sức khỏe của người dân. Ngày 27/3/1946, báo Cứu quốc đăng Lời kêu gọi toàn dân tập thể dục của Người. Văn bản chưa đầy hai trăm chữ, lời lẽ giản dị như một lời trò chuyện, nhưng đặt việc tập thể dục vào đúng giữa những nhiệm vụ lớn của đất nước. Người mở đầu bằng chính những việc hệ trọng nhất lúc bấy giờ: giữ gìn dân chủ, xây dựng nước nhà, gây đời sống mới."},{"t":"Giữ gìn dân chủ, xây dựng nước nhà, gây đời sống mới, việc gì cũng cần có sức khoẻ mới thành công. Mỗi một người dân yếu ớt, tức là cả nước yếu ớt, mỗi một người dân mạnh khoẻ là cả nước mạnh khoẻ. — Chủ tịch Hồ Chí Minh"},{"t":"Đọc lại một lời kêu gọi. Điều đáng chú ý đầu tiên là cách Người nối sức khỏe của từng người với sức mạnh của cả nước. Vì thế, luyện tập thể dục, bồi bổ sức khỏe được Người gọi là bổn phận của mỗi một người yêu nước. Điều thứ hai, đó là việc ai cũng làm được: không tốn kém, không khó khăn, gái trai, già trẻ đều tập được. Người chỉ cách rất cụ thể: mỗi ngày lúc ngủ dậy, tập một ít thể dục; ngày nào cũng tập thì khí huyết lưu thông, tinh thần đầy đủ. Rồi Người đúc kết bằng một câu ngắn gọn: “Dân cường thì quốc thịnh”, dân mạnh thì nước thịnh. Câu cuối cùng mang giọng một lời tâm sự: “Tự tôi, ngày nào tôi cũng tập”. Vị Chủ tịch nước không chỉ khuyên đồng bào, mà nhận mình là người tập luyện trước tiên. Môn học từng chỉ dành cho số ít học trò trường Pháp – Việt, nay trở thành lời kêu gọi gửi tới cả một dân tộc vừa giành được độc lập."},{"t":"Bạn có biết? Gần hai tháng trước Lời kêu gọi toàn dân tập thể dục, ngày 30/1/1946, Chủ tịch Hồ Chí Minh đã ký sắc lệnh thành lập Nha Thể dục Trung ương, cơ quan đầu tiên của Nhà nước chuyên lo việc thể dục cho toàn dân."},{"t":"Tiếng vọng của ngày 27 tháng 3. Ngày ra đời Lời kêu gọi, 27/3/1946, được lấy làm ngày truyền thống của ngành thể dục thể thao Việt Nam. Ngày nay, 27/3 hằng năm cũng là Ngày Thể thao Việt Nam. Vào dịp này, nhiều nơi tổ chức ngày chạy vì sức khỏe, hội thao, những buổi đồng diễn thể dục. Cuộc vận động Toàn dân rèn luyện thân thể theo gương Bác Hồ vĩ đại đưa tinh thần của lời kêu gọi năm xưa vào từng khu dân cư, trường học, đơn vị. Trong nhà trường ngày nay, thể dục là môn học quen thuộc với mọi học sinh, từ bậc tiểu học đến trung học. Khó ai còn thấy lạ khi học trò ra sân tập luyện. Nhưng nhìn lại tấm ảnh năm 1913, người xem hiểu rằng cảnh ấy từng là điều mới mẻ. Và từ những ngôi trường kiểu mới như Quốc Học, thanh niên đầu thế kỷ XX bắt đầu làm quen với ý niệm rằng một dân tộc muốn mạnh thì từng con người phải mạnh."},{"t":"Bạn có biết? Câu “Dân cường thì quốc thịnh” trong lời kêu gọi năm 1946 về sau trở thành phương châm quen thuộc của ngành thể dục thể thao, được nhắc lại trong mỗi dịp kỷ niệm ngày truyền thống 27/3."},{"t":"Dấu tích hôm nay. Hai tấm ảnh Quốc Học công bố năm 1913 nay thuộc phạm vi công cộng, được giới thiệu trên kho ảnh Wikimedia Commons, ai cũng có thể xem. Trường Quốc Học ở số 12 đường Lê Lợi, thành phố Huế, vẫn là một ngôi trường đang dạy học, sân trường vẫn rộn tiếng học sinh. Các dãy nhà quanh sân đã được xây lại bằng gạch từ năm 1915, nên khung cảnh hôm nay khác xa cảnh trong ảnh. Trong không gian 3D của gian trưng bày, sân trường giữa những dãy lớp mái tranh là hình ảnh phục dựng minh họa, giúp khách tham quan hình dung ngôi trường thời Nguyễn Tất Thành theo học. Đứng trước bảng này, người xem có thể nối hai hình ảnh cách nhau hơn ba mươi năm. Một bên là những cậu học trò tập thể dục giữa sân một trường thuộc địa. Bên kia là lời kêu gọi năm 1946 của vị Chủ tịch nước mong mỗi người dân Việt Nam đều khỏe mạnh."}],"so_chu":1843},{"i":6,"tieu_de_bang":"Trường Quốc Học Huế bên bờ sông Hương","tieu_de":"Sắc đỏ bên dòng Hương: hơn một thế kỷ của ngôi trường nơi những người làm nên lịch sử từng ngồi học","sapo":"Một buổi chiều tháng Giêng năm 2008, tác giả Lưu Ly bấm máy trước ngôi trường sắc đỏ bên bờ nam sông Hương. Tấm ảnh bình dị ấy ghi lại một địa chỉ hiếm có. Ở đây từng có mặt người học trò Nguyễn Tất Thành, rồi hai vị Tổng Bí thư, một Thủ tướng, một Đại tướng. Đằng sau khung hình là hơn một thế kỷ sông nước, lớp học và những cuộc ra đi.","bia":{"src":"textures/ht/ht_anh_quoc_hoc_hue.jpg","credit":"Ảnh: Lưu Ly · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Ba giờ chiều, tháng Giêng năm 2008","text":"Theo thông tin đi kèm tệp ảnh, tấm ảnh ở bảng này được chụp lúc 15 giờ ngày 21/1/2008. Tác giả ký tên Lưu Ly, một người đóng góp cho Wikipedia tiếng Việt, và đã để ảnh thuộc phạm vi công cộng. Khung hình cho thấy Trường Quốc Học với sắc đỏ quen thuộc, nằm bên bờ sông Hương.\n\nMột trăm năm trước thời điểm bấm máy, năm 1908, người học trò Nguyễn Tất Thành được nhận vào ngôi trường này. Nhưng người xem cần nhớ rằng những gì hiện ra trong ảnh không phải khung cảnh Người từng thấy. Năm ấy, trường chỉ có hai dãy nhà lợp tranh, tường gạch, cột gỗ, cùng chiếc cổng xây hai tầng. Các dãy nhà gạch hôm nay là thành quả của đợt tái thiết bắt đầu từ năm 1915 và những lần tu bổ về sau (xem chuyên đề Cổng Trường Quốc Học). Cái còn nguyên qua một thế kỷ là vị trí ngôi trường, dòng sông trước mặt và Kinh thành bên kia sông.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_quoc_hoc_hue.jpg","chu_thich":"Trường Quốc Học Huế bên bờ sông Hương. Ảnh: Lưu Ly, chụp ngày 21/1/2008, phạm vi công cộng.","credit":"Ảnh: Lưu Ly · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Dòng sông trước cổng trường","text":"Sông Hương bắt nguồn từ dãy Trường Sơn. Hai nhánh Tả Trạch và Hữu Trạch gặp nhau ở ngã ba Tuần, rồi dòng sông chảy chậm qua vùng lăng tẩm của các vua Nguyễn, qua chân chùa Thiên Mụ dựng từ năm 1601. Đến giữa thành phố, sông chia Huế thành hai nửa: bờ bắc có Kinh thành, bờ nam là khu phố mới hình thành từ cuối thế kỷ XIX. Từ đó sông xuôi về phía đông, đổ vào phá Tam Giang rồi ra biển ở cửa Thuận An.\n\nTrường Quốc Học nằm ở bờ nam, mặt tiền trông ra con đường chạy dọc bờ sông, nay là đường Lê Lợi. Từ trước cổng trường nhìn ra là mặt nước rộng, những con đò ngang qua lại, và xa hơn là tường thành, Kỳ Đài bên bờ bắc. Ít có ngôi trường nào ở Việt Nam có một khung cảnh như thế. Nhiều thế hệ học trò Quốc Học lớn lên cùng dòng sông ấy, và sắc đỏ của ngôi trường bên dòng nước xanh đã trở thành một hình ảnh quen thuộc của Huế.","doc":2},{"loai":"doan","tieu_de":"Hai bờ sông, hai thế giới","text":"Đầu thế kỷ XX, dòng sông không chỉ ngăn cách hai bờ đất. Bờ bắc là không gian của triều đình nhà Nguyễn, với cung điện, Kỳ Đài và những con phố của quan lại, sĩ tử. Bờ nam là nơi người Pháp đặt Tòa Khâm sứ Trung Kỳ, các công sở và những trường học kiểu mới, trong đó có Quốc Học. Quyền lực thật của xứ Trung Kỳ nằm ở bờ nam, dù ngai vàng vẫn ở bờ bắc (xem chuyên đề Huế – Kinh thành và trường Quốc Học).\n\nNhững năm 1906 – 1909, gia đình Nguyễn Tất Thành ở Dãy Trại trên đường Đông Ba, thuộc bờ bắc. Mỗi ngày đến Quốc Học, người học trò phải sang sông, đi từ phía kinh thành cũ sang phía của nhà nước bảo hộ (xem chuyên đề Cầu Trường Tiền và sông Hương). Quãng đường ấy không dài, nhưng nó đặt người thanh niên mười tám tuổi giữa hai thế giới. Một bên là triều đình đã mất thực quyền. Một bên là bộ máy cai trị của người Pháp, với nhà trường đào tạo người phục vụ cho nó.","doc":3},{"loai":"anh","src":"textures/bang_w/G02_6_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Trường Quốc Học Huế bên bờ sông Hương”, nhìn từ xa."},{"loai":"doan","tieu_de":"Hai vị Tổng Bí thư từ một mái trường","text":"Nguyễn Tất Thành rời Quốc Học năm 1909. Hơn một thập niên sau, những dãy lớp bên sông Hương lại đón những người học trò mà về sau tên tuổi gắn với con đường Người đã chọn. Trần Phú, quê Hà Tĩnh, học ở Quốc Học rồi về dạy học ở Vinh, trước khi bước vào con đường hoạt động cách mạng. Tháng 10/1930, tại Hội nghị Ban Chấp hành Trung ương lần thứ nhất, ông được bầu làm Tổng Bí thư đầu tiên của Đảng và là người soạn thảo Luận cương chính trị. Ông hy sinh năm 1931 tại nhà thương Chợ Quán khi mới hai mươi bảy tuổi, để lại lời nhắn nhủ “Hãy giữ vững chí khí chiến đấu”.\n\nHà Huy Tập, cũng quê Hà Tĩnh, là một học trò Quốc Học khác. Ông giữ cương vị Tổng Bí thư trong những năm 1936 – 1938 và hy sinh năm 1941. Như vậy, hai trong số những người đứng đầu Đảng thời kỳ đầu từng ngồi học dưới mái trường mà Nguyễn Tất Thành đã bước qua.","doc":4},{"loai":"doan","tieu_de":"Từ cuộc bãi khóa năm 1927","text":"Võ Nguyên Giáp, sinh năm 1911 ở Quảng Bình, thi đỗ vào Quốc Học năm 1925. Chỉ hai năm sau, người học trò mười sáu tuổi phải rời trường sau một cuộc bãi khóa. Những năm tiếp theo, ông vừa học vừa hoạt động cách mạng ở Huế, rồi ở Hà Nội. Ngày 22/12/1944, theo chỉ thị của lãnh tụ Hồ Chí Minh, ông thành lập Đội Việt Nam Tuyên truyền Giải phóng quân. Mười năm sau, ông là Tổng Tư lệnh chỉ huy chiến dịch Điện Biên Phủ.\n\nPhạm Văn Đồng, quê Quảng Ngãi, cũng từng học ở Quốc Học trước khi ra Hà Nội học tiếp. Năm 1926, ông là một trong những thanh niên dự lớp huấn luyện chính trị do Nguyễn Ái Quốc tổ chức ở Quảng Châu, và về sau đứng đầu Chính phủ hơn ba mươi năm. Học ở những niên khóa khác nhau, họ không cùng ngồi một lớp với Nguyễn Tất Thành. Nhưng cùng một mái trường, cùng dòng sông trước cổng, đã chứng kiến bước khởi đầu của những người sẽ làm nên lịch sử dân tộc.","doc":5},{"loai":"ban_co_biet","text":"Năm 1927, học sinh Võ Nguyên Giáp bị đuổi khỏi Quốc Học vì tham gia bãi khóa – gần hai mươi năm sau khi Nguyễn Tất Thành cũng phải rời ngôi trường này vì đứng về phía nhân dân.","nguon_ten":"Tiểu sử Đại tướng Võ Nguyên Giáp – Cổng Thông tin điện tử Chính phủ","doc":6},{"loai":"doan","tieu_de":"Người ký hiệp định, người làm thơ","text":"Danh sách học trò Quốc Học không chỉ có những nhà chính trị, quân sự. Tạ Quang Bửu, sinh năm 1910 ở Nam Đàn, Nghệ An, cùng huyện với Nguyễn Tất Thành, từng học ở Quốc Học trước khi sang Pháp và Anh học toán, vật lý. Ông trở về tham gia kháng chiến, sau này là Bộ trưởng Bộ Đại học và Trung học chuyên nghiệp, có nhiều đóng góp cho nền khoa học và giáo dục đại học nước nhà.\n\nNhà thơ Xuân Diệu cũng là một học trò của trường trong những năm 1930, khi trường mang tên Trung học Khải Định. Tập Thơ thơ của ông, xuất bản năm 1938, là một đỉnh cao của phong trào Thơ mới. Bên cạnh những tên tuổi ấy là nhiều thế hệ thầy giáo, thầy thuốc, kỹ sư, nhà nghiên cứu đã lớn lên từ những dãy lớp bên sông. Chính quyền bảo hộ lập trường để đào tạo thông ngôn và viên chức, nhưng ngôi trường đã đi xa hơn nhiều so với ý định ban đầu ấy (xem chuyên đề Cổng Trường Quốc Học).","doc":7},{"loai":"ban_co_biet","text":"Ngày 20/7/1954 tại Giơ-ne-vơ, người thay mặt Tổng Tư lệnh Quân đội nhân dân Việt Nam ký Hiệp định đình chỉ chiến sự ở Việt Nam là Thứ trưởng Bộ Quốc phòng Tạ Quang Bửu, một cựu học trò Quốc Học.","nguon_ten":"TTXVN (Vietnam+), “Trường Quốc học Huế – nơi giác ngộ tinh thần yêu nước của Bác Hồ”, 18/5/2020; Hiệp định đình chỉ chiến sự ở Việt Nam, Giơ-ne-vơ, 20/7/1954","doc":8},{"loai":"anh","src":"textures/bang_w/G02_6_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Trường Quốc Học Huế bên bờ sông Hương”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Hơn một thế kỷ trên cùng một mảnh đất","text":"Từ ngày thành lập, 23/10/1896, đến nay, ngôi trường vẫn đứng trên mảnh đất bên bờ nam sông Hương. Những mái tranh buổi đầu đã nhường chỗ cho các dãy nhà gạch sơn đỏ; tên trường cũng nhiều lần thay đổi trước khi trở lại với hai chữ Quốc Học từ năm 1956. Năm 1996, trường kỷ niệm tròn một trăm năm thành lập. Năm 2021, ngôi trường bước sang tuổi một trăm hai mươi lăm.\n\nHiếm có ngôi trường nào mà sân trường, lớp học và cảnh vật xung quanh lại gắn chặt với lịch sử một thành phố như vậy. Ngày nay, dưới tên Trường Trung học phổ thông chuyên Quốc Học, trường là nơi học tập của những học sinh được tuyển chọn qua kỳ thi tuyển. Học trò hôm nay đi trên sân trường mà nhiều thế hệ đàn anh từng đi, nhìn ra cùng một dòng sông. Khoảng cách hơn một thế kỷ như được thu ngắn lại mỗi lần một lớp học trò mới bước qua cánh cổng.","doc":9},{"loai":"doan","tieu_de":"Di tích giữa một ngôi trường đang dạy học","text":"Ngày 26/3/1990, Trường Quốc Học được xếp hạng di tích lịch sử – văn hóa cấp quốc gia. Cũng trong năm ấy, nhân kỷ niệm một trăm năm ngày sinh Chủ tịch Hồ Chí Minh, tượng người học trò Nguyễn Tất Thành được dựng giữa sân trường (xem chuyên đề Tượng học trò Nguyễn Tất Thành ở Trường Quốc Học). Đến năm 2020, địa điểm Trường Quốc Học trở thành một điểm trong Hệ thống di tích lưu niệm Chủ tịch Hồ Chí Minh tại Thừa Thiên Huế, được xếp hạng di tích quốc gia đặc biệt.\n\nĐiều đặc biệt là di tích ấy không phải một công trình đóng cửa để trưng bày. Mỗi sáng, học sinh vẫn đến lớp, tiếng giảng bài vẫn vang lên trong những dãy nhà đỏ. Việc bảo tồn vì thế đi liền với việc dạy học hằng ngày: vừa giữ dáng vẻ những công trình đã hơn trăm tuổi, vừa bảo đảm chỗ học cho những lớp học trò mới. Chính sự sống động ấy làm cho di tích Quốc Học khác với nhiều di tích khác ở Huế.","doc":10},{"loai":"anh","src":"textures/bang_w/G02_6_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Trường Quốc Học Huế bên bờ sông Hương”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Du khách đến Huế có thể tìm tới Trường Quốc Học ở số 12 đường Lê Lợi, ngay bờ nam sông Hương. Đứng bên bờ sông trước cổng trường, nhìn sang bờ bắc là tường thành và Kỳ Đài của Kinh thành, nay thuộc Quần thể di tích Cố đô Huế. Nhìn về phía đông là những nhịp vòm của cầu Trường Tiền. Đó gần như là trọn vẹn khung cảnh của những năm người học trò Nguyễn Tất Thành đến lớp, chỉ khác ở dáng vẻ các công trình.\n\nTrong không gian 3D của gian trưng bày, ngôi trường được dựng lại theo hình dung về những năm đầu thế kỷ XX, với các dãy lớp mái tranh và cổng hai tầng. Đó là hình ảnh phục dựng minh họa, không phải bản sao chính xác của công trình năm 1908. Đặt cạnh tấm ảnh năm 2008, người xem thấy ngôi trường đã đổi thay thế nào qua một trăm năm, và điều gì vẫn còn nguyên: dòng sông, bờ thành bên kia, và vị trí của một ngôi trường đã đi vào lịch sử.","doc":11}],"nguon":["Tường Vi, “Trường Quốc học Huế – nơi giác ngộ tinh thần yêu nước của Bác Hồ”, TTXVN (Vietnam+), 18/5/2020: https://www.vietnamplus.vn/truong-quoc-hoc-hue-noi-giac-ngo-tinh-than-yeu-nuoc-cua-bac-ho-post640707.vnp","Bảo tàng Hồ Chí Minh, Hồ Chí Minh – Tiểu sử, NXB Chính trị quốc gia, 2008","Cổng Thông tin điện tử Chính phủ – Tiểu sử Đại tướng Võ Nguyên Giáp","Trường THPT chuyên Quốc Học – Huế","Hiệp định đình chỉ chiến sự ở Việt Nam, Giơ-ne-vơ, 20/7/1954","Ảnh Trường Quốc Học Huế, Lưu Ly chụp ngày 21/1/2008, phạm vi công cộng (Wikimedia Commons)"],"doc":[{"t":"Sắc đỏ bên dòng Hương: hơn một thế kỷ của ngôi trường nơi những người làm nên lịch sử từng ngồi học. Một buổi chiều tháng Giêng năm 2008, tác giả Lưu Ly bấm máy trước ngôi trường sắc đỏ bên bờ nam sông Hương. Tấm ảnh bình dị ấy ghi lại một địa chỉ hiếm có. Ở đây từng có mặt người học trò Nguyễn Tất Thành, rồi hai vị Tổng Bí thư, một Thủ tướng, một Đại tướng. Đằng sau khung hình là hơn một thế kỷ sông nước, lớp học và những cuộc ra đi."},{"t":"Ba giờ chiều, tháng Giêng năm 2008. Theo thông tin đi kèm tệp ảnh, tấm ảnh ở bảng này được chụp lúc 15 giờ ngày 21/1/2008. Tác giả ký tên Lưu Ly, một người đóng góp cho Wikipedia tiếng Việt, và đã để ảnh thuộc phạm vi công cộng. Khung hình cho thấy Trường Quốc Học với sắc đỏ quen thuộc, nằm bên bờ sông Hương. Một trăm năm trước thời điểm bấm máy, năm 1908, người học trò Nguyễn Tất Thành được nhận vào ngôi trường này. Nhưng người xem cần nhớ rằng những gì hiện ra trong ảnh không phải khung cảnh Người từng thấy. Năm ấy, trường chỉ có hai dãy nhà lợp tranh, tường gạch, cột gỗ, cùng chiếc cổng xây hai tầng. Các dãy nhà gạch hôm nay là thành quả của đợt tái thiết bắt đầu từ năm 1915 và những lần tu bổ về sau (xem chuyên đề Cổng Trường Quốc Học). Cái còn nguyên qua một thế kỷ là vị trí ngôi trường, dòng sông trước mặt và Kinh thành bên kia sông."},{"t":"Dòng sông trước cổng trường. Sông Hương bắt nguồn từ dãy Trường Sơn. Hai nhánh Tả Trạch và Hữu Trạch gặp nhau ở ngã ba Tuần, rồi dòng sông chảy chậm qua vùng lăng tẩm của các vua Nguyễn, qua chân chùa Thiên Mụ dựng từ năm 1601. Đến giữa thành phố, sông chia Huế thành hai nửa: bờ bắc có Kinh thành, bờ nam là khu phố mới hình thành từ cuối thế kỷ XIX. Từ đó sông xuôi về phía đông, đổ vào phá Tam Giang rồi ra biển ở cửa Thuận An. Trường Quốc Học nằm ở bờ nam, mặt tiền trông ra con đường chạy dọc bờ sông, nay là đường Lê Lợi. Từ trước cổng trường nhìn ra là mặt nước rộng, những con đò ngang qua lại, và xa hơn là tường thành, Kỳ Đài bên bờ bắc. Ít có ngôi trường nào ở Việt Nam có một khung cảnh như thế. Nhiều thế hệ học trò Quốc Học lớn lên cùng dòng sông ấy, và sắc đỏ của ngôi trường bên dòng nước xanh đã trở thành một hình ảnh quen thuộc của Huế."},{"t":"Hai bờ sông, hai thế giới. Đầu thế kỷ XX, dòng sông không chỉ ngăn cách hai bờ đất. Bờ bắc là không gian của triều đình nhà Nguyễn, với cung điện, Kỳ Đài và những con phố của quan lại, sĩ tử. Bờ nam là nơi người Pháp đặt Tòa Khâm sứ Trung Kỳ, các công sở và những trường học kiểu mới, trong đó có Quốc Học. Quyền lực thật của xứ Trung Kỳ nằm ở bờ nam, dù ngai vàng vẫn ở bờ bắc (xem chuyên đề Huế – Kinh thành và trường Quốc Học). Những năm 1906 – 1909, gia đình Nguyễn Tất Thành ở Dãy Trại trên đường Đông Ba, thuộc bờ bắc. Mỗi ngày đến Quốc Học, người học trò phải sang sông, đi từ phía kinh thành cũ sang phía của nhà nước bảo hộ (xem chuyên đề Cầu Trường Tiền và sông Hương). Quãng đường ấy không dài, nhưng nó đặt người thanh niên mười tám tuổi giữa hai thế giới. Một bên là triều đình đã mất thực quyền. Một bên là bộ máy cai trị của người Pháp, với nhà trường đào tạo người phục vụ cho nó."},{"t":"Hai vị Tổng Bí thư từ một mái trường. Nguyễn Tất Thành rời Quốc Học năm 1909. Hơn một thập niên sau, những dãy lớp bên sông Hương lại đón những người học trò mà về sau tên tuổi gắn với con đường Người đã chọn. Trần Phú, quê Hà Tĩnh, học ở Quốc Học rồi về dạy học ở Vinh, trước khi bước vào con đường hoạt động cách mạng. Tháng 10/1930, tại Hội nghị Ban Chấp hành Trung ương lần thứ nhất, ông được bầu làm Tổng Bí thư đầu tiên của Đảng và là người soạn thảo Luận cương chính trị. Ông hy sinh năm 1931 tại nhà thương Chợ Quán khi mới hai mươi bảy tuổi, để lại lời nhắn nhủ “Hãy giữ vững chí khí chiến đấu”. Hà Huy Tập, cũng quê Hà Tĩnh, là một học trò Quốc Học khác. Ông giữ cương vị Tổng Bí thư trong những năm 1936 – 1938 và hy sinh năm 1941. Như vậy, hai trong số những người đứng đầu Đảng thời kỳ đầu từng ngồi học dưới mái trường mà Nguyễn Tất Thành đã bước qua."},{"t":"Từ cuộc bãi khóa năm 1927. Võ Nguyên Giáp, sinh năm 1911 ở Quảng Bình, thi đỗ vào Quốc Học năm 1925. Chỉ hai năm sau, người học trò mười sáu tuổi phải rời trường sau một cuộc bãi khóa. Những năm tiếp theo, ông vừa học vừa hoạt động cách mạng ở Huế, rồi ở Hà Nội. Ngày 22/12/1944, theo chỉ thị của lãnh tụ Hồ Chí Minh, ông thành lập Đội Việt Nam Tuyên truyền Giải phóng quân. Mười năm sau, ông là Tổng Tư lệnh chỉ huy chiến dịch Điện Biên Phủ. Phạm Văn Đồng, quê Quảng Ngãi, cũng từng học ở Quốc Học trước khi ra Hà Nội học tiếp. Năm 1926, ông là một trong những thanh niên dự lớp huấn luyện chính trị do Nguyễn Ái Quốc tổ chức ở Quảng Châu, và về sau đứng đầu Chính phủ hơn ba mươi năm. Học ở những niên khóa khác nhau, họ không cùng ngồi một lớp với Nguyễn Tất Thành. Nhưng cùng một mái trường, cùng dòng sông trước cổng, đã chứng kiến bước khởi đầu của những người sẽ làm nên lịch sử dân tộc."},{"t":"Bạn có biết? Năm 1927, học sinh Võ Nguyên Giáp bị đuổi khỏi Quốc Học vì tham gia bãi khóa – gần hai mươi năm sau khi Nguyễn Tất Thành cũng phải rời ngôi trường này vì đứng về phía nhân dân."},{"t":"Người ký hiệp định, người làm thơ. Danh sách học trò Quốc Học không chỉ có những nhà chính trị, quân sự. Tạ Quang Bửu, sinh năm 1910 ở Nam Đàn, Nghệ An, cùng huyện với Nguyễn Tất Thành, từng học ở Quốc Học trước khi sang Pháp và Anh học toán, vật lý. Ông trở về tham gia kháng chiến, sau này là Bộ trưởng Bộ Đại học và Trung học chuyên nghiệp, có nhiều đóng góp cho nền khoa học và giáo dục đại học nước nhà. Nhà thơ Xuân Diệu cũng là một học trò của trường trong những năm 1930, khi trường mang tên Trung học Khải Định. Tập Thơ thơ của ông, xuất bản năm 1938, là một đỉnh cao của phong trào Thơ mới. Bên cạnh những tên tuổi ấy là nhiều thế hệ thầy giáo, thầy thuốc, kỹ sư, nhà nghiên cứu đã lớn lên từ những dãy lớp bên sông. Chính quyền bảo hộ lập trường để đào tạo thông ngôn và viên chức, nhưng ngôi trường đã đi xa hơn nhiều so với ý định ban đầu ấy (xem chuyên đề Cổng Trường Quốc Học)."},{"t":"Bạn có biết? Ngày 20/7/1954 tại Giơ-ne-vơ, người thay mặt Tổng Tư lệnh Quân đội nhân dân Việt Nam ký Hiệp định đình chỉ chiến sự ở Việt Nam là Thứ trưởng Bộ Quốc phòng Tạ Quang Bửu, một cựu học trò Quốc Học."},{"t":"Hơn một thế kỷ trên cùng một mảnh đất. Từ ngày thành lập, 23/10/1896, đến nay, ngôi trường vẫn đứng trên mảnh đất bên bờ nam sông Hương. Những mái tranh buổi đầu đã nhường chỗ cho các dãy nhà gạch sơn đỏ; tên trường cũng nhiều lần thay đổi trước khi trở lại với hai chữ Quốc Học từ năm 1956. Năm 1996, trường kỷ niệm tròn một trăm năm thành lập. Năm 2021, ngôi trường bước sang tuổi một trăm hai mươi lăm. Hiếm có ngôi trường nào mà sân trường, lớp học và cảnh vật xung quanh lại gắn chặt với lịch sử một thành phố như vậy. Ngày nay, dưới tên Trường Trung học phổ thông chuyên Quốc Học, trường là nơi học tập của những học sinh được tuyển chọn qua kỳ thi tuyển. Học trò hôm nay đi trên sân trường mà nhiều thế hệ đàn anh từng đi, nhìn ra cùng một dòng sông. Khoảng cách hơn một thế kỷ như được thu ngắn lại mỗi lần một lớp học trò mới bước qua cánh cổng."},{"t":"Di tích giữa một ngôi trường đang dạy học. Ngày 26/3/1990, Trường Quốc Học được xếp hạng di tích lịch sử – văn hóa cấp quốc gia. Cũng trong năm ấy, nhân kỷ niệm một trăm năm ngày sinh Chủ tịch Hồ Chí Minh, tượng người học trò Nguyễn Tất Thành được dựng giữa sân trường (xem chuyên đề Tượng học trò Nguyễn Tất Thành ở Trường Quốc Học). Đến năm 2020, địa điểm Trường Quốc Học trở thành một điểm trong Hệ thống di tích lưu niệm Chủ tịch Hồ Chí Minh tại Thừa Thiên Huế, được xếp hạng di tích quốc gia đặc biệt. Điều đặc biệt là di tích ấy không phải một công trình đóng cửa để trưng bày. Mỗi sáng, học sinh vẫn đến lớp, tiếng giảng bài vẫn vang lên trong những dãy nhà đỏ. Việc bảo tồn vì thế đi liền với việc dạy học hằng ngày: vừa giữ dáng vẻ những công trình đã hơn trăm tuổi, vừa bảo đảm chỗ học cho những lớp học trò mới. Chính sự sống động ấy làm cho di tích Quốc Học khác với nhiều di tích khác ở Huế."},{"t":"Dấu tích hôm nay. Du khách đến Huế có thể tìm tới Trường Quốc Học ở số 12 đường Lê Lợi, ngay bờ nam sông Hương. Đứng bên bờ sông trước cổng trường, nhìn sang bờ bắc là tường thành và Kỳ Đài của Kinh thành, nay thuộc Quần thể di tích Cố đô Huế. Nhìn về phía đông là những nhịp vòm của cầu Trường Tiền. Đó gần như là trọn vẹn khung cảnh của những năm người học trò Nguyễn Tất Thành đến lớp, chỉ khác ở dáng vẻ các công trình. Trong không gian 3D của gian trưng bày, ngôi trường được dựng lại theo hình dung về những năm đầu thế kỷ XX, với các dãy lớp mái tranh và cổng hai tầng. Đó là hình ảnh phục dựng minh họa, không phải bản sao chính xác của công trình năm 1908. Đặt cạnh tấm ảnh năm 2008, người xem thấy ngôi trường đã đổi thay thế nào qua một trăm năm, và điều gì vẫn còn nguyên: dòng sông, bờ thành bên kia, và vị trí của một ngôi trường đã đi vào lịch sử."}],"so_chu":1808},{"i":7,"tieu_de_bang":"Tượng học trò Nguyễn Tất Thành ở Trường Quốc Học","tieu_de":"Người học trò trở về sân trường xưa: bức tượng Nguyễn Tất Thành giữa sân Quốc Học","sapo":"Người học trò ấy chỉ ngồi ở Quốc Học chưa trọn một năm, rời trường không mang theo tấm bằng nào. Hơn tám mươi năm sau, Người trở lại giữa sân trường trong dáng hình một pho tượng, đúng vào năm kỷ niệm một trăm năm ngày sinh của Người. Câu chuyện của bức tượng cũng là câu chuyện về một câu hỏi lớn: học để làm gì?","bia":{"src":"textures/ht/ht_anh_tuong_nguyen_tat_thanh_tai_quoc_hoc_hue.jpg","credit":"Ảnh: Lưu Ly at Vietnamese Wikipedia · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Giữa sân trường, một người học trò","text":"Tấm ảnh ở bảng này được chụp ngày 1/5/2008. Tác giả là Lưu Ly, một người đóng góp cho Wikipedia tiếng Việt, và ảnh thuộc phạm vi công cộng. Nhân vật chính của khung hình là tượng người học trò Nguyễn Tất Thành trong sân Trường Quốc Học Huế. Theo Thông tấn xã Việt Nam, bức tượng được đặt ở vị trí trang trọng nhất giữa sân trường. Bước qua cổng trường, ai cũng gặp người học trò ấy trước tiên.\n\nBức tượng khắc họa Người ở tuổi học trò, đúng với quãng đời gắn bó với ngôi trường này. Dáng hình ấy mang một ý nghĩa riêng. Ở hầu hết các tượng đài khác trên khắp đất nước, Người hiện lên là vị lãnh tụ của cả dân tộc. Còn ở đây, giữa những dãy lớp học, Người là một học sinh như bao học sinh khác, cùng lứa tuổi với những người ngày ngày đi qua trước tượng. Học trò Quốc Học hôm nay vì thế có thể nhìn bức tượng như nhìn một người bạn học đi trước.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_tuong_nguyen_tat_thanh_tai_quoc_hoc_hue.jpg","chu_thich":"Tượng người học trò Nguyễn Tất Thành trong sân Trường Quốc Học Huế, dựng năm 1990. Ảnh: Lưu Ly, chụp ngày 1/5/2008, phạm vi công cộng.","credit":"Ảnh: Lưu Ly at Vietnamese Wikipedia · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Năm 1990, năm của những cuộc trở về","text":"Theo cổng thông tin du lịch Khám phá Huế, năm 1990, nhân kỷ niệm một trăm năm ngày sinh Chủ tịch Hồ Chí Minh, tỉnh Thừa Thiên Huế cho xây dựng tượng đài Nguyễn Tất Thành ở trung tâm sân trường. Cùng năm ấy, Nhà lưu niệm Bác Hồ và truyền thống Quốc Học được khánh thành trong khuôn viên trường. Cũng trong năm 1990, ngày 26/3, Trường Quốc Học được xếp hạng di tích lịch sử – văn hóa cấp quốc gia.\n\nNăm 1990 là năm cả nước hướng về kỷ niệm một trăm năm ngày sinh của Người. Ngày 19/5/1990, Bảo tàng Hồ Chí Minh ở Hà Nội được khánh thành. Ở Huế, nơi Người sống hai chặng của thời thơ ấu và tuổi thiếu niên, những dấu tích xưa cũng được tìm lại và ghi nhận. Trên vị trí mộ cũ của bà Hoàng Thị Loan, thành phố dựng nhà bia tưởng niệm (xem chuyên đề Mất mẹ giữa kinh thành). Bức tượng ở Quốc Học là một phần của cuộc trở về ấy, trở về bằng ký ức của những nơi Người từng sống.","doc":2},{"loai":"ban_co_biet","text":"Năm 1987, Đại hội đồng UNESCO khóa 24 thông qua Nghị quyết 24C/18.65 về kỷ niệm một trăm năm ngày sinh Chủ tịch Hồ Chí Minh, ghi nhận Người là anh hùng giải phóng dân tộc và nhà văn hóa lớn của Việt Nam. Năm 1990 vì thế là dịp kỷ niệm mang tầm quốc tế.","nguon_ten":"UNESCO, Nghị quyết 24C/18.65, Đại hội đồng khóa 24, Paris, 1987","doc":3},{"loai":"doan","tieu_de":"Chưa trọn một năm học","text":"Người học trò được tạc tượng ở đây chỉ học ở Quốc Học một thời gian ngắn. Nhiều sách in trước đây ghi Người vào trường từ mùa thu năm 1907. Tư liệu lưu trữ công bố về sau cho thấy tháng 8/1908, hiệu trưởng Quốc Học nhận học sinh Nguyễn Sinh Côn, quê Nghệ An. Người học ở trường trong niên khóa 1908 – 1909 (xem chuyên đề Lớp học Trường Quốc Học Huế đầu thế kỷ XX). Khoảng tháng 6/1909, Người rời trường theo cha vào Bình Định.\n\nDù theo cách ghi nào, quãng thời gian ấy cũng chưa trọn một năm học, và Người không nhận tấm bằng nào của Quốc Học. Điều khiến ngôi trường tự hào vì thế không phải thành tích học tập hay mảnh bằng. Đó là lựa chọn của người học trò mười tám tuổi: đứng về phía những người nông dân chống sưu thuế mùa xuân năm 1908 (xem chuyên đề Người phiên dịch cho đoàn nông dân). Rồi từ đó, Người dấn thân vào con đường đi tìm lời giải cho vận mệnh dân tộc.","doc":4},{"loai":"anh","src":"textures/bang_w/G02_7_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tượng học trò Nguyễn Tất Thành ở Trường Quốc Học”, nhìn từ xa."},{"loai":"doan","tieu_de":"Từ lớp học thuộc địa đến phiên họp Chính phủ đầu tiên","text":"Ngày 2/9/1945, tại Quảng trường Ba Đình, người học trò năm xưa đọc Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa. Ngay hôm sau, ngày 3/9/1945, trong phiên họp đầu tiên của Hội đồng Chính phủ, Chủ tịch Hồ Chí Minh nêu sáu nhiệm vụ cấp bách. Trong số đó có việc mở chiến dịch chống nạn mù chữ, và việc bỏ ngay thuế thân, thuế chợ, thuế đò.\n\nĐặt cạnh những năm ở Huế, hai nhiệm vụ ấy mang một ý nghĩa đặc biệt. Gần bốn mươi năm trước, chàng học trò đã làm phiên dịch cho những người nông dân đòi giảm sưu thuế trước Tòa Khâm sứ. Nay, trên cương vị người đứng đầu Nhà nước, Người đề nghị bãi bỏ chính thứ thuế thân từng đè nặng lên vai họ. Người học trò từng thấy nhà trường thuộc địa chỉ dành cho số ít, nay muốn mọi người dân đều biết chữ. Ngày 8/9/1945, Người ký sắc lệnh thành lập Nha Bình dân học vụ, lo việc xóa nạn mù chữ trong cả nước.","doc":5},{"loai":"doan","tieu_de":"Lá thư ngày khai trường","text":"Tháng 9/1945, nhân ngày khai trường đầu tiên của nước Việt Nam Dân chủ Cộng hòa, Chủ tịch Hồ Chí Minh viết thư gửi học sinh cả nước. Người hình dung trước cảnh nhộn nhịp, tưng bừng của ngày tựu trường ở khắp nơi. Các em được gặp lại thầy, gặp lại bạn sau mấy tháng nghỉ học và bao biến chuyển khác thường. Nhưng điều Người nhấn mạnh là từ đây, các em bắt đầu được nhận một nền giáo dục hoàn toàn Việt Nam.\n\nBức thư nhắc rằng sau tám mươi năm nô lệ làm cho nước nhà yếu hèn, đất nước cần xây dựng lại cơ đồ tổ tiên để lại, làm sao theo kịp các nước trên hoàn cầu. Trong công cuộc ấy, học sinh có phần gánh vác rất lớn. Người dặn các em trong năm học mới phải cố gắng, siêng năng học tập, ngoan ngoãn, nghe thầy, yêu bạn. Lời lẽ ân cần như lời một người cha, nhưng đặt lên vai thế hệ trẻ một trách nhiệm lớn lao.","doc":6},{"loai":"trich","text":"Non sông Việt Nam có trở nên tươi đẹp hay không, dân tộc Việt Nam có bước tới đài vinh quang để sánh vai với các cường quốc năm châu được hay không, chính là nhờ một phần lớn ở công học tập của các em.","nguoi":"Chủ tịch Hồ Chí Minh","nguon_ten":"Thư gửi học sinh nhân ngày khai trường đầu tiên của nước Việt Nam Dân chủ Cộng hòa, tháng 9/1945; Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia","doc":7},{"loai":"doan","tieu_de":"Hai nền giáo dục, hai mục đích","text":"Đọc bức thư năm 1945 bên cạnh lịch sử Trường Quốc Học, người xem thấy rõ hai quan niệm về việc học. Ngôi trường Người từng theo học được lập ra trước hết để đào tạo thông ngôn, thư ký, viên chức cho bộ máy bảo hộ. Tấm bằng của trường là tấm vé vào chốn công đường, phục vụ một chính quyền của người ngoại quốc. Nền giáo dục mà Người nói tới năm 1945 thì khác hẳn. Đó là nền giáo dục của một nước độc lập, đào tạo các em thành những công dân hữu ích cho nước Việt Nam, phát triển những năng lực sẵn có của các em.\n\nBức tượng giữa sân Quốc Học vì thế như nối hai đầu của một câu chuyện. Một đầu là người học trò đã rời bỏ con đường làm viên chức mà trường thuộc địa mở sẵn. Đầu kia là vị Chủ tịch nước mong học trò học để xây dựng đất nước của chính mình.","doc":8},{"loai":"anh","src":"textures/bang_w/G02_7_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tượng học trò Nguyễn Tất Thành ở Trường Quốc Học”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Trồng người","text":"Trong những năm làm Chủ tịch nước, Người nhiều lần gửi thư cho thầy cô và học sinh mỗi khi bước vào năm học mới. Năm 1958, nói chuyện với lớp học chính trị của giáo viên cấp hai, cấp ba toàn miền Bắc, Người nêu một ý về sau trở thành phương châm của ngành giáo dục: muốn có lợi ích trăm năm thì phải trồng người. Câu nói ngắn gọn, mượn hình ảnh gần gũi của nhà nông, đặt việc giáo dục con người lên tầm lâu dài nhất của một quốc gia.\n\nMùa thu năm 1968, giữa lúc chiến tranh còn ác liệt, trong một trong những bức thư cuối cùng gửi ngành giáo dục, Người vẫn căn dặn dù khó khăn đến đâu cũng phải thi đua dạy thật tốt, học thật tốt. Từ lá thư năm 1945 đến lá thư năm 1968, mối quan tâm ấy không hề đổi thay. Người học trò Quốc Học năm nào hiểu hơn ai hết rằng việc học quyết định tương lai của một dân tộc.","doc":9},{"loai":"trich","text":"Vì lợi ích mười năm thì phải trồng cây, vì lợi ích trăm năm thì phải trồng người.","nguoi":"Chủ tịch Hồ Chí Minh","nguon_ten":"Bài nói chuyện tại lớp học chính trị của giáo viên cấp II, cấp III toàn miền Bắc, 13/9/1958; Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia","doc":10},{"loai":"doan","tieu_de":"Một hành trình trên đất Huế","text":"Bức tượng ở Quốc Học là một điểm trên hành trình tìm lại dấu chân Người ở Huế. Từ ngôi trường bên sông, du khách có thể sang bờ bắc, tìm đến ngôi nhà lưu niệm trên đường Mai Thúc Loan, nơi gia đình Người ở trong chặng thứ nhất và nơi bà Hoàng Thị Loan qua đời năm 1901. Xa hơn, ở làng Dương Nỗ phía đông thành phố, là ngôi nhà nơi ông Nguyễn Sinh Sắc dạy học và cậu bé Nguyễn Sinh Cung học những chữ Hán đầu tiên. Mỗi nơi gắn với một lát cắt của tuổi thơ, tuổi thiếu niên, đã được kể ở các bảng khác trong gian này.\n\nTrong hành trình ấy, Quốc Học là nơi duy nhất vẫn rộn tiếng học trò. Nhà lưu niệm, nhà bia có thể lặng lẽ, còn sân trường thì mỗi sáng lại rộn ràng. Bức tượng người học trò đứng giữa khung cảnh ấy như người bạn học lớn tuổi nhất của trường, lặng lẽ nhìn từng lớp học trò mới đến rồi đi.","doc":11},{"loai":"ban_co_biet","text":"Bức thư Chủ tịch Hồ Chí Minh gửi học sinh tháng 9/1945 đã được đưa vào sách giáo khoa Tiếng Việt lớp 5. Nhiều thế hệ học sinh thuộc lòng câu “Non sông Việt Nam có trở nên tươi đẹp hay không…” ngay từ những ngày đầu năm học.","nguon_ten":"Bộ Giáo dục và Đào tạo, sách Tiếng Việt 5, tập một, NXB Giáo dục Việt Nam","doc":12},{"loai":"anh","src":"textures/bang_w/G02_7_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tượng học trò Nguyễn Tất Thành ở Trường Quốc Học”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Trường Quốc Học ở số 12 đường Lê Lợi, thành phố Huế, là một điểm trong Hệ thống di tích lưu niệm Chủ tịch Hồ Chí Minh tại Thừa Thiên Huế, được xếp hạng di tích quốc gia đặc biệt năm 2020. Khách tham quan có thể vào sân trường đứng trước bức tượng, rồi tìm đến Nhà lưu niệm Bác Hồ và truyền thống Quốc Học trong khuôn viên trường. Vì đây vẫn là một ngôi trường đang dạy học, khách nên chọn giờ phù hợp và giữ yên tĩnh cho các lớp học.\n\nTấm ảnh năm 2008 ở bảng này ghi lại bức tượng trong khung cảnh ngày nay của trường. Trong không gian 3D của bảo tàng, ngôi trường được dựng lại theo dáng vẻ những năm đầu thế kỷ XX, khi chưa có bức tượng nào. Đặt hai hình ảnh bên nhau, người xem thấy trọn một vòng. Người học trò bước ra khỏi sân trường năm 1909 để rồi đi tìm đường cứu nước. Hơn tám mươi năm sau, Người trở về đứng giữa sân trường ấy, trong tâm trí những thế hệ học trò kế tiếp.","doc":13}],"nguon":["“Trường Quốc Học Huế – Theo chân Bác Hồ thời niên thiếu”, cổng thông tin du lịch Khám phá Huế: https://khamphahue.com.vn/desktopmodules/DNNTinBai/PrintTinBai.aspx?newsid=5D9DFA17-D799-4363-9720-AEF60132034B","Tường Vi, “Trường Quốc học Huế – nơi giác ngộ tinh thần yêu nước của Bác Hồ”, TTXVN (Vietnam+), 18/5/2020: https://www.vietnamplus.vn/truong-quoc-hoc-hue-noi-giac-ngo-tinh-than-yeu-nuoc-cua-bac-ho-post640707.vnp","Hồ Chí Minh, Thư gửi các học sinh (9/1945) và Những nhiệm vụ cấp bách của Nhà nước Việt Nam Dân chủ Cộng hòa (3/9/1945); Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia","Bảo tàng Hồ Chí Minh, Hồ Chí Minh – Tiểu sử, NXB Chính trị quốc gia, 2008","UNESCO, Nghị quyết 24C/18.65, Đại hội đồng khóa 24, 1987","Ảnh tượng Nguyễn Tất Thành tại Trường Quốc Học Huế, Lưu Ly chụp ngày 1/5/2008, phạm vi công cộng (Wikimedia Commons)"],"doc":[{"t":"Người học trò trở về sân trường xưa: bức tượng Nguyễn Tất Thành giữa sân Quốc Học. Người học trò ấy chỉ ngồi ở Quốc Học chưa trọn một năm, rời trường không mang theo tấm bằng nào. Hơn tám mươi năm sau, Người trở lại giữa sân trường trong dáng hình một pho tượng, đúng vào năm kỷ niệm một trăm năm ngày sinh của Người. Câu chuyện của bức tượng cũng là câu chuyện về một câu hỏi lớn: học để làm gì?"},{"t":"Giữa sân trường, một người học trò. Tấm ảnh ở bảng này được chụp ngày 1/5/2008. Tác giả là Lưu Ly, một người đóng góp cho Wikipedia tiếng Việt, và ảnh thuộc phạm vi công cộng. Nhân vật chính của khung hình là tượng người học trò Nguyễn Tất Thành trong sân Trường Quốc Học Huế. Theo Thông tấn xã Việt Nam, bức tượng được đặt ở vị trí trang trọng nhất giữa sân trường. Bước qua cổng trường, ai cũng gặp người học trò ấy trước tiên. Bức tượng khắc họa Người ở tuổi học trò, đúng với quãng đời gắn bó với ngôi trường này. Dáng hình ấy mang một ý nghĩa riêng. Ở hầu hết các tượng đài khác trên khắp đất nước, Người hiện lên là vị lãnh tụ của cả dân tộc. Còn ở đây, giữa những dãy lớp học, Người là một học sinh như bao học sinh khác, cùng lứa tuổi với những người ngày ngày đi qua trước tượng. Học trò Quốc Học hôm nay vì thế có thể nhìn bức tượng như nhìn một người bạn học đi trước."},{"t":"Năm 1990, năm của những cuộc trở về. Theo cổng thông tin du lịch Khám phá Huế, năm 1990, nhân kỷ niệm một trăm năm ngày sinh Chủ tịch Hồ Chí Minh, tỉnh Thừa Thiên Huế cho xây dựng tượng đài Nguyễn Tất Thành ở trung tâm sân trường. Cùng năm ấy, Nhà lưu niệm Bác Hồ và truyền thống Quốc Học được khánh thành trong khuôn viên trường. Cũng trong năm 1990, ngày 26/3, Trường Quốc Học được xếp hạng di tích lịch sử – văn hóa cấp quốc gia. Năm 1990 là năm cả nước hướng về kỷ niệm một trăm năm ngày sinh của Người. Ngày 19/5/1990, Bảo tàng Hồ Chí Minh ở Hà Nội được khánh thành. Ở Huế, nơi Người sống hai chặng của thời thơ ấu và tuổi thiếu niên, những dấu tích xưa cũng được tìm lại và ghi nhận. Trên vị trí mộ cũ của bà Hoàng Thị Loan, thành phố dựng nhà bia tưởng niệm (xem chuyên đề Mất mẹ giữa kinh thành). Bức tượng ở Quốc Học là một phần của cuộc trở về ấy, trở về bằng ký ức của những nơi Người từng sống."},{"t":"Bạn có biết? Năm 1987, Đại hội đồng UNESCO khóa 24 thông qua Nghị quyết 24C/18.65 về kỷ niệm một trăm năm ngày sinh Chủ tịch Hồ Chí Minh, ghi nhận Người là anh hùng giải phóng dân tộc và nhà văn hóa lớn của Việt Nam. Năm 1990 vì thế là dịp kỷ niệm mang tầm quốc tế."},{"t":"Chưa trọn một năm học. Người học trò được tạc tượng ở đây chỉ học ở Quốc Học một thời gian ngắn. Nhiều sách in trước đây ghi Người vào trường từ mùa thu năm 1907. Tư liệu lưu trữ công bố về sau cho thấy tháng 8/1908, hiệu trưởng Quốc Học nhận học sinh Nguyễn Sinh Côn, quê Nghệ An. Người học ở trường trong niên khóa 1908 – 1909 (xem chuyên đề Lớp học Trường Quốc Học Huế đầu thế kỷ XX). Khoảng tháng 6/1909, Người rời trường theo cha vào Bình Định. Dù theo cách ghi nào, quãng thời gian ấy cũng chưa trọn một năm học, và Người không nhận tấm bằng nào của Quốc Học. Điều khiến ngôi trường tự hào vì thế không phải thành tích học tập hay mảnh bằng. Đó là lựa chọn của người học trò mười tám tuổi: đứng về phía những người nông dân chống sưu thuế mùa xuân năm 1908 (xem chuyên đề Người phiên dịch cho đoàn nông dân). Rồi từ đó, Người dấn thân vào con đường đi tìm lời giải cho vận mệnh dân tộc."},{"t":"Từ lớp học thuộc địa đến phiên họp Chính phủ đầu tiên. Ngày 2/9/1945, tại Quảng trường Ba Đình, người học trò năm xưa đọc Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa. Ngay hôm sau, ngày 3/9/1945, trong phiên họp đầu tiên của Hội đồng Chính phủ, Chủ tịch Hồ Chí Minh nêu sáu nhiệm vụ cấp bách. Trong số đó có việc mở chiến dịch chống nạn mù chữ, và việc bỏ ngay thuế thân, thuế chợ, thuế đò. Đặt cạnh những năm ở Huế, hai nhiệm vụ ấy mang một ý nghĩa đặc biệt. Gần bốn mươi năm trước, chàng học trò đã làm phiên dịch cho những người nông dân đòi giảm sưu thuế trước Tòa Khâm sứ. Nay, trên cương vị người đứng đầu Nhà nước, Người đề nghị bãi bỏ chính thứ thuế thân từng đè nặng lên vai họ. Người học trò từng thấy nhà trường thuộc địa chỉ dành cho số ít, nay muốn mọi người dân đều biết chữ. Ngày 8/9/1945, Người ký sắc lệnh thành lập Nha Bình dân học vụ, lo việc xóa nạn mù chữ trong cả nước."},{"t":"Lá thư ngày khai trường. Tháng 9/1945, nhân ngày khai trường đầu tiên của nước Việt Nam Dân chủ Cộng hòa, Chủ tịch Hồ Chí Minh viết thư gửi học sinh cả nước. Người hình dung trước cảnh nhộn nhịp, tưng bừng của ngày tựu trường ở khắp nơi. Các em được gặp lại thầy, gặp lại bạn sau mấy tháng nghỉ học và bao biến chuyển khác thường. Nhưng điều Người nhấn mạnh là từ đây, các em bắt đầu được nhận một nền giáo dục hoàn toàn Việt Nam. Bức thư nhắc rằng sau tám mươi năm nô lệ làm cho nước nhà yếu hèn, đất nước cần xây dựng lại cơ đồ tổ tiên để lại, làm sao theo kịp các nước trên hoàn cầu. Trong công cuộc ấy, học sinh có phần gánh vác rất lớn. Người dặn các em trong năm học mới phải cố gắng, siêng năng học tập, ngoan ngoãn, nghe thầy, yêu bạn. Lời lẽ ân cần như lời một người cha, nhưng đặt lên vai thế hệ trẻ một trách nhiệm lớn lao."},{"t":"Non sông Việt Nam có trở nên tươi đẹp hay không, dân tộc Việt Nam có bước tới đài vinh quang để sánh vai với các cường quốc năm châu được hay không, chính là nhờ một phần lớn ở công học tập của các em. — Chủ tịch Hồ Chí Minh"},{"t":"Hai nền giáo dục, hai mục đích. Đọc bức thư năm 1945 bên cạnh lịch sử Trường Quốc Học, người xem thấy rõ hai quan niệm về việc học. Ngôi trường Người từng theo học được lập ra trước hết để đào tạo thông ngôn, thư ký, viên chức cho bộ máy bảo hộ. Tấm bằng của trường là tấm vé vào chốn công đường, phục vụ một chính quyền của người ngoại quốc. Nền giáo dục mà Người nói tới năm 1945 thì khác hẳn. Đó là nền giáo dục của một nước độc lập, đào tạo các em thành những công dân hữu ích cho nước Việt Nam, phát triển những năng lực sẵn có của các em. Bức tượng giữa sân Quốc Học vì thế như nối hai đầu của một câu chuyện. Một đầu là người học trò đã rời bỏ con đường làm viên chức mà trường thuộc địa mở sẵn. Đầu kia là vị Chủ tịch nước mong học trò học để xây dựng đất nước của chính mình."},{"t":"Trồng người. Trong những năm làm Chủ tịch nước, Người nhiều lần gửi thư cho thầy cô và học sinh mỗi khi bước vào năm học mới. Năm 1958, nói chuyện với lớp học chính trị của giáo viên cấp hai, cấp ba toàn miền Bắc, Người nêu một ý về sau trở thành phương châm của ngành giáo dục: muốn có lợi ích trăm năm thì phải trồng người. Câu nói ngắn gọn, mượn hình ảnh gần gũi của nhà nông, đặt việc giáo dục con người lên tầm lâu dài nhất của một quốc gia. Mùa thu năm 1968, giữa lúc chiến tranh còn ác liệt, trong một trong những bức thư cuối cùng gửi ngành giáo dục, Người vẫn căn dặn dù khó khăn đến đâu cũng phải thi đua dạy thật tốt, học thật tốt. Từ lá thư năm 1945 đến lá thư năm 1968, mối quan tâm ấy không hề đổi thay. Người học trò Quốc Học năm nào hiểu hơn ai hết rằng việc học quyết định tương lai của một dân tộc."},{"t":"Vì lợi ích mười năm thì phải trồng cây, vì lợi ích trăm năm thì phải trồng người. — Chủ tịch Hồ Chí Minh"},{"t":"Một hành trình trên đất Huế. Bức tượng ở Quốc Học là một điểm trên hành trình tìm lại dấu chân Người ở Huế. Từ ngôi trường bên sông, du khách có thể sang bờ bắc, tìm đến ngôi nhà lưu niệm trên đường Mai Thúc Loan, nơi gia đình Người ở trong chặng thứ nhất và nơi bà Hoàng Thị Loan qua đời năm 1901. Xa hơn, ở làng Dương Nỗ phía đông thành phố, là ngôi nhà nơi ông Nguyễn Sinh Sắc dạy học và cậu bé Nguyễn Sinh Cung học những chữ Hán đầu tiên. Mỗi nơi gắn với một lát cắt của tuổi thơ, tuổi thiếu niên, đã được kể ở các bảng khác trong gian này. Trong hành trình ấy, Quốc Học là nơi duy nhất vẫn rộn tiếng học trò. Nhà lưu niệm, nhà bia có thể lặng lẽ, còn sân trường thì mỗi sáng lại rộn ràng. Bức tượng người học trò đứng giữa khung cảnh ấy như người bạn học lớn tuổi nhất của trường, lặng lẽ nhìn từng lớp học trò mới đến rồi đi."},{"t":"Bạn có biết? Bức thư Chủ tịch Hồ Chí Minh gửi học sinh tháng 9/1945 đã được đưa vào sách giáo khoa Tiếng Việt lớp 5. Nhiều thế hệ học sinh thuộc lòng câu “Non sông Việt Nam có trở nên tươi đẹp hay không…” ngay từ những ngày đầu năm học."},{"t":"Dấu tích hôm nay. Trường Quốc Học ở số 12 đường Lê Lợi, thành phố Huế, là một điểm trong Hệ thống di tích lưu niệm Chủ tịch Hồ Chí Minh tại Thừa Thiên Huế, được xếp hạng di tích quốc gia đặc biệt năm 2020. Khách tham quan có thể vào sân trường đứng trước bức tượng, rồi tìm đến Nhà lưu niệm Bác Hồ và truyền thống Quốc Học trong khuôn viên trường. Vì đây vẫn là một ngôi trường đang dạy học, khách nên chọn giờ phù hợp và giữ yên tĩnh cho các lớp học. Tấm ảnh năm 2008 ở bảng này ghi lại bức tượng trong khung cảnh ngày nay của trường. Trong không gian 3D của bảo tàng, ngôi trường được dựng lại theo dáng vẻ những năm đầu thế kỷ XX, khi chưa có bức tượng nào. Đặt hai hình ảnh bên nhau, người xem thấy trọn một vòng. Người học trò bước ra khỏi sân trường năm 1909 để rồi đi tìm đường cứu nước. Hơn tám mươi năm sau, Người trở về đứng giữa sân trường ấy, trong tâm trí những thế hệ học trò kế tiếp."}],"so_chu":1866},{"i":8,"tieu_de_bang":"Cổng Trường Quốc Học","tieu_de":"Cổng Quốc Học: năm dáng hình của một cánh cổng, và người học trò bước qua năm 1908","sapo":"Ai đến Huế cũng nhận ra Quốc Học từ xa nhờ cánh cổng hai tầng mái ngói đỏ bên đường Lê Lợi. Nhưng cánh cổng người học trò Nguyễn Sinh Côn bước qua năm 1908 không phải cánh cổng hôm nay. Hơn một thế kỷ, cổng trường đã mang ít nhất năm dáng hình, từng đề chữ Hán, chữ Pháp, rồi có lúc bị đục mất chữ. Lần theo cánh cổng ấy là lần theo lịch sử một ngôi trường và một người học trò.","bia":{"src":"textures/bai/G02_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Lá thư hỏi về một cậu học trò","text":"Ngày 4/8/1908, Khâm sứ Trung Kỳ Lévecque, người đứng đầu bộ máy bảo hộ Pháp ở Huế, gửi thư cho hiệu trưởng Trường Quốc Học. Ông hỏi về lai lịch một học trò vừa đỗ tiểu học, sắp được chuyển thẳng lên Quốc Học. Người học trò ấy tên là Nguyễn Sinh Côn, gốc Nghệ An. Chỉ ba ngày sau, ngày 7/8/1908, hiệu trưởng Chouquet gửi văn thư phúc đáp.\n\nNguyễn Sinh Côn là tên gọi ở Huế của Nguyễn Tất Thành. Bốn tháng trước đó, anh vừa đi cùng đoàn nông dân biểu tình chống sưu thuế đến Tòa Khâm sứ, và từ đó bị mật thám Pháp để mắt tới. Hai văn bản trao đổi giữa Tòa Khâm sứ và nhà trường hiện nằm trong văn khố Pháp ở Aix-en-Provence, thuộc bộ hồ sơ mật thám lập về Nguyễn Ái Quốc. Chúng giúp làm rõ một chi tiết từng gây tranh luận. Nguyễn Tất Thành vào Quốc Học sau cuộc biểu tình, chứ không phải từ mùa thu năm 1907 như nhiều tài liệu cũ đã viết. Theo Tiểu sử do Bảo tàng Hồ Chí Minh biên soạn, tháng 9/1908 anh vào lớp trung đẳng, tức lớp nhì, của trường.","doc":1},{"loai":"trich","text":"Tôi hân hạnh báo cho ngài rõ sẽ có thể tiếp nhận vào Trường Quốc Học học sinh có tên Nguyễn Sinh Côn, gốc người Nghệ An, học sinh Trường Pháp - An Nam tỉnh Thừa Thiên.","nguoi":"Hiệu trưởng Trường Quốc Học Chouquet, văn thư phúc đáp Tòa Khâm sứ ngày 7/8/1908 (bản dịch)","nguon_ten":"Hồ sơ lưu tại Trung tâm Lưu trữ hải ngoại Pháp, Aix-en-Provence; bản dịch công bố trên báo Tuổi Trẻ, 5/2/2018","doc":2},{"loai":"doan","tieu_de":"Cánh cổng năm 1908 trông ra sao","text":"Cánh cổng Nguyễn Tất Thành đi qua năm ấy khác xa cánh cổng du khách thấy hôm nay. Theo một nghiên cứu của Khoa Kiến trúc, Trường Đại học Khoa học, Đại học Huế, công bố năm 2021, cổng trường thời đầu mang kiểu kiến trúc An Nam. Hai dãy tường rộng chạy giáp vào một cổng có lầu, cột đỡ lầu bằng gỗ, mái lợp theo kiểu Tàu. Bên trong cổng có cầu thang xoắn ốc dẫn lên lầu, và trên lầu treo một quả chuông đồng. Ảnh chụp năm 1913 cho thấy tầng dưới xây gạch đặc, tầng lầu dựng trên cột gỗ, mái ngói có họa tiết trang trí truyền thống. Người vẽ kiểu và năm dựng cổng chưa được xác định chính xác, chỉ biết là trong những năm đầu của trường.\n\nSau cánh cổng ấy chưa có những dãy nhà gạch kiểu Pháp. Các lớp học là những dãy nhà tranh vách đất, mái rạ lợp sơ sài nên mùa mưa thường bị dột. Các dãy nhà dựng đối xứng hai bên lối đi chính giữa: bên trái là phòng học, bên phải là nhà hiệu trưởng, phòng giáo viên và chỗ ở của học trò nội trú. Ông Lê Thanh Cảnh, một người bạn học của Nguyễn Tất Thành, về sau đặt tên cho hồi ký của mình là “Dưới mái tranh Trường Quốc Học những năm 1906 – 1911”.","doc":3},{"loai":"anh","src":"textures/bang_w/G02_8_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Cổng Trường Quốc Học”, nhìn từ xa."},{"loai":"doan","tieu_de":"Ngôi trường dựng trên nền doanh trại thủy binh","text":"Trường Quốc Học ra đời ngày 23/10/1896, theo chỉ dụ năm Thành Thái thứ tám và nghị định ngày 18/11/1896 của Toàn quyền Đông Dương Rousseau. Trường được dựng ở bờ nam sông Hương, trên nền Tả doanh Thủy sư, nơi huấn luyện binh lính đường thủy của quân đội nhà Nguyễn. Mặt tiền trông ra con đường người Pháp đặt tên Jules Ferry, nay là đường Lê Lợi. Vật liệu xây dựng thời ấy lấy từ những dãy nhà cũ của trại lính vệ bị phá dỡ.\n\nGần hai mươi năm đầu, trường mang tên Pháp tự Quốc học đường, dạy tiếng Pháp, chữ quốc ngữ và chữ Nho ở bậc tiểu học. Năm 1897, trường xây thêm nhà hiệu trưởng ba gian hai chái. Năm 1899, học trò đông hơn, trường dựng thêm một dãy lớp tiểu học ba mươi gian và một dãy lớp bổ túc mười sáu gian. Trong những năm 1896 – 1902, hiệu trưởng là một người Pháp, còn ông Ngô Đình Khả giữ chức chưởng giáo. Tài liệu về trường kể rằng ông Khả cho sơn đỏ các bức tường. Sắc đỏ vì thế đã gắn với Quốc Học ngay từ thuở ban đầu.","doc":4},{"loai":"ban_co_biet","text":"Cổng Quốc Học thời đầu có cầu thang xoắn ốc bên trong dẫn lên lầu, và trên lầu treo một quả chuông đồng. Một bức ảnh tư liệu của nhà trường vẫn còn ghi lại chiếc chuông treo trên cổng.","nguon_ten":"Nguyễn Ngọc Tùng và cộng sự, Tạp chí Khoa học và Công nghệ, Trường Đại học Khoa học – Đại học Huế, tập 19, số 1, 2021; báo Tuổi Trẻ, 5/2/2018","doc":5},{"loai":"doan","tieu_de":"Hai chữ 國學 và một nghịch lý","text":"Hai chữ Hán 國學 đọc theo âm Hán Việt là “Quốc Học”. Chữ 國 nghĩa là nước, chữ 學 nghĩa là học, ghép lại có thể hiểu là nền học của nước nhà. Thế nhưng ngôi trường mang cái tên ấy lại lấy tiếng Pháp làm chính. Mục đích trước hết của chính quyền bảo hộ là đào tạo thông ngôn, thư ký, viên chức cho bộ máy cai trị. Cái tên hướng về nước nhà, còn chương trình học hướng về chính quốc.\n\nNghịch lý ấy lại sinh ra những điều người lập trường không mong muốn. Tiểu sử chính thức của Chủ tịch Hồ Chí Minh ghi nhận, thời học ở Quốc Học, Nguyễn Tất Thành được tiếp xúc nhiều với sách báo Pháp. Trong số thầy giáo của trường có những người yêu nước như thầy Hoàng Thông, thầy Lê Văn Miến. Ảnh hưởng của các thầy và của sách báo tiến bộ làm lớn dần trong anh ý muốn sang phương Tây, tìm hiểu tình hình các nước và học hỏi thành tựu văn minh nhân loại. Cánh cổng mang tên “Quốc Học” vì thế đã mở ra cho người học trò một con đường khác hẳn con đường làm viên chức.","doc":6},{"loai":"anh","src":"textures/ht/ht_anh_college_quoc_hoc_a_hue_2e_annee_complementaire.jpg","chu_thich":"Một lớp học của Trường Quốc Học Huế đầu thế kỷ XX, ảnh công bố năm 1913, chỉ vài năm sau khi Nguyễn Tất Thành rời trường.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Một câu hỏi trong giờ vẽ","text":"Theo hồ sơ di tích do Cục Di sản văn hóa giới thiệu, Nguyễn Tất Thành nằm trong danh sách mười học sinh giỏi nhất của trường Pháp – Việt được chuyển thẳng vào Quốc Học, niên khóa 1908 – 1909. Nhà giáo Lê Thiện, bạn học thời tiểu học, kể với nhà nghiên cứu Nguyễn Đắc Xuân rằng anh Côn học giỏi nhưng không học gạo. Học môn gì anh cũng hỏi cặn kẽ. Hán văn anh giỏi nhất lớp, còn Pháp văn thì không trò xứ Nghệ nào bằng.\n\nỞ Quốc Học, thầy dạy vẽ là họa sĩ Lê Văn Miến. Theo lời kể của họa sĩ Tôn Thất Sa, cũng là thầy giáo Quốc Học, thầy Miến thường dành thời gian trong giờ vẽ để kể cho học trò nghe về nước Pháp. Trò Côn thích nghe thầy kể chuyện hơn là học vẽ, và có lần đã hỏi thầy làm sao để sang Pháp xem người Pháp sống ra sao. Đây là lời kể hồi ức do nhà nghiên cứu Nguyễn Đắc Xuân ghi lại. Nhưng nó khớp với điều sách của Trần Dân Tiên chép về Người trước lúc ra đi: muốn đi xem nước Pháp và các nước khác, xem họ làm thế nào, rồi trở về giúp đồng bào.","doc":7},{"loai":"anh","src":"textures/bang_w/G02_8_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Cổng Trường Quốc Học”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Rời trường: bị đuổi hay tự ra đi","text":"Nguyễn Tất Thành học ở Quốc Học chưa trọn một năm học. Về cách anh rời trường, các tài liệu không hoàn toàn thống nhất. Một số sách cho rằng anh bị đuổi học, vì thái độ không chịu khuất phục những thầy giáo Pháp coi thường học trò Việt, và vì các hoạt động khiến Tòa Khâm sứ lo ngại. Nhiều sách phổ thông lại gắn việc bị đuổi học với cuộc biểu tình chống thuế năm 1908.\n\nCác nhà nghiên cứu Nguyễn Đắc Xuân và Nguyễn Hồng Việt thì cho rằng anh không bị đuổi. Theo tư liệu họ dẫn, biết mình bị theo dõi, anh tự nghỉ học, ẩn ở Huế một thời gian, rồi theo cha vào Bình Định. Bảo tàng Hồ Chí Minh Thừa Thiên Huế đánh giá cách lý giải này là phù hợp. Tiểu sử chính thức ghi rằng khoảng tháng 6/1909, Nguyễn Tất Thành rời Trường Quốc Học theo cha vào Bình Định, khi ông Nguyễn Sinh Sắc được bổ làm Tri huyện Bình Khê. Dù rời trường theo cách nào, người học trò ấy không mang theo mảnh bằng Quốc Học nào. Thứ anh mang theo là tiếng Pháp, những trang sách đã đọc, và câu hỏi về con đường cứu nước.","doc":8},{"loai":"doan","tieu_de":"Năm dáng hình của một cánh cổng","text":"Năm 1902, các lớp tiểu học của trường cháy rụi và được dựng lại theo mẫu cũ. Năm 1911, trường lại bị cháy. Từ tháng 5/1915, thầu khoán Le Roy cùng hàng trăm thợ tái thiết trường bằng gạch ngói theo kiểu Pháp, trên khu đất rộng hơn năm héc-ta. Cùng năm ấy, trường nâng lên bậc trung học, lấy tên Collège Quốc Học. Riêng cổng chính được xây bằng xi măng theo lối tam quan cổ truyền.\n\nKhoảng những năm 1933 – 1936, ông Boularand, tổng giám thị của trường, cho cải tạo cổng theo kiến trúc Nhật Bản và sơn màu đỏ. Hai cột cổng khắc đôi câu đối chữ Hán của Nguyễn Đức Đôn, dịch nghĩa là: “Vạn dặm xa thư về một mối, trăm năm sông núi thấy cao xanh”. Năm 1936, nhân kỷ niệm bốn mươi năm thành lập, trường đổi tên là Trung học Khải Định. Cổng được xây lại theo phong cách Việt với bốn trụ đắp nổi hoa sen, trên đề hàng chữ Hán “Khải Định trung học đường” và dòng chữ Pháp “Lycée Khải Định”. Ngày 26/12/1956, dịp kỷ niệm sáu mươi năm, trường trở lại với tên Quốc Học.","doc":9},{"loai":"ban_co_biet","text":"Năm 1958, biển xi măng trước cổng đắp nổi ba chữ quốc ngữ “Trường Quốc Học”, hai bên chua thêm hai chữ Hán 國學. Năm 1979, có người cho rằng chữ Nho là “đồ ngoại” nên hai chữ Hán bị đục bỏ. Quốc Học cũng là trường học duy nhất ở thành phố Huế có cổng hai tầng.","nguon_ten":"Nguyễn Ngọc Tùng và cộng sự, “Vài nét về kiến trúc cổng trường Quốc Học Huế”, Tạp chí Khoa học và Công nghệ, Trường Đại học Khoa học – Đại học Huế, 2021","doc":10},{"loai":"doan","tieu_de":"Cánh cổng hôm nay","text":"Cánh cổng du khách thấy hôm nay được xây năm 1958. Thầy Nguyễn Đình Hàm, hiệu trưởng những năm 1956 – 1958, kể rằng chính ông vẽ kiểu và thuê thợ xây lại cổng. Nhóm nghiên cứu của Đại học Huế ghi nhận kiến trúc cổng do họa sĩ Tôn Thất Sa thiết kế. Đó cũng là người đã kể lại câu chuyện trò Côn hỏi thầy dạy vẽ về nước Pháp. Cổng theo lối tam quan, bên trên có vọng lâu, hai tầng mái lợp ngói âm dương tráng men đỏ màu gạch cua. Cổng rộng 9,1 mét, sâu 2,2 mét, cao 7,3 mét, đứng trên tám cột bê tông. Lối giữa rộng 4,3 mét với hai cánh cửa sắt, hai lối bên mỗi lối rộng 1,2 mét.\n\nDiềm mái lợp ngói trang trí hình chữ thọ và hình hổ phù. Đỉnh mái đắp họa tiết hoa lá hóa rồng với hình mặt nguyệt ở giữa, bên dưới là bộ tranh mai, lan, cúc, trúc đắp nổi. Chữ thọ cách điệu theo lối hồi văn được đắp tay bằng xi măng, sơn trắng, nổi bật trên nền đỏ. Theo các tác giả nghiên cứu, màu men đỏ đồng nhất có thể là chủ ý, để phân biệt với ngói lưu ly sặc sỡ của các công trình cung đình.","doc":11},{"loai":"trich","text":"Đến thời tôi làm hiệu trưởng, xét thấy cần chỉnh lý lại cổng chính cho phù hợp với vẻ uy nghi và rộng lớn của toàn bộ công trình, chính tôi đã vẽ kiểu và thuê thợ xây lại cổng như hiện nay.","nguoi":"Thầy giáo Nguyễn Đình Hàm, hiệu trưởng Trường Quốc Học 1956 – 1958","nguon_ten":"Dẫn theo Nguyễn Ngọc Tùng, Tôn Thất Hiếu Khoa, Hoàng Uyên Thư, Tạp chí Khoa học và Công nghệ, Trường Đại học Khoa học – Đại học Huế, tập 19, số 1, 2021","doc":12},{"loai":"anh","src":"textures/ht/ht_anh_quoc_hoc_hue.jpg","chu_thich":"Trường Quốc Học Huế bên bờ sông Hương, ảnh chụp năm 2008.","credit":"Ảnh: Lưu Ly · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày 31/12/2020, Thủ tướng Chính phủ ký Quyết định số 2280/QĐ-TTg, xếp hạng Hệ thống di tích lưu niệm Chủ tịch Hồ Chí Minh tại Thừa Thiên Huế là di tích quốc gia đặc biệt. Hệ thống gồm Nhà lưu niệm ở số 158 Mai Thúc Loan, Nhà lưu niệm và đình làng Dương Nỗ, cùng Địa điểm Trường Quốc Học ở số 12 Lê Lợi. Ngôi trường vẫn đang dạy học, từ năm 2009 mang tên Trường Trung học phổ thông chuyên Quốc Học. Trong sân trường có tượng người học trò Nguyễn Tất Thành (xem chuyên đề Tượng học trò Nguyễn Tất Thành ở Trường Quốc Học).\n\nVăn thư phúc đáp năm 1908 của hiệu trưởng Chouquet là một tư liệu được Bảo tàng Hồ Chí Minh Thừa Thiên Huế giới thiệu. Trong không gian 3D của gian trưng bày, cổng trường được dựng theo dáng hai tầng quen thuộc, với tấm biển 國學, như một hình ảnh gợi nhớ ngôi trường. Người xem nên nhớ rằng cánh cổng thật năm 1908 là cổng lầu kiểu An Nam, cột gỗ, mái ngói, với quả chuông đồng treo trên lầu.","doc":13},{"loai":"anh","src":"textures/bang_w/G02_8_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Cổng Trường Quốc Học”, nhìn từ trên cao."},{"loai":"ban_co_biet","text":"Chữ 國 trên biển cổng trường cũng có mặt trong cái tên Nguyễn Ái Quốc (阮愛國), nghĩa là “Nguyễn yêu nước”, mà người học trò Quốc Học năm xưa dùng từ năm 1919.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","doc":14}],"nguon":["Nguyễn Ngọc Tùng, Tôn Thất Hiếu Khoa, Hoàng Uyên Thư, “Vài nét về kiến trúc cổng trường Quốc Học Huế”, Tạp chí Khoa học và Công nghệ, Trường Đại học Khoa học – Đại học Huế, tập 19, số 1, 2021 – https://csdlkhoahoc.hueuni.edu.vn/data/2022/3/720_fulltext_9_Kien_truc_-_Tung_-_Nguyen_Ngoc_Tung.pdf","Bảo tàng Hồ Chí Minh, Hồ Chí Minh – Tiểu sử, NXB Chính trị quốc gia, 2008; bài “Thời niên thiếu của Chủ tịch Hồ Chí Minh (1890-1911)”, Tư liệu – Văn kiện Đảng – https://tulieuvankien.dangcongsan.vn/c-mac-angghen-lenin-ho-chi-minh/ho-chi-minh/tieu-su-cuoc-doi-va-su-nghiep/thoi-nien-thieu-cua-chu-tich-ho-chi-minh-1890-1911-3487","Cục Di sản văn hóa, “Hệ thống di tích lưu niệm Chủ tịch Hồ Chí Minh tại Thừa Thiên Huế” – https://dsvh.gov.vn/he-thong-di-tich-luu-niem-chu-tich-ho-chi-minh-tai-thua-thien-hue-3310","Báo Tuổi Trẻ, “Nguyễn Tất Thành ra đi từ ngôi trường xứ Huế”, 5/2/2018 – https://tuoitre.vn/nguyen-tat-thanh-ra-di-tu-ngoi-truong-xu-hue-20180205104555229.htm","Trần Dân Tiên, Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch, NXB Chính trị quốc gia","Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia"],"doc":[{"t":"Cổng Quốc Học: năm dáng hình của một cánh cổng, và người học trò bước qua năm 1908. Ai đến Huế cũng nhận ra Quốc Học từ xa nhờ cánh cổng hai tầng mái ngói đỏ bên đường Lê Lợi. Nhưng cánh cổng người học trò Nguyễn Sinh Côn bước qua năm 1908 không phải cánh cổng hôm nay. Hơn một thế kỷ, cổng trường đã mang ít nhất năm dáng hình, từng đề chữ Hán, chữ Pháp, rồi có lúc bị đục mất chữ. Lần theo cánh cổng ấy là lần theo lịch sử một ngôi trường và một người học trò."},{"t":"Lá thư hỏi về một cậu học trò. Ngày 4/8/1908, Khâm sứ Trung Kỳ Lévecque, người đứng đầu bộ máy bảo hộ Pháp ở Huế, gửi thư cho hiệu trưởng Trường Quốc Học. Ông hỏi về lai lịch một học trò vừa đỗ tiểu học, sắp được chuyển thẳng lên Quốc Học. Người học trò ấy tên là Nguyễn Sinh Côn, gốc Nghệ An. Chỉ ba ngày sau, ngày 7/8/1908, hiệu trưởng Chouquet gửi văn thư phúc đáp. Nguyễn Sinh Côn là tên gọi ở Huế của Nguyễn Tất Thành. Bốn tháng trước đó, anh vừa đi cùng đoàn nông dân biểu tình chống sưu thuế đến Tòa Khâm sứ, và từ đó bị mật thám Pháp để mắt tới. Hai văn bản trao đổi giữa Tòa Khâm sứ và nhà trường hiện nằm trong văn khố Pháp ở Aix-en-Provence, thuộc bộ hồ sơ mật thám lập về Nguyễn Ái Quốc. Chúng giúp làm rõ một chi tiết từng gây tranh luận. Nguyễn Tất Thành vào Quốc Học sau cuộc biểu tình, chứ không phải từ mùa thu năm 1907 như nhiều tài liệu cũ đã viết. Theo Tiểu sử do Bảo tàng Hồ Chí Minh biên soạn, tháng 9/1908 anh vào lớp trung đẳng, tức lớp nhì, của trường."},{"t":"Tôi hân hạnh báo cho ngài rõ sẽ có thể tiếp nhận vào Trường Quốc Học học sinh có tên Nguyễn Sinh Côn, gốc người Nghệ An, học sinh Trường Pháp - An Nam tỉnh Thừa Thiên. — Hiệu trưởng Trường Quốc Học Chouquet, văn thư phúc đáp Tòa Khâm sứ ngày 7/8/1908 (bản dịch)"},{"t":"Cánh cổng năm 1908 trông ra sao. Cánh cổng Nguyễn Tất Thành đi qua năm ấy khác xa cánh cổng du khách thấy hôm nay. Theo một nghiên cứu của Khoa Kiến trúc, Trường Đại học Khoa học, Đại học Huế, công bố năm 2021, cổng trường thời đầu mang kiểu kiến trúc An Nam. Hai dãy tường rộng chạy giáp vào một cổng có lầu, cột đỡ lầu bằng gỗ, mái lợp theo kiểu Tàu. Bên trong cổng có cầu thang xoắn ốc dẫn lên lầu, và trên lầu treo một quả chuông đồng. Ảnh chụp năm 1913 cho thấy tầng dưới xây gạch đặc, tầng lầu dựng trên cột gỗ, mái ngói có họa tiết trang trí truyền thống. Người vẽ kiểu và năm dựng cổng chưa được xác định chính xác, chỉ biết là trong những năm đầu của trường. Sau cánh cổng ấy chưa có những dãy nhà gạch kiểu Pháp. Các lớp học là những dãy nhà tranh vách đất, mái rạ lợp sơ sài nên mùa mưa thường bị dột. Các dãy nhà dựng đối xứng hai bên lối đi chính giữa: bên trái là phòng học, bên phải là nhà hiệu trưởng, phòng giáo viên và chỗ ở của học trò nội trú. Ông Lê Thanh Cảnh, một người bạn học của Nguyễn Tất Thành, về sau đặt tên cho hồi ký của mình là “Dưới mái tranh Trường Quốc Học những năm 1906 – 1911”."},{"t":"Ngôi trường dựng trên nền doanh trại thủy binh. Trường Quốc Học ra đời ngày 23/10/1896, theo chỉ dụ năm Thành Thái thứ tám và nghị định ngày 18/11/1896 của Toàn quyền Đông Dương Rousseau. Trường được dựng ở bờ nam sông Hương, trên nền Tả doanh Thủy sư, nơi huấn luyện binh lính đường thủy của quân đội nhà Nguyễn. Mặt tiền trông ra con đường người Pháp đặt tên Jules Ferry, nay là đường Lê Lợi. Vật liệu xây dựng thời ấy lấy từ những dãy nhà cũ của trại lính vệ bị phá dỡ. Gần hai mươi năm đầu, trường mang tên Pháp tự Quốc học đường, dạy tiếng Pháp, chữ quốc ngữ và chữ Nho ở bậc tiểu học. Năm 1897, trường xây thêm nhà hiệu trưởng ba gian hai chái. Năm 1899, học trò đông hơn, trường dựng thêm một dãy lớp tiểu học ba mươi gian và một dãy lớp bổ túc mười sáu gian. Trong những năm 1896 – 1902, hiệu trưởng là một người Pháp, còn ông Ngô Đình Khả giữ chức chưởng giáo. Tài liệu về trường kể rằng ông Khả cho sơn đỏ các bức tường. Sắc đỏ vì thế đã gắn với Quốc Học ngay từ thuở ban đầu."},{"t":"Bạn có biết? Cổng Quốc Học thời đầu có cầu thang xoắn ốc bên trong dẫn lên lầu, và trên lầu treo một quả chuông đồng. Một bức ảnh tư liệu của nhà trường vẫn còn ghi lại chiếc chuông treo trên cổng."},{"t":"Hai chữ 國學 và một nghịch lý. Hai chữ Hán 國學 đọc theo âm Hán Việt là “Quốc Học”. Chữ 國 nghĩa là nước, chữ 學 nghĩa là học, ghép lại có thể hiểu là nền học của nước nhà. Thế nhưng ngôi trường mang cái tên ấy lại lấy tiếng Pháp làm chính. Mục đích trước hết của chính quyền bảo hộ là đào tạo thông ngôn, thư ký, viên chức cho bộ máy cai trị. Cái tên hướng về nước nhà, còn chương trình học hướng về chính quốc. Nghịch lý ấy lại sinh ra những điều người lập trường không mong muốn. Tiểu sử chính thức của Chủ tịch Hồ Chí Minh ghi nhận, thời học ở Quốc Học, Nguyễn Tất Thành được tiếp xúc nhiều với sách báo Pháp. Trong số thầy giáo của trường có những người yêu nước như thầy Hoàng Thông, thầy Lê Văn Miến. Ảnh hưởng của các thầy và của sách báo tiến bộ làm lớn dần trong anh ý muốn sang phương Tây, tìm hiểu tình hình các nước và học hỏi thành tựu văn minh nhân loại. Cánh cổng mang tên “Quốc Học” vì thế đã mở ra cho người học trò một con đường khác hẳn con đường làm viên chức."},{"t":"Một câu hỏi trong giờ vẽ. Theo hồ sơ di tích do Cục Di sản văn hóa giới thiệu, Nguyễn Tất Thành nằm trong danh sách mười học sinh giỏi nhất của trường Pháp – Việt được chuyển thẳng vào Quốc Học, niên khóa 1908 – 1909. Nhà giáo Lê Thiện, bạn học thời tiểu học, kể với nhà nghiên cứu Nguyễn Đắc Xuân rằng anh Côn học giỏi nhưng không học gạo. Học môn gì anh cũng hỏi cặn kẽ. Hán văn anh giỏi nhất lớp, còn Pháp văn thì không trò xứ Nghệ nào bằng. Ở Quốc Học, thầy dạy vẽ là họa sĩ Lê Văn Miến. Theo lời kể của họa sĩ Tôn Thất Sa, cũng là thầy giáo Quốc Học, thầy Miến thường dành thời gian trong giờ vẽ để kể cho học trò nghe về nước Pháp. Trò Côn thích nghe thầy kể chuyện hơn là học vẽ, và có lần đã hỏi thầy làm sao để sang Pháp xem người Pháp sống ra sao. Đây là lời kể hồi ức do nhà nghiên cứu Nguyễn Đắc Xuân ghi lại. Nhưng nó khớp với điều sách của Trần Dân Tiên chép về Người trước lúc ra đi: muốn đi xem nước Pháp và các nước khác, xem họ làm thế nào, rồi trở về giúp đồng bào."},{"t":"Rời trường: bị đuổi hay tự ra đi. Nguyễn Tất Thành học ở Quốc Học chưa trọn một năm học. Về cách anh rời trường, các tài liệu không hoàn toàn thống nhất. Một số sách cho rằng anh bị đuổi học, vì thái độ không chịu khuất phục những thầy giáo Pháp coi thường học trò Việt, và vì các hoạt động khiến Tòa Khâm sứ lo ngại. Nhiều sách phổ thông lại gắn việc bị đuổi học với cuộc biểu tình chống thuế năm 1908. Các nhà nghiên cứu Nguyễn Đắc Xuân và Nguyễn Hồng Việt thì cho rằng anh không bị đuổi. Theo tư liệu họ dẫn, biết mình bị theo dõi, anh tự nghỉ học, ẩn ở Huế một thời gian, rồi theo cha vào Bình Định. Bảo tàng Hồ Chí Minh Thừa Thiên Huế đánh giá cách lý giải này là phù hợp. Tiểu sử chính thức ghi rằng khoảng tháng 6/1909, Nguyễn Tất Thành rời Trường Quốc Học theo cha vào Bình Định, khi ông Nguyễn Sinh Sắc được bổ làm Tri huyện Bình Khê. Dù rời trường theo cách nào, người học trò ấy không mang theo mảnh bằng Quốc Học nào. Thứ anh mang theo là tiếng Pháp, những trang sách đã đọc, và câu hỏi về con đường cứu nước."},{"t":"Năm dáng hình của một cánh cổng. Năm 1902, các lớp tiểu học của trường cháy rụi và được dựng lại theo mẫu cũ. Năm 1911, trường lại bị cháy. Từ tháng 5/1915, thầu khoán Le Roy cùng hàng trăm thợ tái thiết trường bằng gạch ngói theo kiểu Pháp, trên khu đất rộng hơn năm héc-ta. Cùng năm ấy, trường nâng lên bậc trung học, lấy tên Collège Quốc Học. Riêng cổng chính được xây bằng xi măng theo lối tam quan cổ truyền. Khoảng những năm 1933 – 1936, ông Boularand, tổng giám thị của trường, cho cải tạo cổng theo kiến trúc Nhật Bản và sơn màu đỏ. Hai cột cổng khắc đôi câu đối chữ Hán của Nguyễn Đức Đôn, dịch nghĩa là: “Vạn dặm xa thư về một mối, trăm năm sông núi thấy cao xanh”. Năm 1936, nhân kỷ niệm bốn mươi năm thành lập, trường đổi tên là Trung học Khải Định. Cổng được xây lại theo phong cách Việt với bốn trụ đắp nổi hoa sen, trên đề hàng chữ Hán “Khải Định trung học đường” và dòng chữ Pháp “Lycée Khải Định”. Ngày 26/12/1956, dịp kỷ niệm sáu mươi năm, trường trở lại với tên Quốc Học."},{"t":"Bạn có biết? Năm 1958, biển xi măng trước cổng đắp nổi ba chữ quốc ngữ “Trường Quốc Học”, hai bên chua thêm hai chữ Hán 國學. Năm 1979, có người cho rằng chữ Nho là “đồ ngoại” nên hai chữ Hán bị đục bỏ. Quốc Học cũng là trường học duy nhất ở thành phố Huế có cổng hai tầng."},{"t":"Cánh cổng hôm nay. Cánh cổng du khách thấy hôm nay được xây năm 1958. Thầy Nguyễn Đình Hàm, hiệu trưởng những năm 1956 – 1958, kể rằng chính ông vẽ kiểu và thuê thợ xây lại cổng. Nhóm nghiên cứu của Đại học Huế ghi nhận kiến trúc cổng do họa sĩ Tôn Thất Sa thiết kế. Đó cũng là người đã kể lại câu chuyện trò Côn hỏi thầy dạy vẽ về nước Pháp. Cổng theo lối tam quan, bên trên có vọng lâu, hai tầng mái lợp ngói âm dương tráng men đỏ màu gạch cua. Cổng rộng 9,1 mét, sâu 2,2 mét, cao 7,3 mét, đứng trên tám cột bê tông. Lối giữa rộng 4,3 mét với hai cánh cửa sắt, hai lối bên mỗi lối rộng 1,2 mét. Diềm mái lợp ngói trang trí hình chữ thọ và hình hổ phù. Đỉnh mái đắp họa tiết hoa lá hóa rồng với hình mặt nguyệt ở giữa, bên dưới là bộ tranh mai, lan, cúc, trúc đắp nổi. Chữ thọ cách điệu theo lối hồi văn được đắp tay bằng xi măng, sơn trắng, nổi bật trên nền đỏ. Theo các tác giả nghiên cứu, màu men đỏ đồng nhất có thể là chủ ý, để phân biệt với ngói lưu ly sặc sỡ của các công trình cung đình."},{"t":"Đến thời tôi làm hiệu trưởng, xét thấy cần chỉnh lý lại cổng chính cho phù hợp với vẻ uy nghi và rộng lớn của toàn bộ công trình, chính tôi đã vẽ kiểu và thuê thợ xây lại cổng như hiện nay. — Thầy giáo Nguyễn Đình Hàm, hiệu trưởng Trường Quốc Học 1956 – 1958"},{"t":"Dấu tích hôm nay. Ngày 31/12/2020, Thủ tướng Chính phủ ký Quyết định số 2280/QĐ-TTg, xếp hạng Hệ thống di tích lưu niệm Chủ tịch Hồ Chí Minh tại Thừa Thiên Huế là di tích quốc gia đặc biệt. Hệ thống gồm Nhà lưu niệm ở số 158 Mai Thúc Loan, Nhà lưu niệm và đình làng Dương Nỗ, cùng Địa điểm Trường Quốc Học ở số 12 Lê Lợi. Ngôi trường vẫn đang dạy học, từ năm 2009 mang tên Trường Trung học phổ thông chuyên Quốc Học. Trong sân trường có tượng người học trò Nguyễn Tất Thành (xem chuyên đề Tượng học trò Nguyễn Tất Thành ở Trường Quốc Học). Văn thư phúc đáp năm 1908 của hiệu trưởng Chouquet là một tư liệu được Bảo tàng Hồ Chí Minh Thừa Thiên Huế giới thiệu. Trong không gian 3D của gian trưng bày, cổng trường được dựng theo dáng hai tầng quen thuộc, với tấm biển 國學, như một hình ảnh gợi nhớ ngôi trường. Người xem nên nhớ rằng cánh cổng thật năm 1908 là cổng lầu kiểu An Nam, cột gỗ, mái ngói, với quả chuông đồng treo trên lầu."},{"t":"Bạn có biết? Chữ 國 trên biển cổng trường cũng có mặt trong cái tên Nguyễn Ái Quốc (阮愛國), nghĩa là “Nguyễn yêu nước”, mà người học trò Quốc Học năm xưa dùng từ năm 1919."}],"so_chu":2178},{"i":9,"tieu_de_bang":"Phong trào chống sưu thuế 1908","tieu_de":"Mùa xuân 1908: những người “đồng bào cắt tóc” kéo về kinh đô","sapo":"Họ đi tay không, tóc cắt ngắn, gọi nhau là “đồng bào”. Mùa xuân năm 1908, nông dân Trung Kỳ từ Quảng Nam đến Thừa Thiên lần lượt kéo đến các tòa sứ đòi giảm sưu, giảm thuế. Một bản báo cáo mật của viên Công sứ Pháp ở Huế, mới được dịch và công bố, cho phép dựng lại từng ngày biến động ở kinh đô. Trong đám đông ấy có một học trò mười tám tuổi tên Nguyễn Tất Thành.","bia":{"src":"textures/bai/G02_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Những người gọi nhau là đồng bào","text":"Cuốn “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch” của Trần Dân Tiên ghi lại một hình ảnh khó quên. Nông dân các tỉnh Trung Bộ nổi dậy chống thuế mà không có khí giới, chỉ yêu cầu giảm thuế. Họ cắt tóc ngắn để tỏ tình đoàn kết và gọi nhau bằng hai tiếng “đồng bào”. Người Pháp vì thế gọi phong trào là “án đồng bào cắt tóc”. Sách của Trần Dân Tiên ghi sự kiện vào năm 1907, còn tài liệu lưu trữ cho thấy các cuộc biểu tình lớn nổ ra vào mùa xuân năm 1908.\n\nMái tóc ngắn không phải chuyện ngẫu nhiên. Mấy năm trước đó, phong trào Duy Tân do các nhà nho yêu nước như Phan Châu Trinh, Huỳnh Thúc Kháng, Trần Quý Cáp khởi xướng đã lan rộng ở Quảng Nam và nhiều tỉnh Trung Kỳ. Họ vận động mở trường, diễn thuyết, cắt tóc ngắn, mặc áo ngắn. Cắt bỏ búi tóc dài là dấu hiệu từ bỏ lối cũ để theo cái mới. Khi phong trào chống thuế bùng lên, mái tóc ngắn trở thành dấu hiệu nhận ra nhau của những người cùng xuống đường.","doc":1},{"loai":"trich","text":"Họ đi tay không, không có khí giới. Họ chỉ yêu cầu giảm thuế. Để tỏ tình đoàn kết nhất trí, họ đều cắt tóc ngắn và gọi nhau là “đồng bào”.","nguoi":"Trần Dân Tiên","nguon_ten":"Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch","doc":2},{"loai":"doan","tieu_de":"Gánh sưu, gánh thuế","text":"Sưu là những ngày lao dịch không công mà người dân phải đi làm cho nhà nước, như làm đường, đắp đê. Thuế thân đánh vào những người đàn ông có tên trong sổ đinh của làng, bên cạnh thuế ruộng đất. Yêu sách mà nông dân Thừa Thiên trình lên năm 1908 cho thấy gánh nặng đè lên họ ở đâu. Họ đòi xóa bỏ lao dịch, giảm thuế thân xuống còn 1 đồng 20 xu mỗi suất đinh, xếp toàn bộ ruộng lúa vào hạng tư. Họ xin được nộp thuế làm hai kỳ, và đòi bãi chức các quan lại trong tỉnh.\n\nChính viên Công sứ Thừa Thiên, người chỉ huy việc đàn áp, cũng phải thừa nhận nhiều bất công. Trong báo cáo gửi Khâm sứ Trung Kỳ, ông viết rằng thuế thân được phân bổ không công bằng. Các kỳ mục trong làng tự miễn cho mình rồi bắt những người nghèo nhất gánh thay. Ruộng đất của người nghèo lại chịu mức thuế cao nhất. Ông còn kể hai nguyên nhân khác khiến dân bất bình: cách quản lý muối làm giá muối tăng, và quy định buộc các làng phải lập trường học, tự trả lương thầy giáo.","doc":3},{"loai":"anh","src":"textures/bang_w/G02_9_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Phong trào chống sưu thuế 1908”, nhìn từ xa."},{"loai":"doan","tieu_de":"Từ Hội An đến kinh đô","text":"Ngày 11/3/1908, nông dân Quảng Nam kéo về tỉnh lỵ Hội An đòi giảm lao dịch và thuế. Phong trào nối tiếp ở Quảng Ngãi, rồi lan ra Bình Định, Phú Yên, Thừa Thiên và nhiều tỉnh Trung Kỳ khác. Báo cáo của Công sứ Thừa Thiên cho biết, trước khi dân Huế kéo vào thành phố, những cuộc biểu tình tương tự đã diễn ra ở Quảng Nam và Quảng Ngãi.\n\nViên Công sứ tin rằng phong trào có tổ chức. Theo ông, ở Thừa Thiên đã hình thành nhiều hội kín núp dưới danh nghĩa hội buôn. Hội đầu tiên lập đầu năm 1907 ở Bao Vinh, thường xuyên liên hệ với một hội tương tự ở Hội An. Sau đó có thêm hội ở Truồi thuộc huyện Phú Lộc, ở chợ Niêm Phổ thuộc huyện Quảng Điền và một số làng khác. Hội viên đi quyên tiền, truyền các bản kêu gọi dân chúng học tập và làm giàu theo gương người Nhật, để thoát khỏi vòng bảo hộ. Dù chưa có một tổ chức thống nhất, phong trào đã có những sợi dây nối các tỉnh với nhau.","doc":4},{"loai":"ban_co_biet","text":"Theo báo cáo của Công sứ Thừa Thiên, người đứng đầu hội kín ở Bao Vinh là một quan tứ phẩm, đang dạy ở Trường Pháp – Việt và từng là học sinh Quốc Học. Ông bị bắt trong đợt truy lùng năm 1908.","nguon_ten":"Thanh Biên (Trung tâm Lưu trữ quốc gia IV), “Phong trào chống thuế tại Huế năm 1908 qua báo cáo của người Pháp”, bản dịch báo cáo của Công sứ Thừa Thiên, hồ sơ 2554 RSA; mocban.vn, 11/12/2025","doc":5},{"loai":"doan","tieu_de":"Bảy ngày ở kinh đô: từ làng ra phố","text":"Báo cáo của viên Công sứ kể lại gần như từng ngày. Sáng 9/4/1908, ông nhận tin nông dân nhiều làng phía nam tỉnh đang tụ tập ở các tổng An Cựu, Cư Chánh thuộc huyện Hương Thủy và tổng Dương Nỗ thuộc huyện Phú Vang. Một số nhóm nhỏ hơn tụ tập ở An Hòa, phía bắc Kinh thành.\n\nTối 10/4, người biểu tình đã kéo đến sát thành phố. Viên Phủ doãn Thừa Thiên đi thuyền tam bản đến làng Công Lương để khuyên dân giải tán thì bị ném đá. Một người dân lao xuống nước định làm chìm thuyền, liền bị một viên chỉ huy lính đi theo bắn. Dân làng bắt giữ viên Phủ doãn cùng binh lính, trói lại trước làng. Khoảng 10 giờ sáng 11/4, vài trăm người giải viên Phủ doãn đến trước Tòa Khâm sứ. Viên Công sứ ra nói chuyện hơn một giờ, khuyên dân về làng. Người biểu tình đáp rằng họ sẽ không rời đi nếu yêu sách chưa được chấp thuận. Bốn giờ chiều, khoảng một nghìn người lại vây quanh Tòa Khâm sứ, đòi giảm thuế và bãi chức các quan tỉnh.","doc":6},{"loai":"doan","tieu_de":"Bảy ngày ở kinh đô: trên cầu, ngoài chợ","text":"Rạng sáng 12/4, khoảng một trăm lính thủy quân lục chiến kéo đến Công Lương, bắt 34 người biểu tình. Cùng ngày, người từ An Cựu kéo vào thành phố, đứng thành từng nhóm năm mươi đến một trăm người, chiếm cả đại lộ dẫn ra ga xe lửa.\n\nSáng 13/4, các nhóm biểu tình tụ tập trên cầu Thành Thái, tức cầu Trường Tiền ngày nay, và trên đại lộ ra ga. Chiều tối, một nhóm khoảng một trăm người tấn công đồn cảnh sát ở chợ, rồi bị lính giải tán. Nửa đêm, Hội đồng Phụ chính của triều đình ra thông báo: ai còn quay lại sẽ bị trấn áp không khoan nhượng. Chiều 14/4, binh lính giải tán đám đông trước dinh các quan tỉnh, hai người bị đánh bằng báng súng. Ngày 15/4, người biểu tình rút về Phú Bài, cách thành phố mười lăm cây số, rồi trở về làng. Viên Công sứ ghi rằng nông dân đã bỏ dở mùa gặt khoảng tám ngày.","doc":7},{"loai":"anh","src":"textures/bang_w/G02_9_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Phong trào chống sưu thuế 1908”, nhìn theo hướng ngược lại."},{"loai":"ban_co_biet","text":"Nhiều bài viết ghi cuộc biểu tình ở Huế diễn ra vào tháng 5/1908, còn sách của Trần Dân Tiên ghi năm 1907. Báo cáo của Công sứ Thừa Thiên ghi rõ các ngày từ 9 đến 15/4/1908, khớp với Tiểu sử Chủ tịch Hồ Chí Minh do Bảo tàng Hồ Chí Minh biên soạn.","nguon_ten":"Thanh Biên (Trung tâm Lưu trữ quốc gia IV), “Phong trào chống thuế tại Huế năm 1908 qua báo cáo của người Pháp”, bản dịch báo cáo của Công sứ Thừa Thiên, hồ sơ 2554 RSA; mocban.vn, 11/12/2025; Bảo tàng Hồ Chí Minh, Hồ Chí Minh – Tiểu sử, 2008","doc":8},{"loai":"doan","tieu_de":"Người học trò trong đám đông","text":"Những ngày ấy, Nguyễn Tất Thành đang học Trường tiểu học Pháp – Việt tỉnh Thừa Thiên, sát ngoài cửa Đông Ba. Anh đã đi cùng đoàn nông dân đến Tòa Khâm sứ và làm phiên dịch cho bà con (xem chuyên đề Người phiên dịch cho đoàn nông dân). Các nhà nghiên cứu ở Huế xác định đó là buổi sáng 11/4/1908. Bảo tàng Hồ Chí Minh Thừa Thiên Huế lưu ý rằng khi ấy anh còn là học trò trường tiểu học Pháp – Việt, chưa phải học trò Quốc Học như nhiều tài liệu đã viết.\n\nHậu quả đến ngay sau đó. Tiểu sử chính thức ghi rằng anh bị thực dân Pháp để ý theo dõi, còn ông Nguyễn Sinh Sắc bị khiển trách vì đã để con trai có những hoạt động bài Pháp. Tháng 8/1908, Khâm sứ Trung Kỳ gửi thư hỏi hiệu trưởng Quốc Học về lai lịch người học trò tên Nguyễn Sinh Côn (xem chuyên đề Cổng Trường Quốc Học). Với người thanh niên mười tám tuổi, đó là lần đầu tiên anh đứng hẳn về phía người nông dân, đối mặt với bộ máy cai trị.","doc":9},{"loai":"trich","text":"Tháng 4-1908, anh tham gia cuộc biểu tình chống thuế của nông dân tỉnh Thừa Thiên, khởi đầu cho cuộc tranh đấu suốt đời Người vì quyền lợi của nhân dân lao động.","nguoi":"Tiểu sử Chủ tịch Hồ Chí Minh, Bảo tàng Hồ Chí Minh biên soạn","nguon_ten":"Hồ Chí Minh – Tiểu sử, NXB Chính trị quốc gia, 2008; đăng trên tulieuvankien.dangcongsan.vn","doc":10},{"loai":"anh","src":"textures/ht/ht_anh_tuong_nguyen_tat_thanh_tai_quoc_hoc_hue.jpg","chu_thich":"Tượng người học trò Nguyễn Tất Thành trong sân Trường Quốc Học Huế, ảnh chụp năm 2008.","credit":"Ảnh: Lưu Ly at Vietnamese Wikipedia · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Đòn trừng phạt nhắm vào các nhà nho","text":"Viên Công sứ đề nghị cấp trên cứng rắn với những người cầm đầu, còn với dân chúng thì khoan dung. Riêng ở Thừa Thiên, ngoài 34 người bị bắt ở Công Lương còn có 30 người bị bắt sau vụ tấn công đồn cảnh sát. Hai người trong số đó bị kết án tử hình nhưng được hoãn thi hành. Nhiều người bị coi là thủ lĩnh bị bắt trước và sau biến động, trong đó có cựu quan lại, thầy giáo, hội viên các hội kín. Ba thủ lĩnh chính ở Thừa Thiên vẫn được dân che giấu, chưa bị bắt.\n\nTrên toàn Trung Kỳ, chính quyền thực dân quy trách nhiệm cho các nhà nho Duy Tân. Trần Quý Cáp bị kết án tử hình, xử chém ngang lưng ở Khánh Hòa. Phan Châu Trinh bị kết án tử hình rồi được giảm án, bị đày ra Côn Đảo. Sách của Trần Dân Tiên cho biết cụ được Hội Nhân quyền Pa-ri can thiệp cứu. Huỳnh Thúc Kháng cũng bị đày ra Côn Đảo. Không có vũ khí, không có một bộ chỉ huy chung, phong trào bị dập tắt ngay trong năm 1908.","doc":11},{"loai":"ban_co_biet","text":"Tổng Dương Nỗ, một trong những nơi nông dân tụ tập sáng 9/4/1908, là vùng có làng Dương Nỗ, nơi năm 1898 ông Nguyễn Sinh Sắc dạy học. Nhà lưu niệm thời niên thiếu của Chủ tịch Hồ Chí Minh ở Dương Nỗ nay là một điểm của di tích quốc gia đặc biệt.","nguon_ten":"Thanh Biên (Trung tâm Lưu trữ quốc gia IV), “Phong trào chống thuế tại Huế năm 1908 qua báo cáo của người Pháp”, bản dịch báo cáo của Công sứ Thừa Thiên, hồ sơ 2554 RSA; mocban.vn, 11/12/2025; Cục Di sản văn hóa – Hệ thống di tích lưu niệm Chủ tịch Hồ Chí Minh tại Thừa Thiên Huế","doc":12},{"loai":"doan","tieu_de":"Trong mắt người cai trị","text":"Phần kết của bản báo cáo cho thấy người Pháp lo ngại điều gì. Viên Công sứ viết rằng, theo ý ông, đây là một sự chuyển biến trong tư tưởng của người An Nam. Việc những người cầm đầu liên kết với nhau, trong một tỉnh và giữa các tỉnh, là hiện tượng mới mà trước đó ông chưa nhận thấy. Ông cũng nhận ra uy tín của quan lại đang sa sút: một viên Phủ doãn bị dân trói, còn lời một vị Tham tri trong triều thì bị phớt lờ. Theo ông, những tư tưởng mới đang manh nha tìm đường, lấy cảm hứng từ sự chuyển mình của Nhật Bản.\n\nDù thừa nhận thuế thân phân bổ bất công, viên Công sứ vẫn cho rằng yêu cầu giảm thuế hiện tại không thể xem xét. Ông e rằng cải cách vội vã sẽ làm lung lay làng xã và khiến tầng lớp quan lại xa lánh chính quyền bảo hộ. Những yêu sách chính đáng của người nông dân vì thế bị gác lại, còn câu trả lời họ nhận được là roi mây, báng súng và nhà tù.","doc":13},{"loai":"anh","src":"textures/bang_w/G02_9_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Phong trào chống sưu thuế 1908”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Bài học đầu đời và dấu tích hôm nay","text":"Phong trào chống thuế năm 1908 cho thấy sức mạnh của người nông dân khi đồng loạt đứng lên, nhưng cũng bộc lộ giới hạn của những cuộc đấu tranh tự phát, thiếu tổ chức chặt chẽ và thiếu đường lối rõ ràng. Với Nguyễn Tất Thành, đó là bài học đầu tiên về đấu tranh của quần chúng. Anh chứng kiến những yêu sách chính đáng bị đáp lại bằng roi vọt, và biết tin những sĩ phu mà anh khâm phục như Phan Châu Trinh bị tù đày. Ba năm sau, ngày 5/6/1911, người thanh niên ấy rời Bến Nhà Rồng ra đi tìm đường cứu nước.\n\nBản báo cáo mật năm 1908 hiện nằm trong hồ sơ số 2554 thuộc phông Tòa Khâm sứ Trung Kỳ, lưu tại Trung tâm Lưu trữ quốc gia IV ở Đà Lạt. Tài liệu được tác giả Thanh Biên dịch toàn văn, giới thiệu trên tạp chí Nghiên cứu lịch sử xứ Quảng và trang thông tin của Trung tâm ngày 11/12/2025. Người đến Huế hôm nay vẫn có thể lần theo dấu những ngày ấy. Cây cầu nơi người biểu tình tụ tập vẫn bắc qua sông Hương (xem chuyên đề Cầu Trường Tiền và sông Hương), còn làng Dương Nỗ vẫn giữ ngôi nhà lưu niệm.","doc":14},{"loai":"moc","items":[["11/3/1908","Nông dân Quảng Nam kéo về tỉnh lỵ Hội An đòi giảm lao dịch và thuế"],["9/4/1908","Nông dân phía nam Thừa Thiên tụ tập ở An Cựu, Cư Chánh, Dương Nỗ"],["10/4/1908","Dân làng Công Lương bắt giữ viên Phủ doãn Thừa Thiên"],["11/4/1908","Khoảng một nghìn người vây Tòa Khâm sứ; Nguyễn Tất Thành làm phiên dịch cho nông dân"],["12/4/1908","Lính thủy quân lục chiến bắt 34 người ở Công Lương"],["13/4/1908","Người biểu tình tụ tập trên cầu Thành Thái; đồn cảnh sát ở chợ bị tấn công"],["15/4/1908","Người biểu tình rút về Phú Bài rồi trở về làng"]],"doc":15}],"nguon":["Thanh Biên (Trung tâm Lưu trữ quốc gia IV), “Phong trào chống thuế tại Huế năm 1908 qua báo cáo của người Pháp”, bản dịch báo cáo của Công sứ Thừa Thiên, hồ sơ 2554 RSA; mocban.vn, 11/12/2025 – https://mocban.vn/phong-trao-chong-thue-tai-hue-nam-1908-qua-bao-cao-cua-nguoi-phap/","Trần Dân Tiên, Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch, NXB Chính trị quốc gia","Bảo tàng Hồ Chí Minh, Hồ Chí Minh – Tiểu sử, NXB Chính trị quốc gia, 2008; bài “Thời niên thiếu của Chủ tịch Hồ Chí Minh (1890-1911)” – https://tulieuvankien.dangcongsan.vn/c-mac-angghen-lenin-ho-chi-minh/ho-chi-minh/tieu-su-cuoc-doi-va-su-nghiep/thoi-nien-thieu-cua-chu-tich-ho-chi-minh-1890-1911-3487","Hà Văn Thịnh, “Nguyễn Tất Thành với Huế và phong trào chống thuế năm 1908”, Tạp chí Sông Hương, số 228, 2008 – http://tapchisonghuong.com.vn/tap-chi/c107/n804/Nguyen-Tat-Thanh-voi-Hue-va-phong-trao-chong-thue-nam-1908.html","Báo Tuổi Trẻ, “Nguyễn Tất Thành ra đi từ ngôi trường xứ Huế”, 5/2/2018 – https://tuoitre.vn/nguyen-tat-thanh-ra-di-tu-ngoi-truong-xu-hue-20180205104555229.htm","Viện Sử học – Lịch sử Việt Nam"],"doc":[{"t":"Mùa xuân 1908: những người “đồng bào cắt tóc” kéo về kinh đô. Họ đi tay không, tóc cắt ngắn, gọi nhau là “đồng bào”. Mùa xuân năm 1908, nông dân Trung Kỳ từ Quảng Nam đến Thừa Thiên lần lượt kéo đến các tòa sứ đòi giảm sưu, giảm thuế. Một bản báo cáo mật của viên Công sứ Pháp ở Huế, mới được dịch và công bố, cho phép dựng lại từng ngày biến động ở kinh đô. Trong đám đông ấy có một học trò mười tám tuổi tên Nguyễn Tất Thành."},{"t":"Những người gọi nhau là đồng bào. Cuốn “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch” của Trần Dân Tiên ghi lại một hình ảnh khó quên. Nông dân các tỉnh Trung Bộ nổi dậy chống thuế mà không có khí giới, chỉ yêu cầu giảm thuế. Họ cắt tóc ngắn để tỏ tình đoàn kết và gọi nhau bằng hai tiếng “đồng bào”. Người Pháp vì thế gọi phong trào là “án đồng bào cắt tóc”. Sách của Trần Dân Tiên ghi sự kiện vào năm 1907, còn tài liệu lưu trữ cho thấy các cuộc biểu tình lớn nổ ra vào mùa xuân năm 1908. Mái tóc ngắn không phải chuyện ngẫu nhiên. Mấy năm trước đó, phong trào Duy Tân do các nhà nho yêu nước như Phan Châu Trinh, Huỳnh Thúc Kháng, Trần Quý Cáp khởi xướng đã lan rộng ở Quảng Nam và nhiều tỉnh Trung Kỳ. Họ vận động mở trường, diễn thuyết, cắt tóc ngắn, mặc áo ngắn. Cắt bỏ búi tóc dài là dấu hiệu từ bỏ lối cũ để theo cái mới. Khi phong trào chống thuế bùng lên, mái tóc ngắn trở thành dấu hiệu nhận ra nhau của những người cùng xuống đường."},{"t":"Họ đi tay không, không có khí giới. Họ chỉ yêu cầu giảm thuế. Để tỏ tình đoàn kết nhất trí, họ đều cắt tóc ngắn và gọi nhau là “đồng bào”. — Trần Dân Tiên"},{"t":"Gánh sưu, gánh thuế. Sưu là những ngày lao dịch không công mà người dân phải đi làm cho nhà nước, như làm đường, đắp đê. Thuế thân đánh vào những người đàn ông có tên trong sổ đinh của làng, bên cạnh thuế ruộng đất. Yêu sách mà nông dân Thừa Thiên trình lên năm 1908 cho thấy gánh nặng đè lên họ ở đâu. Họ đòi xóa bỏ lao dịch, giảm thuế thân xuống còn 1 đồng 20 xu mỗi suất đinh, xếp toàn bộ ruộng lúa vào hạng tư. Họ xin được nộp thuế làm hai kỳ, và đòi bãi chức các quan lại trong tỉnh. Chính viên Công sứ Thừa Thiên, người chỉ huy việc đàn áp, cũng phải thừa nhận nhiều bất công. Trong báo cáo gửi Khâm sứ Trung Kỳ, ông viết rằng thuế thân được phân bổ không công bằng. Các kỳ mục trong làng tự miễn cho mình rồi bắt những người nghèo nhất gánh thay. Ruộng đất của người nghèo lại chịu mức thuế cao nhất. Ông còn kể hai nguyên nhân khác khiến dân bất bình: cách quản lý muối làm giá muối tăng, và quy định buộc các làng phải lập trường học, tự trả lương thầy giáo."},{"t":"Từ Hội An đến kinh đô. Ngày 11/3/1908, nông dân Quảng Nam kéo về tỉnh lỵ Hội An đòi giảm lao dịch và thuế. Phong trào nối tiếp ở Quảng Ngãi, rồi lan ra Bình Định, Phú Yên, Thừa Thiên và nhiều tỉnh Trung Kỳ khác. Báo cáo của Công sứ Thừa Thiên cho biết, trước khi dân Huế kéo vào thành phố, những cuộc biểu tình tương tự đã diễn ra ở Quảng Nam và Quảng Ngãi. Viên Công sứ tin rằng phong trào có tổ chức. Theo ông, ở Thừa Thiên đã hình thành nhiều hội kín núp dưới danh nghĩa hội buôn. Hội đầu tiên lập đầu năm 1907 ở Bao Vinh, thường xuyên liên hệ với một hội tương tự ở Hội An. Sau đó có thêm hội ở Truồi thuộc huyện Phú Lộc, ở chợ Niêm Phổ thuộc huyện Quảng Điền và một số làng khác. Hội viên đi quyên tiền, truyền các bản kêu gọi dân chúng học tập và làm giàu theo gương người Nhật, để thoát khỏi vòng bảo hộ. Dù chưa có một tổ chức thống nhất, phong trào đã có những sợi dây nối các tỉnh với nhau."},{"t":"Bạn có biết? Theo báo cáo của Công sứ Thừa Thiên, người đứng đầu hội kín ở Bao Vinh là một quan tứ phẩm, đang dạy ở Trường Pháp – Việt và từng là học sinh Quốc Học. Ông bị bắt trong đợt truy lùng năm 1908."},{"t":"Bảy ngày ở kinh đô: từ làng ra phố. Báo cáo của viên Công sứ kể lại gần như từng ngày. Sáng 9/4/1908, ông nhận tin nông dân nhiều làng phía nam tỉnh đang tụ tập ở các tổng An Cựu, Cư Chánh thuộc huyện Hương Thủy và tổng Dương Nỗ thuộc huyện Phú Vang. Một số nhóm nhỏ hơn tụ tập ở An Hòa, phía bắc Kinh thành. Tối 10/4, người biểu tình đã kéo đến sát thành phố. Viên Phủ doãn Thừa Thiên đi thuyền tam bản đến làng Công Lương để khuyên dân giải tán thì bị ném đá. Một người dân lao xuống nước định làm chìm thuyền, liền bị một viên chỉ huy lính đi theo bắn. Dân làng bắt giữ viên Phủ doãn cùng binh lính, trói lại trước làng. Khoảng 10 giờ sáng 11/4, vài trăm người giải viên Phủ doãn đến trước Tòa Khâm sứ. Viên Công sứ ra nói chuyện hơn một giờ, khuyên dân về làng. Người biểu tình đáp rằng họ sẽ không rời đi nếu yêu sách chưa được chấp thuận. Bốn giờ chiều, khoảng một nghìn người lại vây quanh Tòa Khâm sứ, đòi giảm thuế và bãi chức các quan tỉnh."},{"t":"Bảy ngày ở kinh đô: trên cầu, ngoài chợ. Rạng sáng 12/4, khoảng một trăm lính thủy quân lục chiến kéo đến Công Lương, bắt 34 người biểu tình. Cùng ngày, người từ An Cựu kéo vào thành phố, đứng thành từng nhóm năm mươi đến một trăm người, chiếm cả đại lộ dẫn ra ga xe lửa. Sáng 13/4, các nhóm biểu tình tụ tập trên cầu Thành Thái, tức cầu Trường Tiền ngày nay, và trên đại lộ ra ga. Chiều tối, một nhóm khoảng một trăm người tấn công đồn cảnh sát ở chợ, rồi bị lính giải tán. Nửa đêm, Hội đồng Phụ chính của triều đình ra thông báo: ai còn quay lại sẽ bị trấn áp không khoan nhượng. Chiều 14/4, binh lính giải tán đám đông trước dinh các quan tỉnh, hai người bị đánh bằng báng súng. Ngày 15/4, người biểu tình rút về Phú Bài, cách thành phố mười lăm cây số, rồi trở về làng. Viên Công sứ ghi rằng nông dân đã bỏ dở mùa gặt khoảng tám ngày."},{"t":"Bạn có biết? Nhiều bài viết ghi cuộc biểu tình ở Huế diễn ra vào tháng 5/1908, còn sách của Trần Dân Tiên ghi năm 1907. Báo cáo của Công sứ Thừa Thiên ghi rõ các ngày từ 9 đến 15/4/1908, khớp với Tiểu sử Chủ tịch Hồ Chí Minh do Bảo tàng Hồ Chí Minh biên soạn."},{"t":"Người học trò trong đám đông. Những ngày ấy, Nguyễn Tất Thành đang học Trường tiểu học Pháp – Việt tỉnh Thừa Thiên, sát ngoài cửa Đông Ba. Anh đã đi cùng đoàn nông dân đến Tòa Khâm sứ và làm phiên dịch cho bà con (xem chuyên đề Người phiên dịch cho đoàn nông dân). Các nhà nghiên cứu ở Huế xác định đó là buổi sáng 11/4/1908. Bảo tàng Hồ Chí Minh Thừa Thiên Huế lưu ý rằng khi ấy anh còn là học trò trường tiểu học Pháp – Việt, chưa phải học trò Quốc Học như nhiều tài liệu đã viết. Hậu quả đến ngay sau đó. Tiểu sử chính thức ghi rằng anh bị thực dân Pháp để ý theo dõi, còn ông Nguyễn Sinh Sắc bị khiển trách vì đã để con trai có những hoạt động bài Pháp. Tháng 8/1908, Khâm sứ Trung Kỳ gửi thư hỏi hiệu trưởng Quốc Học về lai lịch người học trò tên Nguyễn Sinh Côn (xem chuyên đề Cổng Trường Quốc Học). Với người thanh niên mười tám tuổi, đó là lần đầu tiên anh đứng hẳn về phía người nông dân, đối mặt với bộ máy cai trị."},{"t":"Tháng 4-1908, anh tham gia cuộc biểu tình chống thuế của nông dân tỉnh Thừa Thiên, khởi đầu cho cuộc tranh đấu suốt đời Người vì quyền lợi của nhân dân lao động. — Tiểu sử Chủ tịch Hồ Chí Minh, Bảo tàng Hồ Chí Minh biên soạn"},{"t":"Đòn trừng phạt nhắm vào các nhà nho. Viên Công sứ đề nghị cấp trên cứng rắn với những người cầm đầu, còn với dân chúng thì khoan dung. Riêng ở Thừa Thiên, ngoài 34 người bị bắt ở Công Lương còn có 30 người bị bắt sau vụ tấn công đồn cảnh sát. Hai người trong số đó bị kết án tử hình nhưng được hoãn thi hành. Nhiều người bị coi là thủ lĩnh bị bắt trước và sau biến động, trong đó có cựu quan lại, thầy giáo, hội viên các hội kín. Ba thủ lĩnh chính ở Thừa Thiên vẫn được dân che giấu, chưa bị bắt. Trên toàn Trung Kỳ, chính quyền thực dân quy trách nhiệm cho các nhà nho Duy Tân. Trần Quý Cáp bị kết án tử hình, xử chém ngang lưng ở Khánh Hòa. Phan Châu Trinh bị kết án tử hình rồi được giảm án, bị đày ra Côn Đảo. Sách của Trần Dân Tiên cho biết cụ được Hội Nhân quyền Pa-ri can thiệp cứu. Huỳnh Thúc Kháng cũng bị đày ra Côn Đảo. Không có vũ khí, không có một bộ chỉ huy chung, phong trào bị dập tắt ngay trong năm 1908."},{"t":"Bạn có biết? Tổng Dương Nỗ, một trong những nơi nông dân tụ tập sáng 9/4/1908, là vùng có làng Dương Nỗ, nơi năm 1898 ông Nguyễn Sinh Sắc dạy học. Nhà lưu niệm thời niên thiếu của Chủ tịch Hồ Chí Minh ở Dương Nỗ nay là một điểm của di tích quốc gia đặc biệt."},{"t":"Trong mắt người cai trị. Phần kết của bản báo cáo cho thấy người Pháp lo ngại điều gì. Viên Công sứ viết rằng, theo ý ông, đây là một sự chuyển biến trong tư tưởng của người An Nam. Việc những người cầm đầu liên kết với nhau, trong một tỉnh và giữa các tỉnh, là hiện tượng mới mà trước đó ông chưa nhận thấy. Ông cũng nhận ra uy tín của quan lại đang sa sút: một viên Phủ doãn bị dân trói, còn lời một vị Tham tri trong triều thì bị phớt lờ. Theo ông, những tư tưởng mới đang manh nha tìm đường, lấy cảm hứng từ sự chuyển mình của Nhật Bản. Dù thừa nhận thuế thân phân bổ bất công, viên Công sứ vẫn cho rằng yêu cầu giảm thuế hiện tại không thể xem xét. Ông e rằng cải cách vội vã sẽ làm lung lay làng xã và khiến tầng lớp quan lại xa lánh chính quyền bảo hộ. Những yêu sách chính đáng của người nông dân vì thế bị gác lại, còn câu trả lời họ nhận được là roi mây, báng súng và nhà tù."},{"t":"Bài học đầu đời và dấu tích hôm nay. Phong trào chống thuế năm 1908 cho thấy sức mạnh của người nông dân khi đồng loạt đứng lên, nhưng cũng bộc lộ giới hạn của những cuộc đấu tranh tự phát, thiếu tổ chức chặt chẽ và thiếu đường lối rõ ràng. Với Nguyễn Tất Thành, đó là bài học đầu tiên về đấu tranh của quần chúng. Anh chứng kiến những yêu sách chính đáng bị đáp lại bằng roi vọt, và biết tin những sĩ phu mà anh khâm phục như Phan Châu Trinh bị tù đày. Ba năm sau, ngày 5/6/1911, người thanh niên ấy rời Bến Nhà Rồng ra đi tìm đường cứu nước. Bản báo cáo mật năm 1908 hiện nằm trong hồ sơ số 2554 thuộc phông Tòa Khâm sứ Trung Kỳ, lưu tại Trung tâm Lưu trữ quốc gia IV ở Đà Lạt. Tài liệu được tác giả Thanh Biên dịch toàn văn, giới thiệu trên tạp chí Nghiên cứu lịch sử xứ Quảng và trang thông tin của Trung tâm ngày 11/12/2025. Người đến Huế hôm nay vẫn có thể lần theo dấu những ngày ấy. Cây cầu nơi người biểu tình tụ tập vẫn bắc qua sông Hương (xem chuyên đề Cầu Trường Tiền và sông Hương), còn làng Dương Nỗ vẫn giữ ngôi nhà lưu niệm."},{"t":"Các mốc thời gian. 11/3/1908: Nông dân Quảng Nam kéo về tỉnh lỵ Hội An đòi giảm lao dịch và thuế. 9/4/1908: Nông dân phía nam Thừa Thiên tụ tập ở An Cựu, Cư Chánh, Dương Nỗ. 10/4/1908: Dân làng Công Lương bắt giữ viên Phủ doãn Thừa Thiên. 11/4/1908: Khoảng một nghìn người vây Tòa Khâm sứ; Nguyễn Tất Thành làm phiên dịch cho nông dân. 12/4/1908: Lính thủy quân lục chiến bắt 34 người ở Công Lương. 13/4/1908: Người biểu tình tụ tập trên cầu Thành Thái; đồn cảnh sát ở chợ bị tấn công. 15/4/1908: Người biểu tình rút về Phú Bài rồi trở về làng."}],"so_chu":2067},{"i":10,"tieu_de_bang":"Cầu Trường Tiền và sông Hương","tieu_de":"Cầu Trường Tiền: sáu nhịp thép, bốn lần đổi tên, một dòng sông chứng nhân","sapo":"Tháng 3/1897, muốn vào gặp vua Thành Thái, Toàn quyền Đông Dương Paul Doumer vẫn phải vượt sông Hương bằng tàu. Ba năm sau, một cây cầu thép sáu nhịp vắt ngang dòng sông, mang niên hiệu nhà vua. Cây cầu ấy từng bị bão quật gãy, hai lần bị đánh sập, bốn lần đổi tên. Và mùa xuân năm 1908, chính trên mặt cầu, những đoàn nông dân chống thuế đã tụ lại giữa kinh đô.","bia":{"src":"textures/bai/G02_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Kinh đô qua sông bằng đò","text":"Suốt nhiều thế kỷ, người Huế qua sông Hương bằng đò ngang. Khi Toàn quyền Đông Dương Paul Doumer đến Huế tháng 3/1897, quan lại triều đình ở bờ bắc, quan chức Tòa Khâm sứ ở bờ nam và dân chúng đều qua lại bằng đò. Chính ông, khi vào gặp vua Thành Thái, cũng phải vượt sông bằng chiếc tàu của Tòa Khâm sứ. Dòng sông không chỉ ngăn đôi triều đình Nguyễn với bộ máy bảo hộ, mà còn cắt ngang con đường thiên lý Bắc – Nam.\n\nÝ định bắc một cây cầu sắt đã có từ trước. Ngày 11/8/1896, Viện Cơ mật tâu vua việc Tòa Khâm sứ bàn làm cầu sắt qua sông trước Kinh thành. Sách Đại Nam thực lục chép lời chỉ dụ của vua Thành Thái: “Chính trị nhân đức không gì quan trọng bằng gia ân cho dân”. Dự tính ban đầu là một cây cầu rộng 5 thước 2 tấc, chi phí khoảng 190.000 đồng. Doumer đề nghị làm rộng hơn, chịu tốn một lần để yên ổn lâu dài. Đầu năm 1898, chi phí ước lên khoảng 500.000 đồng; phần vượt dự toán do chính quyền bảo hộ bù.","doc":1},{"loai":"doan","tieu_de":"Không phải Eiffel","text":"Nhiều sách báo, cả từ điển, từng viết cầu Trường Tiền do hãng Eiffel xây dựng. Tài liệu lưu trữ của Pháp cho thấy không phải vậy. Ngày 26/5/1897, Doumer phê duyệt chương trình và thông số kỹ thuật để đấu thầu cây cầu. Ủy ban xét thầu do Khâm sứ Trung Kỳ làm chủ tịch, đại thần Nguyễn Thân làm phó chủ tịch, họp tại Huế ngày 15/10/1897 để xem xét năm hồ sơ dự thầu.\n\nNgười thắng thầu là liên danh Schneider et Cie và Letellier, với số tiền được phép chi hơn 723.800 franc. Công trình chính thức giao cho nhà thầu ngày 23/11/1897. Schneider là tập đoàn công nghiệp lớn ở Le Creusot, còn Letellier từng thi công nhà máy nước Yên Phụ ở Hà Nội. Công ty kế tục hãng Eiffel lúc ấy mang tên Société de Constructions de Levallois-Perret, cũng dự thầu nhưng bị loại. Chuyện này được làm rõ nhờ nhà nghiên cứu Tim Doling và loạt bài của báo Tuổi Trẻ năm 2021, dựa trên Công báo Đông Dương năm 1897. Dấu ấn Eiffel chỉ đến với cây cầu mấy chục năm sau, qua những lần đại tu.","doc":2},{"loai":"doan","tieu_de":"Cầu Thành Thái ra đời","text":"Cây cầu xây xong năm nào? Ba nguồn chính thống ghi ba mốc khác nhau. Sách Đại Nam nhất thống chí ghi cầu xây năm 1897, xong năm 1899, và nhiều tài liệu phổ thông vẫn theo mốc này. Sách Đại Nam thực lục ghi khởi công tháng 11/1898, khánh thành tháng 11/1900. Còn báo cáo của Toàn quyền Doumer ghi khởi công tháng 5/1899, hoàn thành tháng 10/1900, thông xe ngày 18/12/1900. Phó giáo sư Đỗ Bang cho rằng cầu do người Pháp trực tiếp thi công, nên căn cứ vào tài liệu của Pháp là phù hợp hơn.\n\nCuối năm 1900, vua Thành Thái và Toàn quyền Doumer dự lễ khánh thành. Người Pháp lấy niên hiệu nhà vua đặt tên là cầu Thành Thái. Cầu có sáu nhịp dầm thép, mỗi nhịp dài khoảng 67 mét, tựa trên năm trụ và hai mố. Trên mỗi nhịp có hai vì thép cong hình vành lược, người Huế gọi là “vài”. Đây là cây cầu đầu tiên bắc qua sông Hương, nối Kinh thành ở bờ bắc với khu Tòa Khâm sứ và các cơ quan bảo hộ ở bờ nam.","doc":3},{"loai":"anh","src":"textures/bang_w/G02_10_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Cầu Trường Tiền và sông Hương”, nhìn từ xa."},{"loai":"ban_co_biet","text":"Câu ca dao “Cầu Trường Tiền sáu vài mười hai nhịp” thực ra nói ngược: cầu có sáu nhịp, mỗi nhịp hai vài, tức sáu nhịp mười hai vài.","nguon_ten":"Sở Giao thông vận tải Thừa Thiên Huế; Từ điển tiếng Việt, Hoàng Phê chủ biên; dẫn theo Minh Tự, loạt bài “Trường Tiền – chuyện chưa kể cây cầu lịch sử”, báo Tuổi Trẻ, 8/2021","doc":4},{"loai":"doan","tieu_de":"Cơn bão năm Giáp Thìn","text":"Chưa đầy bốn năm sau, cây cầu gặp tai họa. Sáng 11/9/1904, tức mồng 2 tháng 8 năm Giáp Thìn, một cơn bão lớn đổ bộ kinh đô. Sách Đại Nam thực lục chép rằng nước dâng ngập cung điện và quan thự, cột cờ trên Kỳ Đài gãy ngang, cầu sắt sông Hương cũng bị trôi đổ. Bốn nhịp cầu bị bật khỏi trụ. Theo lời kể dân gian do học giả Phan Văn Dật thu thập, hai vài bị hất ra giữa sông, ngang trước chợ Đông Ba, một vài bị cuốn xuống tận Bãi Dâu, cách gần ba cây số.\n\nPhóng viên Alfred Raquez, có mặt ở Huế, viết trên tờ L’Avenir du Tonkin ngày 23/9/1904 rằng cơn bão cướp đi sinh mạng của khoảng 3.000 người bản xứ. Vợ chồng du khách người Pháp J. Pannier kịp chụp lại cảnh cầu gãy, nay là tư liệu hiếm hoi về trận bão. Tương truyền, lúc xây cầu, viên Khâm sứ từng nói với vua rằng bao giờ cầu gãy thì nước Pháp trả lại nước An Nam. Năm 1906, hãng Daydé et Pillé, khi ấy đang làm cầu đường sắt ở Huế, được mời làm lại bốn nhịp, mặt cầu đúc bê tông.","doc":5},{"loai":"doan","tieu_de":"Cây cầu trong những năm Huế của người học trò","text":"Cuối tháng 5/1906, khi Nguyễn Tất Thành theo cha trở lại Huế, bốn nhịp cầu vừa được làm lại. Ông Nguyễn Sinh Sắc được cấp một căn phòng ở dãy nhà dành cho thuộc viên các bộ, thường gọi là Dãy Trại, trên đường Đông Ba, nay là đường Mai Thúc Loan. Trường tiểu học Pháp – Việt nơi hai anh em theo học nằm sát ngoài cửa Đông Ba, cách nhà chừng hai trăm mét, không xa khu chợ Đông Ba ở đầu cầu phía bắc. Từ tháng 9/1908, anh vào Quốc Học ở bờ nam. Tư liệu không ghi lại anh thường sang sông qua cầu hay bằng đò.\n\nNăm 1907, vua Thành Thái bị chính quyền bảo hộ ép thoái vị. Cây cầu vẫn mang tên ông thêm mười hai năm nữa, như một nghịch lý giữa kinh đô. Tháng 4/1908, cây cầu trở thành nơi tụ họp của những người nông dân chống thuế. Báo cáo của Công sứ Thừa Thiên ghi rằng sáng 13/4/1908, các nhóm biểu tình tập trung trên cầu Thành Thái và đại lộ dẫn ra ga (xem chuyên đề Phong trào chống sưu thuế 1908).","doc":6},{"loai":"anh","src":"textures/ht/ht_anh_quoc_hoc_hue.jpg","chu_thich":"Trường Quốc Học Huế bên bờ sông Hương, ảnh chụp năm 2008.","credit":"Ảnh: Lưu Ly · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Bốn lần đổi tên","text":"Từ ngày 14/7/1919, theo nghị định của quyền Toàn quyền Đông Dương Montguillot, cầu Thành Thái đổi thành cầu Clémenceau, tên vị Thủ tướng vừa đưa nước Pháp thắng trận trong Chiến tranh thế giới thứ nhất. Người Huế thì chẳng mấy ai biết ông là ai. Tháng 5/1945, sau khi Nhật đảo chính Pháp, nội các Trần Trọng Kim chủ trương thay tên Pháp bằng tên Việt, và cầu được đổi thành cầu Nguyễn Hoàng. Tên gọi này rất ít được nhắc đến. Các văn bản của chính quyền cách mạng và sách báo về sau đều gọi là cầu Trường Tiền.\n\nCái tên dân gian ấy có trước cây cầu. Theo Từ điển nhà Nguyễn của Võ Hương An, năm 1775, sau khi chiếm thành Phú Xuân, chúa Trịnh cho lập xưởng đúc tiền ở bờ bắc sông Hương, cách cửa Thượng Tứ khoảng 500 mét. Xưởng đúc tiền gọi là trường tiền, bến đò bên cạnh gọi là bến đò Trường Tiền, và cây cầu dựng ở chỗ bến đò cũng mang luôn tên ấy.","doc":7},{"loai":"ban_co_biet","text":"Sau lần khôi phục năm 1995, hai tấm biển đồng ở hai đầu cầu ghi nhầm là “Tràng Tiền”, có lẽ lẫn với địa danh ở Hà Nội. Tháng 10/2017, cầu mới được trả lại đúng tên Trường Tiền.","nguon_ten":"Minh Tự, loạt bài “Trường Tiền – chuyện chưa kể cây cầu lịch sử”, báo Tuổi Trẻ, 8/2021","doc":8},{"loai":"doan","tieu_de":"Cuộc đại tu 1937 – 1939","text":"Đến những năm 1930, nhiều khung sắt dưới gầm cầu đã bị gỉ sét nặng. Chính quyền bảo hộ thương lượng với hãng kế tục Eiffel, lúc ấy mang tên Société des Anciens Établissements Eiffel. Cuộc đại tu khởi công ngày 20/6/1937, kéo dài 29 tháng, hoàn tất ngày 29/11/1939, tốn khoảng 433.000 franc. Toàn bộ bề rộng 5,6 mét giữa hai hàng vài được dành cho xe cộ. Lối đi bộ chuyển ra phía ngoài, mỗi bên rộng 1,95 mét, có bao lơn ngắm cảnh ở chỗ các trụ. Các vài được nắn lại cho đều và thon thả hơn. Đó là hình hài cây cầu mà người Huế quen thuộc đến ngày nay. Báo Tràng An ở Huế theo dõi sát công trình, và có một nhận xét đến nay vẫn đáng suy ngẫm.","doc":9},{"loai":"trich","text":"Mỗi khi chúng ta để chân lên chiếc cầu rộng rãi tốt đẹp ấy, thì cũng nên nhớ rằng nó là một công trình vĩ đại của chánh phủ Bảo hộ, và cũng là vật cấu tạo của hàng ngàn, hàng vạn, hàng ức, hàng triệu giọt mồ hôi, nước mắt của chúng ta.","nguoi":"Báo Tràng An (Huế), năm 1939","nguon_ten":"Dẫn theo Minh Tự, loạt bài “Trường Tiền – chuyện chưa kể cây cầu lịch sử”, báo Tuổi Trẻ, 8/2021","doc":10},{"loai":"doan","tieu_de":"Những vết thương chiến tranh","text":"Rạng sáng 20/12/1946, khi cuộc kháng chiến toàn quốc bùng nổ, Mặt trận Huế nổ súng lúc 2 giờ 30 phút. Theo kế hoạch tác chiến, công binh trung đoàn Trần Cao Vân do đại đội trưởng Lê Vừa chỉ huy đã đánh sập cầu để chặn quân Pháp đóng ở bờ nam. Thuốc nổ lấy từ những quả thủy lôi phát xít Nhật bỏ lại, mỗi quả nặng khoảng 500 ki-lô-gam. Ba nhịp phía bắc bị phá hủy. Năm 1948, quân Pháp nối tạm bằng dầm sắt lát ván. Những năm 1953 – 1954, hãng kế tục Eiffel khôi phục ba nhịp này.\n\nTết Mậu Thân 1968, đơn vị đặc công K14 chở mười quả bom, mỗi quả nặng một tấn, gài vào nhịp số 4, để chặn xe tăng Mỹ và quân đội Việt Nam Cộng hòa từ bờ nam tiến vào Thành Nội. Trụ số 3 bị phá hủy hoàn toàn, nhịp số 4 đổ sập. Năm 1969, cầu được nối tạm, nhưng suốt 27 năm sau đó cây cầu khuyết một cặp vài, như một vết thương chưa lành.","doc":11},{"loai":"anh","src":"textures/bang_w/G02_10_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Cầu Trường Tiền và sông Hương”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Trả lại chiếc lược ngà cho dòng Hương","text":"Năm 1990, cầu xuống cấp nghiêm trọng, phải cấm xe cơ giới từ tháng 9. Ngày 18/5/1991, Bộ Giao thông vận tải khởi công sửa chữa, khôi phục cầu. Thép cho nhịp số 4 được chế tạo tại Pháp theo đúng hình dáng cũ, rồi đưa về Huế lắp ráp. Thợ Việt Nam tán khoảng 15 vạn đinh tán, riêng nhịp số 4 khoảng 11 vạn. Ngày 19/5/1995, đúng ngày sinh Chủ tịch Hồ Chí Minh, cầu khánh thành, lại đủ sáu nhịp mười hai vài. Tháng 10/2017, đơn vị quản lý cầu khôi phục lan can với mười bao lơn ngắm cảnh như dáng cầu sau cuộc đại tu 1937 – 1939.\n\nNgày nay, cây cầu là hình ảnh gắn với Huế hơn cả, được chiếu sáng nghệ thuật về đêm và là sân khấu của nhiều lễ hội. Đầu cầu phía nam gặp đường Lê Lợi chạy dọc bờ sông, trên đó có Trường Quốc Học. Đầu cầu phía bắc là khu chợ Đông Ba, gần những con phố người học trò năm xưa từng sống. Trong không gian 3D của gian trưng bày, cầu sáu nhịp hiện ra ở phía đông, bên kia sân trường, như câu thơ Nguyễn Bính: “Cầu cong như chiếc lược ngà, sông dài mái tóc cung nga buông hờ”.","doc":12},{"loai":"anh","src":"textures/bang_w/G02_10_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Cầu Trường Tiền và sông Hương”, nhìn từ trên cao."},{"loai":"ban_co_biet","text":"Công ty kế tục hãng Eiffel dự thầu năm 1897 bị loại, chỉ được thưởng 2.000 franc cho bản đồ án. Những bản vẽ ấy về sau thường bị nhầm là thiết kế gốc của cầu Trường Tiền.","nguon_ten":"Công báo Đông Dương năm 1897, nghị định số 1205; dẫn theo Minh Tự, loạt bài “Trường Tiền – chuyện chưa kể cây cầu lịch sử”, báo Tuổi Trẻ, 8/2021","doc":13},{"loai":"moc","items":[["11/8/1896","Viện Cơ mật tâu vua việc làm cầu sắt qua sông Hương"],["23/11/1897","Công trình giao cho liên danh Schneider et Cie và Letellier"],["5/1899","Khởi công, theo báo cáo của Toàn quyền Doumer"],["18/12/1900","Cầu Thành Thái thông xe"],["11/9/1904","Bão Giáp Thìn quật đổ bốn nhịp"],["1906","Hãng Daydé et Pillé làm lại bốn nhịp; Nguyễn Tất Thành trở lại Huế"],["13/4/1908","Người biểu tình chống thuế tụ tập trên cầu"],["14/7/1919","Đổi tên thành cầu Clémenceau"],["1937 – 1939","Đại tu, mở lối đi bộ hai bên"],["5/1945","Đổi tên thành cầu Nguyễn Hoàng"],["20/12/1946","Cầu bị đánh sập ba nhịp phía bắc"],["1968","Tết Mậu Thân, cầu bị đánh sập trụ số 3 và nhịp số 4"],["19/5/1995","Khánh thành sau khôi phục"],["10/2017","Khôi phục bao lơn và đúng tên Trường Tiền"]],"doc":14}],"nguon":["Minh Tự, loạt bài “Trường Tiền – chuyện chưa kể cây cầu lịch sử”, báo Tuổi Trẻ, 8/2021 – https://tuoitre.vn/truong-tien-chuyen-chua-ke-cay-cau-lich-su-ky-1-nhip-cau-noi-duong-thien-ly-2021080321280859.htm ; https://tuoitre.vn/truong-tien-chuyen-chua-ke-cay-cau-lich-su-ky-2-di-tim-tac-gia-cau-truong-tien-20210804211450528.htm ; https://tuoitre.vn/truong-tien-chuyen-chua-ke-cay-cau-lich-su-ky-3-chiec-cau-truan-chuyen-20210805203202752.htm","Báo Tuổi Trẻ, kỳ 4 và kỳ 5 của loạt bài trên – https://tuoitre.vn/truong-tien-chuyen-chua-ke-cay-cau-lich-su-ky-4-su-that-dau-an-eiffel-20210806224701246.htm ; https://tuoitre.vn/truong-tien-chuyen-chua-ke-cay-cau-lich-su-ky-5-tra-chiec-luoc-nga-cho-huong-giang-20210807202748209.htm","VnExpress, “Cầu Trường Tiền từng sập do bão lớn 120 năm trước” – https://vnexpress.net/cau-truong-tien-tung-sap-do-bao-lon-120-nam-truoc-4960658.html","Thanh Biên (Trung tâm Lưu trữ quốc gia IV), “Phong trào chống thuế tại Huế năm 1908 qua báo cáo của người Pháp”, mocban.vn, 11/12/2025 – https://mocban.vn/phong-trao-chong-thue-tai-hue-nam-1908-qua-bao-cao-cua-nguoi-phap/","Báo Tuổi Trẻ, “Nguyễn Tất Thành ra đi từ ngôi trường xứ Huế”, 5/2/2018 – https://tuoitre.vn/nguyen-tat-thanh-ra-di-tu-ngoi-truong-xu-hue-20180205104555229.htm","Bảo tàng Hồ Chí Minh, Hồ Chí Minh – Tiểu sử, NXB Chính trị quốc gia, 2008"],"doc":[{"t":"Cầu Trường Tiền: sáu nhịp thép, bốn lần đổi tên, một dòng sông chứng nhân. Tháng 3/1897, muốn vào gặp vua Thành Thái, Toàn quyền Đông Dương Paul Doumer vẫn phải vượt sông Hương bằng tàu. Ba năm sau, một cây cầu thép sáu nhịp vắt ngang dòng sông, mang niên hiệu nhà vua. Cây cầu ấy từng bị bão quật gãy, hai lần bị đánh sập, bốn lần đổi tên. Và mùa xuân năm 1908, chính trên mặt cầu, những đoàn nông dân chống thuế đã tụ lại giữa kinh đô."},{"t":"Kinh đô qua sông bằng đò. Suốt nhiều thế kỷ, người Huế qua sông Hương bằng đò ngang. Khi Toàn quyền Đông Dương Paul Doumer đến Huế tháng 3/1897, quan lại triều đình ở bờ bắc, quan chức Tòa Khâm sứ ở bờ nam và dân chúng đều qua lại bằng đò. Chính ông, khi vào gặp vua Thành Thái, cũng phải vượt sông bằng chiếc tàu của Tòa Khâm sứ. Dòng sông không chỉ ngăn đôi triều đình Nguyễn với bộ máy bảo hộ, mà còn cắt ngang con đường thiên lý Bắc – Nam. Ý định bắc một cây cầu sắt đã có từ trước. Ngày 11/8/1896, Viện Cơ mật tâu vua việc Tòa Khâm sứ bàn làm cầu sắt qua sông trước Kinh thành. Sách Đại Nam thực lục chép lời chỉ dụ của vua Thành Thái: “Chính trị nhân đức không gì quan trọng bằng gia ân cho dân”. Dự tính ban đầu là một cây cầu rộng 5 thước 2 tấc, chi phí khoảng 190.000 đồng. Doumer đề nghị làm rộng hơn, chịu tốn một lần để yên ổn lâu dài. Đầu năm 1898, chi phí ước lên khoảng 500.000 đồng; phần vượt dự toán do chính quyền bảo hộ bù."},{"t":"Không phải Eiffel. Nhiều sách báo, cả từ điển, từng viết cầu Trường Tiền do hãng Eiffel xây dựng. Tài liệu lưu trữ của Pháp cho thấy không phải vậy. Ngày 26/5/1897, Doumer phê duyệt chương trình và thông số kỹ thuật để đấu thầu cây cầu. Ủy ban xét thầu do Khâm sứ Trung Kỳ làm chủ tịch, đại thần Nguyễn Thân làm phó chủ tịch, họp tại Huế ngày 15/10/1897 để xem xét năm hồ sơ dự thầu. Người thắng thầu là liên danh Schneider et Cie và Letellier, với số tiền được phép chi hơn 723.800 franc. Công trình chính thức giao cho nhà thầu ngày 23/11/1897. Schneider là tập đoàn công nghiệp lớn ở Le Creusot, còn Letellier từng thi công nhà máy nước Yên Phụ ở Hà Nội. Công ty kế tục hãng Eiffel lúc ấy mang tên Société de Constructions de Levallois-Perret, cũng dự thầu nhưng bị loại. Chuyện này được làm rõ nhờ nhà nghiên cứu Tim Doling và loạt bài của báo Tuổi Trẻ năm 2021, dựa trên Công báo Đông Dương năm 1897. Dấu ấn Eiffel chỉ đến với cây cầu mấy chục năm sau, qua những lần đại tu."},{"t":"Cầu Thành Thái ra đời. Cây cầu xây xong năm nào? Ba nguồn chính thống ghi ba mốc khác nhau. Sách Đại Nam nhất thống chí ghi cầu xây năm 1897, xong năm 1899, và nhiều tài liệu phổ thông vẫn theo mốc này. Sách Đại Nam thực lục ghi khởi công tháng 11/1898, khánh thành tháng 11/1900. Còn báo cáo của Toàn quyền Doumer ghi khởi công tháng 5/1899, hoàn thành tháng 10/1900, thông xe ngày 18/12/1900. Phó giáo sư Đỗ Bang cho rằng cầu do người Pháp trực tiếp thi công, nên căn cứ vào tài liệu của Pháp là phù hợp hơn. Cuối năm 1900, vua Thành Thái và Toàn quyền Doumer dự lễ khánh thành. Người Pháp lấy niên hiệu nhà vua đặt tên là cầu Thành Thái. Cầu có sáu nhịp dầm thép, mỗi nhịp dài khoảng 67 mét, tựa trên năm trụ và hai mố. Trên mỗi nhịp có hai vì thép cong hình vành lược, người Huế gọi là “vài”. Đây là cây cầu đầu tiên bắc qua sông Hương, nối Kinh thành ở bờ bắc với khu Tòa Khâm sứ và các cơ quan bảo hộ ở bờ nam."},{"t":"Bạn có biết? Câu ca dao “Cầu Trường Tiền sáu vài mười hai nhịp” thực ra nói ngược: cầu có sáu nhịp, mỗi nhịp hai vài, tức sáu nhịp mười hai vài."},{"t":"Cơn bão năm Giáp Thìn. Chưa đầy bốn năm sau, cây cầu gặp tai họa. Sáng 11/9/1904, tức mồng 2 tháng 8 năm Giáp Thìn, một cơn bão lớn đổ bộ kinh đô. Sách Đại Nam thực lục chép rằng nước dâng ngập cung điện và quan thự, cột cờ trên Kỳ Đài gãy ngang, cầu sắt sông Hương cũng bị trôi đổ. Bốn nhịp cầu bị bật khỏi trụ. Theo lời kể dân gian do học giả Phan Văn Dật thu thập, hai vài bị hất ra giữa sông, ngang trước chợ Đông Ba, một vài bị cuốn xuống tận Bãi Dâu, cách gần ba cây số. Phóng viên Alfred Raquez, có mặt ở Huế, viết trên tờ L’Avenir du Tonkin ngày 23/9/1904 rằng cơn bão cướp đi sinh mạng của khoảng 3.000 người bản xứ. Vợ chồng du khách người Pháp J. Pannier kịp chụp lại cảnh cầu gãy, nay là tư liệu hiếm hoi về trận bão. Tương truyền, lúc xây cầu, viên Khâm sứ từng nói với vua rằng bao giờ cầu gãy thì nước Pháp trả lại nước An Nam. Năm 1906, hãng Daydé et Pillé, khi ấy đang làm cầu đường sắt ở Huế, được mời làm lại bốn nhịp, mặt cầu đúc bê tông."},{"t":"Cây cầu trong những năm Huế của người học trò. Cuối tháng 5/1906, khi Nguyễn Tất Thành theo cha trở lại Huế, bốn nhịp cầu vừa được làm lại. Ông Nguyễn Sinh Sắc được cấp một căn phòng ở dãy nhà dành cho thuộc viên các bộ, thường gọi là Dãy Trại, trên đường Đông Ba, nay là đường Mai Thúc Loan. Trường tiểu học Pháp – Việt nơi hai anh em theo học nằm sát ngoài cửa Đông Ba, cách nhà chừng hai trăm mét, không xa khu chợ Đông Ba ở đầu cầu phía bắc. Từ tháng 9/1908, anh vào Quốc Học ở bờ nam. Tư liệu không ghi lại anh thường sang sông qua cầu hay bằng đò. Năm 1907, vua Thành Thái bị chính quyền bảo hộ ép thoái vị. Cây cầu vẫn mang tên ông thêm mười hai năm nữa, như một nghịch lý giữa kinh đô. Tháng 4/1908, cây cầu trở thành nơi tụ họp của những người nông dân chống thuế. Báo cáo của Công sứ Thừa Thiên ghi rằng sáng 13/4/1908, các nhóm biểu tình tập trung trên cầu Thành Thái và đại lộ dẫn ra ga (xem chuyên đề Phong trào chống sưu thuế 1908)."},{"t":"Bốn lần đổi tên. Từ ngày 14/7/1919, theo nghị định của quyền Toàn quyền Đông Dương Montguillot, cầu Thành Thái đổi thành cầu Clémenceau, tên vị Thủ tướng vừa đưa nước Pháp thắng trận trong Chiến tranh thế giới thứ nhất. Người Huế thì chẳng mấy ai biết ông là ai. Tháng 5/1945, sau khi Nhật đảo chính Pháp, nội các Trần Trọng Kim chủ trương thay tên Pháp bằng tên Việt, và cầu được đổi thành cầu Nguyễn Hoàng. Tên gọi này rất ít được nhắc đến. Các văn bản của chính quyền cách mạng và sách báo về sau đều gọi là cầu Trường Tiền. Cái tên dân gian ấy có trước cây cầu. Theo Từ điển nhà Nguyễn của Võ Hương An, năm 1775, sau khi chiếm thành Phú Xuân, chúa Trịnh cho lập xưởng đúc tiền ở bờ bắc sông Hương, cách cửa Thượng Tứ khoảng 500 mét. Xưởng đúc tiền gọi là trường tiền, bến đò bên cạnh gọi là bến đò Trường Tiền, và cây cầu dựng ở chỗ bến đò cũng mang luôn tên ấy."},{"t":"Bạn có biết? Sau lần khôi phục năm 1995, hai tấm biển đồng ở hai đầu cầu ghi nhầm là “Tràng Tiền”, có lẽ lẫn với địa danh ở Hà Nội. Tháng 10/2017, cầu mới được trả lại đúng tên Trường Tiền."},{"t":"Cuộc đại tu 1937 – 1939. Đến những năm 1930, nhiều khung sắt dưới gầm cầu đã bị gỉ sét nặng. Chính quyền bảo hộ thương lượng với hãng kế tục Eiffel, lúc ấy mang tên Société des Anciens Établissements Eiffel. Cuộc đại tu khởi công ngày 20/6/1937, kéo dài 29 tháng, hoàn tất ngày 29/11/1939, tốn khoảng 433.000 franc. Toàn bộ bề rộng 5,6 mét giữa hai hàng vài được dành cho xe cộ. Lối đi bộ chuyển ra phía ngoài, mỗi bên rộng 1,95 mét, có bao lơn ngắm cảnh ở chỗ các trụ. Các vài được nắn lại cho đều và thon thả hơn. Đó là hình hài cây cầu mà người Huế quen thuộc đến ngày nay. Báo Tràng An ở Huế theo dõi sát công trình, và có một nhận xét đến nay vẫn đáng suy ngẫm."},{"t":"Mỗi khi chúng ta để chân lên chiếc cầu rộng rãi tốt đẹp ấy, thì cũng nên nhớ rằng nó là một công trình vĩ đại của chánh phủ Bảo hộ, và cũng là vật cấu tạo của hàng ngàn, hàng vạn, hàng ức, hàng triệu giọt mồ hôi, nước mắt của chúng ta. — Báo Tràng An (Huế), năm 1939"},{"t":"Những vết thương chiến tranh. Rạng sáng 20/12/1946, khi cuộc kháng chiến toàn quốc bùng nổ, Mặt trận Huế nổ súng lúc 2 giờ 30 phút. Theo kế hoạch tác chiến, công binh trung đoàn Trần Cao Vân do đại đội trưởng Lê Vừa chỉ huy đã đánh sập cầu để chặn quân Pháp đóng ở bờ nam. Thuốc nổ lấy từ những quả thủy lôi phát xít Nhật bỏ lại, mỗi quả nặng khoảng 500 ki-lô-gam. Ba nhịp phía bắc bị phá hủy. Năm 1948, quân Pháp nối tạm bằng dầm sắt lát ván. Những năm 1953 – 1954, hãng kế tục Eiffel khôi phục ba nhịp này. Tết Mậu Thân 1968, đơn vị đặc công K14 chở mười quả bom, mỗi quả nặng một tấn, gài vào nhịp số 4, để chặn xe tăng Mỹ và quân đội Việt Nam Cộng hòa từ bờ nam tiến vào Thành Nội. Trụ số 3 bị phá hủy hoàn toàn, nhịp số 4 đổ sập. Năm 1969, cầu được nối tạm, nhưng suốt 27 năm sau đó cây cầu khuyết một cặp vài, như một vết thương chưa lành."},{"t":"Trả lại chiếc lược ngà cho dòng Hương. Năm 1990, cầu xuống cấp nghiêm trọng, phải cấm xe cơ giới từ tháng 9. Ngày 18/5/1991, Bộ Giao thông vận tải khởi công sửa chữa, khôi phục cầu. Thép cho nhịp số 4 được chế tạo tại Pháp theo đúng hình dáng cũ, rồi đưa về Huế lắp ráp. Thợ Việt Nam tán khoảng 15 vạn đinh tán, riêng nhịp số 4 khoảng 11 vạn. Ngày 19/5/1995, đúng ngày sinh Chủ tịch Hồ Chí Minh, cầu khánh thành, lại đủ sáu nhịp mười hai vài. Tháng 10/2017, đơn vị quản lý cầu khôi phục lan can với mười bao lơn ngắm cảnh như dáng cầu sau cuộc đại tu 1937 – 1939. Ngày nay, cây cầu là hình ảnh gắn với Huế hơn cả, được chiếu sáng nghệ thuật về đêm và là sân khấu của nhiều lễ hội. Đầu cầu phía nam gặp đường Lê Lợi chạy dọc bờ sông, trên đó có Trường Quốc Học. Đầu cầu phía bắc là khu chợ Đông Ba, gần những con phố người học trò năm xưa từng sống. Trong không gian 3D của gian trưng bày, cầu sáu nhịp hiện ra ở phía đông, bên kia sân trường, như câu thơ Nguyễn Bính: “Cầu cong như chiếc lược ngà, sông dài mái tóc cung nga buông hờ”."},{"t":"Bạn có biết? Công ty kế tục hãng Eiffel dự thầu năm 1897 bị loại, chỉ được thưởng 2.000 franc cho bản đồ án. Những bản vẽ ấy về sau thường bị nhầm là thiết kế gốc của cầu Trường Tiền."},{"t":"Các mốc thời gian. 11/8/1896: Viện Cơ mật tâu vua việc làm cầu sắt qua sông Hương. 23/11/1897: Công trình giao cho liên danh Schneider et Cie và Letellier. 5/1899: Khởi công, theo báo cáo của Toàn quyền Doumer. 18/12/1900: Cầu Thành Thái thông xe. 11/9/1904: Bão Giáp Thìn quật đổ bốn nhịp. 1906: Hãng Daydé et Pillé làm lại bốn nhịp; Nguyễn Tất Thành trở lại Huế. 13/4/1908: Người biểu tình chống thuế tụ tập trên cầu. 14/7/1919: Đổi tên thành cầu Clémenceau. 1937 – 1939: Đại tu, mở lối đi bộ hai bên. 5/1945: Đổi tên thành cầu Nguyễn Hoàng. 20/12/1946: Cầu bị đánh sập ba nhịp phía bắc. 1968: Tết Mậu Thân, cầu bị đánh sập trụ số 3 và nhịp số 4. 19/5/1995: Khánh thành sau khôi phục. 10/2017: Khôi phục bao lơn và đúng tên Trường Tiền."}],"so_chu":1939}],"do_vat":[{"id":"blackboard@0.0,42.9","x":0,"y":1.65,"z":42.85,"loai":"blackboard","ten":"Bảng đen lớp học Quốc Học","tieu_de":"Tấm bảng của một ngôi trường Pháp – Việt","text":"Tấm bảng đen dựng trong không gian 3D là vật minh họa, không phải hiện vật gốc: một khung gỗ sơn đen, mặt bảng phủ lớp sơn nhám để viết phấn, đặt trên giá ba chân hoặc gắn tường theo đúng kiểu lớp học Pháp – Việt phổ biến ở Đông Dương đầu thế kỷ XX. Trước tấm bảng ấy, thầy giáo giảng bài chủ yếu bằng tiếng Pháp, thỉnh thoảng viết thêm chữ quốc ngữ hoặc vài chữ Hán để đối chiếu; học trò ngồi thành hàng, tay cầm bút sắt chấm mực hoặc phấn trắng, chép lại từng dòng chữ La tinh còn xa lạ với phần đông con em nhà nho.\n\nTrường Quốc Học Huế, nơi tấm bảng này gợi nhớ, được triều đình và chính quyền bảo hộ lập ra từ ngày 23 tháng 10 năm 1896, ban đầu nhằm đào tạo đội ngũ thông ngôn, viên chức cho bộ máy cai trị. Đây là trường Pháp – Việt lớn nhất xứ Trung Kỳ, cổng trường hai tầng còn khắc dòng chữ Hán \"Quốc Học\". Chương trình học gồm Pháp văn, quốc ngữ, một ít Hán văn, toán và thể dục — một sự pha trộn hoàn toàn khác với lối học cử nghiệp chữ Hán mà phần lớn học trò từng quen thuộc trước đó.\n\nNăm 1906, ông Nguyễn Sinh Sắc nhận chức Thừa biện Bộ Lễ, đưa hai con trai Nguyễn Sinh Khiêm và Nguyễn Tất Thành vào Huế lần thứ hai. Tất Thành học Trường Tiểu học Pháp – Việt Đông Ba. Vốn tiếng Pháp tích lũy trước những tấm bảng như thế đã đủ để tháng 4/1908, người học trò trẻ làm phiên dịch giúp đoàn nông dân chống sưu thuế kéo đến trước Tòa Khâm sứ ở Huế, và từ đó lọt vào tầm theo dõi của mật thám Pháp. Theo tư liệu lưu trữ Pháp, ngày 7/8/1908 hiệu trưởng Quốc Học nhận lời tiếp nhận học sinh Nguyễn Sinh Côn; tháng 9/1908 anh vào Quốc Học và học ở đây đến khoảng tháng 4–5/1909.\n\nKhông dừng lại ở đó, thứ tiếng Pháp học được nơi lớp học Quốc Học còn theo Người suốt chặng đường sau: những năm bôn ba, viết báo, hoạt động ở Pháp, rồi soạn thảo văn kiện, tiếp xúc ngoại giao quốc tế, đều bắt đầu từ vốn liếng gây dựng trên ghế nhà trường xứ Huế.\n\nMột buổi học ở Quốc Học thời ấy thường mở đầu bằng giờ Pháp văn: đọc chính tả, chia động từ, rồi tới giờ toán, sử - địa và một ít giờ thể dục theo kiểu nhà trường phương Tây; chữ Hán chỉ còn được dạy như một môn phụ, khác hẳn thời cha ông toàn tâm học chữ thánh hiền để đi thi Hương, thi Hội. Học trò Quốc Học phần nhiều là con em quan lại, nhà khá giả trong vùng; để được nhận vào trường, gia đình phải có chút thế lực hoặc quen biết — trường hợp của Nguyễn Tất Thành có phần thuận lợi hơn nhờ người cha vừa đỗ Phó bảng, đang làm việc trong triều.\n\nTrường Quốc Học ngày nay vẫn đứng bên bờ sông Hương, đối diện Kỳ Đài và tường thành Kinh thành Huế, được xếp hạng di tích lịch sử quốc gia. Trong sân trường có bức tượng người học trò Nguyễn Tất Thành; những dãy lớp học mái ngói đỏ vẫn giữ dáng vẻ một ngôi trường trăm năm tuổi, dù nội thất lớp học nguyên bản của niên khóa 1908 – 1909 không còn được lưu giữ. Tấm bảng đen trong không gian phục dựng vì thế chỉ là hình ảnh gợi nhắc, giúp người xem hình dung lại khung cảnh học tập mà cậu học trò xứ Nghệ từng trải qua trước khi bước vào những năm tháng tìm đường cứu nước.","nguon":"Hồ Chí Minh – Biên niên tiểu sử, tập 1; Bảo tàng Hồ Chí Minh","doc":[{"t":"Tấm bảng của một ngôi trường Pháp – Việt. Tấm bảng đen dựng trong không gian 3D là vật minh họa, không phải hiện vật gốc: một khung gỗ sơn đen, mặt bảng phủ lớp sơn nhám để viết phấn, đặt trên giá ba chân hoặc gắn tường theo đúng kiểu lớp học Pháp – Việt phổ biến ở Đông Dương đầu thế kỷ XX. Trước tấm bảng ấy, thầy giáo giảng bài chủ yếu bằng tiếng Pháp, thỉnh thoảng viết thêm chữ quốc ngữ hoặc vài chữ Hán để đối chiếu; học trò ngồi thành hàng, tay cầm bút sắt chấm mực hoặc phấn trắng, chép lại từng dòng chữ La tinh còn xa lạ với phần đông con em nhà nho."},{"t":"Trường Quốc Học Huế, nơi tấm bảng này gợi nhớ, được triều đình và chính quyền bảo hộ lập ra từ ngày 23 tháng 10 năm 1896, ban đầu nhằm đào tạo đội ngũ thông ngôn, viên chức cho bộ máy cai trị. Đây là trường Pháp – Việt lớn nhất xứ Trung Kỳ, cổng trường hai tầng còn khắc dòng chữ Hán \"Quốc Học\". Chương trình học gồm Pháp văn, quốc ngữ, một ít Hán văn, toán và thể dục — một sự pha trộn hoàn toàn khác với lối học cử nghiệp chữ Hán mà phần lớn học trò từng quen thuộc trước đó."},{"t":"Năm 1906, ông Nguyễn Sinh Sắc nhận chức Thừa biện Bộ Lễ, đưa hai con trai Nguyễn Sinh Khiêm và Nguyễn Tất Thành vào Huế lần thứ hai. Tất Thành học Trường Tiểu học Pháp – Việt Đông Ba. Vốn tiếng Pháp tích lũy trước những tấm bảng như thế đã đủ để tháng 4/1908, người học trò trẻ làm phiên dịch giúp đoàn nông dân chống sưu thuế kéo đến trước Tòa Khâm sứ ở Huế, và từ đó lọt vào tầm theo dõi của mật thám Pháp. Theo tư liệu lưu trữ Pháp, ngày 7/8/1908 hiệu trưởng Quốc Học nhận lời tiếp nhận học sinh Nguyễn Sinh Côn; tháng 9/1908 anh vào Quốc Học và học ở đây đến khoảng tháng 4–5/1909."},{"t":"Không dừng lại ở đó, thứ tiếng Pháp học được nơi lớp học Quốc Học còn theo Người suốt chặng đường sau: những năm bôn ba, viết báo, hoạt động ở Pháp, rồi soạn thảo văn kiện, tiếp xúc ngoại giao quốc tế, đều bắt đầu từ vốn liếng gây dựng trên ghế nhà trường xứ Huế."},{"t":"Một buổi học ở Quốc Học thời ấy thường mở đầu bằng giờ Pháp văn: đọc chính tả, chia động từ, rồi tới giờ toán, sử - địa và một ít giờ thể dục theo kiểu nhà trường phương Tây; chữ Hán chỉ còn được dạy như một môn phụ, khác hẳn thời cha ông toàn tâm học chữ thánh hiền để đi thi Hương, thi Hội. Học trò Quốc Học phần nhiều là con em quan lại, nhà khá giả trong vùng; để được nhận vào trường, gia đình phải có chút thế lực hoặc quen biết — trường hợp của Nguyễn Tất Thành có phần thuận lợi hơn nhờ người cha vừa đỗ Phó bảng, đang làm việc trong triều."},{"t":"Trường Quốc Học ngày nay vẫn đứng bên bờ sông Hương, đối diện Kỳ Đài và tường thành Kinh thành Huế, được xếp hạng di tích lịch sử quốc gia. Trong sân trường có bức tượng người học trò Nguyễn Tất Thành; những dãy lớp học mái ngói đỏ vẫn giữ dáng vẻ một ngôi trường trăm năm tuổi, dù nội thất lớp học nguyên bản của niên khóa 1908 – 1909 không còn được lưu giữ. Tấm bảng đen trong không gian phục dựng vì thế chỉ là hình ảnh gợi nhắc, giúp người xem hình dung lại khung cảnh học tập mà cậu học trò xứ Nghệ từng trải qua trước khi bước vào những năm tháng tìm đường cứu nước."},{"t":"Bạn có biết? Quốc Học Huế sau này còn là nơi học tập của nhiều nhân vật lịch sử khác như Võ Nguyên Giáp và Phạm Văn Đồng, dù mỗi người theo học cách xa nhiều năm."}],"ban_co_biet":"Quốc Học Huế sau này còn là nơi học tập của nhiều nhân vật lịch sử khác như Võ Nguyên Giáp và Phạm Văn Đồng, dù mỗi người theo học cách xa nhiều năm."},{"id":"schoolDesk@1.5,40.0","x":1.5,"y":0.75,"z":40,"loai":"schoolDesk","ten":"Bàn học trò Quốc Học","tieu_de":"Chưa đầy một năm trên ghế nhà trường","text":"Những dãy bàn gỗ liền ghế xếp thành hàng trong không gian 3D là đồ vật minh họa, phỏng theo kiểu bàn học hai chỗ ngồi phổ biến trong các trường Pháp – Việt đầu thế kỷ XX: mặt bàn nghiêng có rãnh đặt bút và lỗ khoét để đặt lọ mực, ngăn dưới đựng sách vở — một mẫu bàn học kiểu phương Tây hoàn toàn khác với án thư thấp, nghiên mực mài tay của lối học chữ Hán truyền thống mà nhiều học trò từng quen.\n\nTrên chiếc bàn học kiểu ấy, Nguyễn Tất Thành ngồi học tại Trường Quốc Học Huế từ tháng 9/1908 đến khoảng tháng 4–5/1909. Anh theo cha là ông Nguyễn Sinh Sắc ra Huế từ năm 1906, khi ông nhận chức Thừa biện Bộ Lễ, và trước đó đã học ở Trường Tiểu học Pháp – Việt Đông Ba. Đây là quãng thời gian anh vừa học tiếng Pháp, quốc ngữ, vừa được tiếp xúc với sách báo, ý niệm mới của phương Tây mà một nhà nho thuần túy khó có cơ hội chạm tới.\n\nKhoảng thời gian ngồi trên ghế Quốc Học ấy chưa đầy một năm. Trước đó, tháng 4/1908, phong trào chống sưu cao thuế nặng bùng lên khắp Trung Kỳ, từng đoàn nông dân kéo về trước Tòa Khâm sứ Pháp ở Huế để đưa kiến nghị. Khi còn là học sinh Trường Đông Ba, anh đã giúp đoàn biểu tình làm phiên dịch, chuyển đạt nguyện vọng của bà con tới nhà cầm quyền. Từ đó tên anh lọt vào tầm theo dõi của mật thám Pháp — một cái giá phải trả sớm cho tinh thần đứng về phía đồng bào. Nhiều sách trước đây viết rằng anh bị đuổi học vì cuộc biểu tình này; tư liệu lưu trữ công bố về sau cho thấy anh vào Quốc Học sau sự kiện ấy và rời trường khi theo cha vào Bình Định năm 1909.\n\nRời ngôi trường lớn nhất xứ Trung Kỳ, người thanh niên mười chín tuổi không dừng lại. Năm 1909, anh theo cha vào Bình Định, rồi một mình xuôi Phan Thiết dạy học ở Trường Dục Thanh — ngôi trường tư thục do các sĩ phu yêu nước lập ra, nhận cả học trò nghèo — trước khi vào Sài Gòn năm 1911 và bước lên con tàu rời Bến Nhà Rồng (xem chuyên đề về Trường Dục Thanh, Phan Thiết). \"Trường học\" lớn hơn mà anh bước vào sau khi rời Quốc Học chính là cuộc sống của nhân dân và những chặng đường mới, trong nước rồi ra nước ngoài.\n\nCuộc biểu tình năm 1908 cũng để lại một dấu vết khác: từ đó, tên tuổi Nguyễn Tất Thành bắt đầu xuất hiện trong hồ sơ theo dõi của mật thám Pháp ở Trung Kỳ — những trang hồ sơ mà về sau các nhà nghiên cứu tiểu sử của Người phải lần tìm qua nhiều kho lưu trữ để dựng lại từng chặng đường hoạt động thời trẻ.\n\nNhững chiếc bàn nguyên bản của lớp học niên khóa 1908 – 1909 không còn được lưu giữ, nên bàn học trong không gian phục dựng chỉ là vật minh họa. Trường Quốc Học ngày nay vẫn hoạt động bên bờ sông Hương, trong khuôn viên có bức tượng người học trò Nguyễn Tất Thành, nhắc nhớ một trong những học trò nổi tiếng nhất từng ngồi trên những dãy bàn của ngôi trường hơn một trăm hai mươi năm tuổi.","nguon":"Bảo tàng Hồ Chí Minh – Tiểu sử Chủ tịch Hồ Chí Minh; Hồ Chí Minh – Biên niên tiểu sử, tập 1","doc":[{"t":"Chưa đầy một năm trên ghế nhà trường. Những dãy bàn gỗ liền ghế xếp thành hàng trong không gian 3D là đồ vật minh họa, phỏng theo kiểu bàn học hai chỗ ngồi phổ biến trong các trường Pháp – Việt đầu thế kỷ XX: mặt bàn nghiêng có rãnh đặt bút và lỗ khoét để đặt lọ mực, ngăn dưới đựng sách vở — một mẫu bàn học kiểu phương Tây hoàn toàn khác với án thư thấp, nghiên mực mài tay của lối học chữ Hán truyền thống mà nhiều học trò từng quen."},{"t":"Trên chiếc bàn học kiểu ấy, Nguyễn Tất Thành ngồi học tại Trường Quốc Học Huế từ tháng 9/1908 đến khoảng tháng 4–5/1909. Anh theo cha là ông Nguyễn Sinh Sắc ra Huế từ năm 1906, khi ông nhận chức Thừa biện Bộ Lễ, và trước đó đã học ở Trường Tiểu học Pháp – Việt Đông Ba. Đây là quãng thời gian anh vừa học tiếng Pháp, quốc ngữ, vừa được tiếp xúc với sách báo, ý niệm mới của phương Tây mà một nhà nho thuần túy khó có cơ hội chạm tới."},{"t":"Khoảng thời gian ngồi trên ghế Quốc Học ấy chưa đầy một năm. Trước đó, tháng 4/1908, phong trào chống sưu cao thuế nặng bùng lên khắp Trung Kỳ, từng đoàn nông dân kéo về trước Tòa Khâm sứ Pháp ở Huế để đưa kiến nghị. Khi còn là học sinh Trường Đông Ba, anh đã giúp đoàn biểu tình làm phiên dịch, chuyển đạt nguyện vọng của bà con tới nhà cầm quyền. Từ đó tên anh lọt vào tầm theo dõi của mật thám Pháp — một cái giá phải trả sớm cho tinh thần đứng về phía đồng bào. Nhiều sách trước đây viết rằng anh bị đuổi học vì cuộc biểu tình này; tư liệu lưu trữ công bố về sau cho thấy anh vào Quốc Học sau sự kiện ấy và rời trường khi theo cha vào Bình Định năm 1909."},{"t":"Rời ngôi trường lớn nhất xứ Trung Kỳ, người thanh niên mười chín tuổi không dừng lại. Năm 1909, anh theo cha vào Bình Định, rồi một mình xuôi Phan Thiết dạy học ở Trường Dục Thanh — ngôi trường tư thục do các sĩ phu yêu nước lập ra, nhận cả học trò nghèo — trước khi vào Sài Gòn năm 1911 và bước lên con tàu rời Bến Nhà Rồng (xem chuyên đề về Trường Dục Thanh, Phan Thiết). \"Trường học\" lớn hơn mà anh bước vào sau khi rời Quốc Học chính là cuộc sống của nhân dân và những chặng đường mới, trong nước rồi ra nước ngoài."},{"t":"Cuộc biểu tình năm 1908 cũng để lại một dấu vết khác: từ đó, tên tuổi Nguyễn Tất Thành bắt đầu xuất hiện trong hồ sơ theo dõi của mật thám Pháp ở Trung Kỳ — những trang hồ sơ mà về sau các nhà nghiên cứu tiểu sử của Người phải lần tìm qua nhiều kho lưu trữ để dựng lại từng chặng đường hoạt động thời trẻ."},{"t":"Những chiếc bàn nguyên bản của lớp học niên khóa 1908 – 1909 không còn được lưu giữ, nên bàn học trong không gian phục dựng chỉ là vật minh họa. Trường Quốc Học ngày nay vẫn hoạt động bên bờ sông Hương, trong khuôn viên có bức tượng người học trò Nguyễn Tất Thành, nhắc nhớ một trong những học trò nổi tiếng nhất từng ngồi trên những dãy bàn của ngôi trường hơn một trăm hai mươi năm tuổi."},{"t":"Bạn có biết? Rời Quốc Học, Nguyễn Tất Thành từng trở lại với việc dạy học một thời gian ngắn tại Trường Dục Thanh, Phan Thiết, trước khi vào Sài Gòn năm 1911."}],"ban_co_biet":"Rời Quốc Học, Nguyễn Tất Thành từng trở lại với việc dạy học một thời gian ngắn tại Trường Dục Thanh, Phan Thiết, trước khi vào Sài Gòn năm 1911."},{"id":"schoolDesk@-1.6,40.0","x":-1.6,"y":0.75,"z":40,"loai":"schoolDesk","ten":"Bàn học trò Quốc Học","tieu_de":"Từ chữ Hán sang chữ Pháp","text":"Cũng như những dãy bàn khác trong không gian phục dựng, chiếc bàn học liền ghế này là đồ vật minh họa lớp học kiểu Pháp – Việt, không phải hiện vật gốc. Nhưng câu chuyện gắn với nó lại bắt đầu từ một nền học vấn khác hẳn: trước khi ngồi vào bàn ghế kiểu phương Tây, Nguyễn Tất Thành đã trải qua nhiều năm học chữ Hán theo lối cổ truyền — ngồi án thư thấp, mài mực, tập viết bằng bút lông trên giấy bản, học từ Tam tự kinh đến Tứ thư, Ngũ kinh.\n\nNăm 1898, khi cha là ông Nguyễn Sinh Sắc nhận dạy học ở làng Dương Nỗ ven Huế, hai anh em Nguyễn Sinh Khiêm và Nguyễn Tất Thành theo cha học chữ Hán tại đó. Về sau, khi gia đình trở lại làng Sen, Nam Đàn sau khi bà Hoàng Thị Loan qua đời năm 1901, cậu bé còn theo học các thầy đồ yêu nước trong vùng, trong đó có thầy Vương Thúc Quý — con trai cử nhân Vương Thúc Mậu, người từng lãnh đạo phong trào Cần Vương ở Nam Đàn. Nhà thầy Quý cũng là nơi các sĩ phu như Phan Bội Châu, Đặng Thái Thân thường lui tới bàn việc nước.\n\nLối học chữ Hán ấy đề cao việc thuộc lòng kinh sách, luyện chữ đẹp và học làm văn theo khuôn mẫu bát cổ — mục đích cuối cùng là đi thi Hương, thi Hội để ra làm quan. Chính người cha, ông Nguyễn Sinh Sắc, cũng đi trọn con đường ấy: đỗ Cử nhân ở quê, rồi đỗ Phó bảng năm 1901 sau nhiều lần thi Hội. Nhưng ông cũng là người sớm nhận ra thế cuộc đã đổi khác, nên không ngăn các con tiếp cận với chữ Pháp, chữ quốc ngữ khi có dịp.\n\nNăm 1906, theo cha ra Huế lần thứ hai, Nguyễn Tất Thành chuyển sang học ở Trường Tiểu học Pháp – Việt Đông Ba rồi Trường Quốc Học. Bàn ghế xếp hàng thay án thư, bút sắt và mực tím thay bút lông, giờ học tiếng Pháp thay giờ bình văn chữ Hán — đó là cánh cửa mở ra một thế giới hoàn toàn khác: thế giới của sách báo, tư tưởng phương Tây mà nhà nho thuần túy khó tiếp cận.\n\nNhưng vốn chữ Hán những năm tháng trước không hề mất đi, mà trở thành một phần hành trang tri thức của Người. Về sau, trong thời gian bị chính quyền Tưởng Giới Thạch giam giữ ở Quảng Tây các năm 1942 – 1943, Người vẫn làm hơn một trăm bài thơ chữ Hán, tập hợp thành tập \"Nhật ký trong tù\" — minh chứng cho nền Hán học vững vàng có được từ thời thơ ấu, song hành cùng vốn tiếng Pháp thông thạo học được từ những năm ngồi ghế Quốc Học.\n\nLàng Dương Nỗ ngày nay vẫn là một địa danh gắn với thời niên thiếu của Người tại Thừa Thiên Huế; Trường Quốc Học vẫn đứng bên bờ sông Hương, cách đó không xa. Hai nơi chốn ấy, một gắn với chữ Hán thuở nhỏ, một gắn với chữ Pháp thời thiếu niên, cùng nằm trong một vùng đất kinh kỳ mà Người đã đi qua hai lần trong đời niên thiếu. Chiếc bàn học trong không gian 3D, vì vậy, không tái hiện một đồ vật cụ thể nào còn lưu giữ, mà là hình ảnh gợi lại bước chuyển từ nền học vấn cũ sang nền học vấn mới trong cuộc đời một con người.","nguon":"Hồ Chí Minh Toàn tập; Hồ Chí Minh – Biên niên tiểu sử, tập 1; Khu Di tích Kim Liên","doc":[{"t":"Từ chữ Hán sang chữ Pháp. Cũng như những dãy bàn khác trong không gian phục dựng, chiếc bàn học liền ghế này là đồ vật minh họa lớp học kiểu Pháp – Việt, không phải hiện vật gốc. Nhưng câu chuyện gắn với nó lại bắt đầu từ một nền học vấn khác hẳn: trước khi ngồi vào bàn ghế kiểu phương Tây, Nguyễn Tất Thành đã trải qua nhiều năm học chữ Hán theo lối cổ truyền — ngồi án thư thấp, mài mực, tập viết bằng bút lông trên giấy bản, học từ Tam tự kinh đến Tứ thư, Ngũ kinh."},{"t":"Năm 1898, khi cha là ông Nguyễn Sinh Sắc nhận dạy học ở làng Dương Nỗ ven Huế, hai anh em Nguyễn Sinh Khiêm và Nguyễn Tất Thành theo cha học chữ Hán tại đó. Về sau, khi gia đình trở lại làng Sen, Nam Đàn sau khi bà Hoàng Thị Loan qua đời năm 1901, cậu bé còn theo học các thầy đồ yêu nước trong vùng, trong đó có thầy Vương Thúc Quý — con trai cử nhân Vương Thúc Mậu, người từng lãnh đạo phong trào Cần Vương ở Nam Đàn. Nhà thầy Quý cũng là nơi các sĩ phu như Phan Bội Châu, Đặng Thái Thân thường lui tới bàn việc nước."},{"t":"Lối học chữ Hán ấy đề cao việc thuộc lòng kinh sách, luyện chữ đẹp và học làm văn theo khuôn mẫu bát cổ — mục đích cuối cùng là đi thi Hương, thi Hội để ra làm quan. Chính người cha, ông Nguyễn Sinh Sắc, cũng đi trọn con đường ấy: đỗ Cử nhân ở quê, rồi đỗ Phó bảng năm 1901 sau nhiều lần thi Hội. Nhưng ông cũng là người sớm nhận ra thế cuộc đã đổi khác, nên không ngăn các con tiếp cận với chữ Pháp, chữ quốc ngữ khi có dịp."},{"t":"Năm 1906, theo cha ra Huế lần thứ hai, Nguyễn Tất Thành chuyển sang học ở Trường Tiểu học Pháp – Việt Đông Ba rồi Trường Quốc Học. Bàn ghế xếp hàng thay án thư, bút sắt và mực tím thay bút lông, giờ học tiếng Pháp thay giờ bình văn chữ Hán — đó là cánh cửa mở ra một thế giới hoàn toàn khác: thế giới của sách báo, tư tưởng phương Tây mà nhà nho thuần túy khó tiếp cận."},{"t":"Nhưng vốn chữ Hán những năm tháng trước không hề mất đi, mà trở thành một phần hành trang tri thức của Người. Về sau, trong thời gian bị chính quyền Tưởng Giới Thạch giam giữ ở Quảng Tây các năm 1942 – 1943, Người vẫn làm hơn một trăm bài thơ chữ Hán, tập hợp thành tập \"Nhật ký trong tù\" — minh chứng cho nền Hán học vững vàng có được từ thời thơ ấu, song hành cùng vốn tiếng Pháp thông thạo học được từ những năm ngồi ghế Quốc Học."},{"t":"Làng Dương Nỗ ngày nay vẫn là một địa danh gắn với thời niên thiếu của Người tại Thừa Thiên Huế; Trường Quốc Học vẫn đứng bên bờ sông Hương, cách đó không xa. Hai nơi chốn ấy, một gắn với chữ Hán thuở nhỏ, một gắn với chữ Pháp thời thiếu niên, cùng nằm trong một vùng đất kinh kỳ mà Người đã đi qua hai lần trong đời niên thiếu. Chiếc bàn học trong không gian 3D, vì vậy, không tái hiện một đồ vật cụ thể nào còn lưu giữ, mà là hình ảnh gợi lại bước chuyển từ nền học vấn cũ sang nền học vấn mới trong cuộc đời một con người."},{"t":"Bạn có biết? \"Nhật ký trong tù\" gồm hơn một trăm bài thơ chữ Hán, được Người sáng tác trong thời gian bị giam giữ ở Quảng Tây (Trung Quốc) các năm 1942 – 1943."}],"ban_co_biet":"\"Nhật ký trong tù\" gồm hơn một trăm bài thơ chữ Hán, được Người sáng tác trong thời gian bị giam giữ ở Quảng Tây (Trung Quốc) các năm 1942 – 1943."},{"id":"schoolDesk@4.6,40.0","x":4.6,"y":0.75,"z":40,"loai":"schoolDesk","ten":"Bàn học trò Quốc Học","tieu_de":"Lời tương truyền của cụ Phó bảng về chốn quan trường","text":"Chiếc bàn học trong không gian 3D là đồ vật minh họa lớp học Quốc Học, nơi con trai cụ Phó bảng Nguyễn Sinh Sắc theo học những năm cuối thập niên 1900. Nhưng câu chuyện đọng lại quanh chiếc bàn này lại không phải chuyện học chữ, mà là chuyện về thái độ của người cha đối với chốn quan trường mà ông từng bước chân vào.\n\nÔng Nguyễn Sinh Sắc đỗ Phó bảng khoa thi Hội năm 1901, nhưng phải đến năm 1906 mới ra Huế nhận chức Thừa biện Bộ Lễ — một chức quan nhỏ, lo việc giấy tờ, nghi lễ trong Bộ Lễ của triều đình — đưa hai con trai Nguyễn Sinh Khiêm và Nguyễn Tất Thành theo cùng để ăn học. Khoảng cách năm năm giữa việc đỗ đạt và việc ra làm quan cho thấy một sự chần chừ, dùng dằng của ông trước con đường hoạn lộ mà nhiều nhà nho đương thời coi là đích đến vinh hiển nhất; với một người từng chứng kiến cảnh mất nước, hoạn lộ ấy không còn nguyên vẹn sức hấp dẫn như trước.\n\nVề thái độ ấy, dân gian vùng Nam Đàn truyền lại một câu nói được cho là của cụ Phó bảng: \"Quan trường thị nô lệ trung chi nô lệ, hựu nô lệ\" — chốn quan trường là nô lệ trong đám nô lệ, lại còn nô lệ hơn. Đây chỉ là lời tương truyền, được biết đến qua lời kể truyền miệng chứ chưa tìm thấy trong văn bản do chính ông để lại, nên cần đọc như một giai thoại phản ánh cách nhìn của ông về việc làm quan dưới chế độ bảo hộ, hơn là một câu nói đã được xác thực chữ nghĩa chính xác.\n\nGiai thoại ấy phần nào ăn khớp với những gì xảy ra sau này: năm 1910, khi giữ chức tri huyện Bình Khê, ông Nguyễn Sinh Sắc bị triều đình cách chức sau một vụ xử phạt liên quan đến một cường hào địa phương. Rời quan trường, ông vào Nam Bộ, sống những năm cuối đời ở vùng Sa Đéc, Cao Lãnh, làm nghề dạy học và bốc thuốc cho dân nghèo cho đến khi qua đời năm 1929. Cách sống ấy của người cha — không màng danh vọng chốn quan trường, gần gũi với dân — để lại dấu ấn không nhỏ trong cách nhìn của người con về sau.\n\nBản thân Nguyễn Tất Thành, sau khi rời Quốc Học năm 1908 rồi rời Việt Nam năm 1911, cũng không bao giờ đi theo con đường khoa cử, làm quan như phần lớn bạn học cùng lứa mơ ước. Từ người phụ bếp trên tàu viễn dương đến người viết báo, người hoạt động cách mạng ở nước ngoài, con đường ông chọn khác hẳn con đường của cha — nhưng tinh thần không cam chịu phận \"nô lệ trong đám nô lệ\" mà giai thoại trên nhắc tới, theo nhiều nhà nghiên cứu tiểu sử, đã âm thầm được tiếp nối theo một cách khác.\n\nNhững chiếc bàn học trong không gian 3D chỉ là vật minh họa, không phải hiện vật của gia đình để lại. Trường Quốc Học, nơi hai con trai ông Sắc từng theo học, ngày nay vẫn còn đó bên bờ sông Hương, trong khi câu chuyện về người cha thanh liêm vẫn được nhắc lại như một phần bối cảnh hun đúc nên tính cách của người học trò Nguyễn Tất Thành.","nguon":"Giai thoại lưu truyền về cụ Phó bảng Nguyễn Sinh Sắc (Khu Di tích Kim Liên); Hồ Chí Minh – Biên niên tiểu sử, tập 1","doc":[{"t":"Lời tương truyền của cụ Phó bảng về chốn quan trường. Chiếc bàn học trong không gian 3D là đồ vật minh họa lớp học Quốc Học, nơi con trai cụ Phó bảng Nguyễn Sinh Sắc theo học những năm cuối thập niên 1900. Nhưng câu chuyện đọng lại quanh chiếc bàn này lại không phải chuyện học chữ, mà là chuyện về thái độ của người cha đối với chốn quan trường mà ông từng bước chân vào."},{"t":"Ông Nguyễn Sinh Sắc đỗ Phó bảng khoa thi Hội năm 1901, nhưng phải đến năm 1906 mới ra Huế nhận chức Thừa biện Bộ Lễ — một chức quan nhỏ, lo việc giấy tờ, nghi lễ trong Bộ Lễ của triều đình — đưa hai con trai Nguyễn Sinh Khiêm và Nguyễn Tất Thành theo cùng để ăn học. Khoảng cách năm năm giữa việc đỗ đạt và việc ra làm quan cho thấy một sự chần chừ, dùng dằng của ông trước con đường hoạn lộ mà nhiều nhà nho đương thời coi là đích đến vinh hiển nhất; với một người từng chứng kiến cảnh mất nước, hoạn lộ ấy không còn nguyên vẹn sức hấp dẫn như trước."},{"t":"Về thái độ ấy, dân gian vùng Nam Đàn truyền lại một câu nói được cho là của cụ Phó bảng: \"Quan trường thị nô lệ trung chi nô lệ, hựu nô lệ\" — chốn quan trường là nô lệ trong đám nô lệ, lại còn nô lệ hơn. Đây chỉ là lời tương truyền, được biết đến qua lời kể truyền miệng chứ chưa tìm thấy trong văn bản do chính ông để lại, nên cần đọc như một giai thoại phản ánh cách nhìn của ông về việc làm quan dưới chế độ bảo hộ, hơn là một câu nói đã được xác thực chữ nghĩa chính xác."},{"t":"Giai thoại ấy phần nào ăn khớp với những gì xảy ra sau này: năm 1910, khi giữ chức tri huyện Bình Khê, ông Nguyễn Sinh Sắc bị triều đình cách chức sau một vụ xử phạt liên quan đến một cường hào địa phương. Rời quan trường, ông vào Nam Bộ, sống những năm cuối đời ở vùng Sa Đéc, Cao Lãnh, làm nghề dạy học và bốc thuốc cho dân nghèo cho đến khi qua đời năm 1929. Cách sống ấy của người cha — không màng danh vọng chốn quan trường, gần gũi với dân — để lại dấu ấn không nhỏ trong cách nhìn của người con về sau."},{"t":"Bản thân Nguyễn Tất Thành, sau khi rời Quốc Học năm 1908 rồi rời Việt Nam năm 1911, cũng không bao giờ đi theo con đường khoa cử, làm quan như phần lớn bạn học cùng lứa mơ ước. Từ người phụ bếp trên tàu viễn dương đến người viết báo, người hoạt động cách mạng ở nước ngoài, con đường ông chọn khác hẳn con đường của cha — nhưng tinh thần không cam chịu phận \"nô lệ trong đám nô lệ\" mà giai thoại trên nhắc tới, theo nhiều nhà nghiên cứu tiểu sử, đã âm thầm được tiếp nối theo một cách khác."},{"t":"Những chiếc bàn học trong không gian 3D chỉ là vật minh họa, không phải hiện vật của gia đình để lại. Trường Quốc Học, nơi hai con trai ông Sắc từng theo học, ngày nay vẫn còn đó bên bờ sông Hương, trong khi câu chuyện về người cha thanh liêm vẫn được nhắc lại như một phần bối cảnh hun đúc nên tính cách của người học trò Nguyễn Tất Thành."},{"t":"Bạn có biết? Năm 1910, ông Nguyễn Sinh Sắc bị triều đình cách chức tri huyện Bình Khê; sau đó ông vào Nam Bộ, sống bằng nghề dạy học và bốc thuốc cho đến khi mất năm 1929."}],"ban_co_biet":"Năm 1910, ông Nguyễn Sinh Sắc bị triều đình cách chức tri huyện Bình Khê; sau đó ông vào Nam Bộ, sống bằng nghề dạy học và bốc thuốc cho đến khi mất năm 1929."}]};
